    racetext: {get: function() { return this.GetRacetext(); }, configurable: true},
    cdef: {get: function() { return (this.param(3) + this.param(5)) * 0.5; }, configurable: true}, // Combined Defense of regular Defense and Magical Defense
    catk: {get: function() { return (this.param(2) + this.param(4)) * 0.5; }, configurable: true}, // Combined Attack of regular Attack and Magical Attack
    patk: {get: function() { return this.param(2); }, configurable: true}, // ATtacK power
    pdef: {get: function() { return this.param(3); }, configurable: true}, // DEFense power
    matk: {get: function() { return this.param(4); }, configurable: true}, // Magic ATtack power
    mdef: {get: function() { return this.param(5); }, configurable: true}, // Magic DeFense power
    patkv: {get: function() { return (1.0-dragon_variance_physical_attack) + (Math.random()*2.0*dragon_variance_physical_attack); }, configurable: true}, // Physical Attack Variance
    matkv: {get: function() { return (1.0-dragon_variance_magical_attack) + (Math.random()*2.0*dragon_variance_magical_attack); }, configurable: true}, // Physical Attack Variance
    pdefv: {get: function() { return (1.0-dragon_variance_physical_defense) + (Math.random()*2.0*dragon_variance_physical_defense); }, configurable: true}, // Physical Defense Variance
    mdefv: {get: function() { return (1.0-dragon_variance_magical_defense) + (Math.random()*2.0*dragon_variance_magical_defense); }, configurable: true}, // Magical Defense Variance
    sa1: {get: function() { return 1.0*((1.0-dragon_variance_physical_attack) + (Math.random()*2.0*dragon_variance_physical_attack)); }, configurable: true}, // Static Physical Damage Attack, with variance
    pa1: {get: function() { return this.param(2) * ((1.0-dragon_variance_physical_attack) + (Math.random()*2.0*dragon_variance_physical_attack)); }, configurable: true}, // Physical Attack, with variance
    ma1: {get: function() { return this.param(4) * ((1.0 - dragon_variance_magical_attack) + (Math.random() * 2.00000 * dragon_variance_magical_attack)); }, configurable: true}, // Magical Attack, with variance
    ca1: {get: function() { return (this.param(2).Vary(dragon_variance_physical_attack)+this.param(4).Vary(dragon_variance_magical_attack))*0.5; }, configurable: true}, // Combined Attack, with variance
    pd1: {get: function() { return this.param(3).Vary(dragon_variance_physical_defense); }, configurable: true}, // Physical Defense, with variance
    md1: {get: function() { return this.param(5).Vary(dragon_variance_magical_defense); }, configurable: true}, // Magical Defense, with variance
    cd1: {get: function() { return (this.param(3).Vary(dragon_variance_physical_defense)+this.param(5).Vary(dragon_variance_magical_defense))*0.5; }, configurable: true}, // Combined Defense, with variance
    dmpn: {get: function() { return 1.0-((1.0-Math.pow(this._hp/this.param(0),2.0))*dragon_combat_hp_dampening); }, configurable: true}, // Hit point percentage damage dampening factor, less end-result with fewer HP
    dmpi: {get: function() { return 1.0-(dragon_combat_hp_dampening_inverse*this._hp/this.param(0)); }, configurable: true}, // Hit point percentage damage dampening factor, inverted, less end-result with higher and max HP
    dp: {get: function() { return this.GetDp(); }, configurable: true},
    eq0: {get: function() { return this.e0(800); }, configurable: true},
    eq2: {get: function() { return this.e2(800); }, configurable: true},
    eq3: {get: function() { return this.e3(800); }, configurable: true},
    nrmLvl: {get: function() { return this.GetNormalizedLevel(); }, configurable: true}, // Normalized Level
    hit_rate_physical: {get: function() { return this.GetAtr_HitRatePhysical(); }, configurable: true},
    hit_rate_magical: {get: function() { return this.GetAtr_HitRateMagical(); }, configurable: true},
    health_points: {get: function() { return this._hp; }, configurable: true},
    magic_points: {get: function() { return this._mp; }, configurable: true},
    tactical_points: {get: function() { return this._tp.clamp(0, this.maxTp); }, configurable: true},
    max_tp: {get: function() { return this.maxTp(); }, configurable: true},
    max_tactical_points: {get: function() { return this.maxTp(); }, configurable: true},
    max_health_points: {get: function() { return this.param(0); }, configurable: true},
    orig_mhp: {get: function() { return this.MaximumOriginalHp(); }, configurable: true},
