Game_BattlerBase.prototype.ratio = function(attacker_value, defender_value) {
    var total = attacker_value + defender_value;
    var d = defender_value;
    if ( total > 1 ) {
        d /= total;
    } else {
        d = 1;
    }

    return 1.0 - d;
};
