DgnMapData.prototype.ReadFromMeta = function() {
    this.SetDefaults();

    if ( !$dataMap.meta ) return;
	if ( $dataMap.meta.dgnVehicle ) {
        $gameSystem.inside_vehicle = true;
        $gamePlayer.setTransparent(false);
	}
	else {
        $gameSystem.inside_vehicle = false;
	}
	if ( $dataMap.meta.tMap ) {
        const t_map = JSON.parse( $dataMap.meta.tMap );
        if ( t_map.length > 0 ) $gameVariables.setValue( dragon_variable_game_chapter, t_map[0] );
        if ( t_map.length > 1 ) $gameSystem.treasure_chest_level = Math.round(Math.min(t_map[1] * dragon_level_scaling_factor, 1.0));
        if ( t_map.length > 2 ) $gameSystem.enemy_grade = t_map[2];
	}
	if ( $dataMap.meta.tSkyRegion ) $gameSystem.sky_region = Number( $dataMap.meta.tSkyRegion ).clamp( 0, 255 );
    if ( $dataMap.meta.tEnemyL ) {
        const enemy_levels = JSON.parse( $dataMap.meta.tEnemyL );
        $gameSystem.min_enemy_level = Math.round(Math.min(enemy_levels[0] * dragon_level_scaling_factor, 1.0));
        $gameSystem.max_enemy_level = Math.round(Math.max(enemy_levels[1] * dragon_level_scaling_factor, 25000.0));
        if ( enemy_levels.length > 2 ) $gameSystem.enemy_level_offset = Math.round((enemy_levels[2] * dragon_level_scaling_factor).clamp(-50000.0, 50000.0));
    }
	if ( $dataMap.meta.dgnRegMaxEnemies ) $gameSystem.max_random_enemies = JSON.parse( $dataMap.meta.dgnRegMaxEnemies );
	if ( $dataMap.meta.dgnRegionExp ) $gameSystem.encounter_exp_limit = JSON.parse( $dataMap.meta.dgnRegionExp );
};
