Game_Map.prototype.setup = function(mapId) {
    if (!$dataMap) {
        throw new Error("The map data is not available");
    }
    this._mapId = mapId;
    this._tilesetId = $dataMap.tilesetId;
    this._displayX = 0;
    this._displayY = 0;
    this.refereshVehicles();
    this.setupEvents();
    this.setupScroll();
    this.setupParallax();
    this.setupBattleback();
    this._needsRefresh = false;

    DRAGON_map.ReadFromMeta();
    DRAGON_map.UpdateGameVars();

    DGN.UpdateGlobalData();

    $gameSystem.UpdateEncounterGroups();
};
Game_Map.prototype.createVehicles = function() {
    this._vehicles = [];
    /*
    this._vehicles[0] = new Game_Vehicle("boat");
    this._vehicles[1] = new Game_Vehicle("ship");
    this._vehicles[2] = new Game_Vehicle("airship");
    this._vehicles[3] = new Game_Vehicle("landcraft");
    */

    if ( dragon_vehicles_boat.length > 1 ) {
        for ( let i = 0; i < dragon_vehicles_boat.length; i++ )
            this._vehicles.push( new Game_Vehicle( dragon_vehicles_boat[i].type, dragon_vehicles_boat[i].name ) );
    }
    if ( dragon_vehicles_ship.length > 1 ) {
        for ( let i = 0; i < dragon_vehicles_ship.length; i++ )
            this._vehicles.push( new Game_Vehicle( dragon_vehicles_ship[i].type, dragon_vehicles_ship[i].name ) );
    }
    if ( dragon_vehicles_skycraft.length > 1 ) {
        for ( let i = 0; i < dragon_vehicles_skycraft.length; i++ )
            this._vehicles.push( new Game_Vehicle( dragon_vehicles_skycraft[i].type, dragon_vehicles_skycraft[i].name ) );
    }
    if ( dragon_vehicles_landcraft.length > 1 ) {
        for ( let i = 0; i < dragon_vehicles_landcraft.length; i++ )
            this._vehicles.push( new Game_Vehicle( dragon_vehicles_landcraft[i].type, dragon_vehicles_landcraft[i].name ) );
    }
};
Game_Map.prototype.vehicle = function(type) {
    if (type === 0 || type === "boat") {
        return this.boat();
    } else if (type === 1 || type === "ship") {
        return this.ship();
    } else if (type === 2 || type === "airship") {
        return this.airship();
    } else if ( type < this._vehicles.length ) {
        return this._vehicles[type];
    } else {
        return null;
    }
};
Game_Map.prototype.vehicles = function() {
    return this._vehicles;
};

