DRAGON.prototype.pluginCommand_ClearContentsOfTreasureChests = function(args) {
    for (let i = 0; i < dragon_number_of_random_chests; i++) {
        dragon_Chest[i].Clear();
    }

    dragon_TotalChest.Clear();
};
DRAGON.prototype.pluginCommand_AddItemsToTreasureChest = function(args) {
    const chestIndex = Number(args.ChestIndex);
    const itmCounts = JSON.parse( args.ItemCount );
    const itmChances = JSON.parse( args.ItemChance );
    const itmIds = JSON.parse( args.ItemId );
    const item_level_base = (Number(args.ItemLevel)).clamp( 1, 20 ); // 20 is number of temporary variables, should be 20 regardless of value of dragon_max_item_levels.
    const item_level = ($gameSystem.treasure_chest_level + $gameVariables.value(item_level_base)).clamp( 1, dragon_max_item_levels );
    const numberItems = Math.min( itmCounts.length, itmChances.length, itmIds.length );
    if ( numberItems < 1 ) return;
    if ( chestIndex < 0 ) return;
    if ( chestIndex >= dragon_number_of_random_chests ) return;

    for (let i = 0; i < numberItems; i++) {
        dragon_Chest[chestIndex].AddItem( Number(itmCounts[i]), Number(itmChances[i]), Number(itmIds[i]), item_level );
    }
};
