DRAGON.prototype.pluginCommand_LootChest = function(args) {
    const chestIndex = Math.round(Math.random() * Number(args.ChestIndexMax));
    const chestName = args.ChestName;
    const silent_if_empty = JSON.parse( args.SilentIfEmpty );
    const chance_multiplier = (Number( args.ChanceMultiplier ) * 0.01).clamp( 0, 100 );

    dragon_Chest[chestIndex].Loot(chance_multiplier);
    const totalItems = dragon_Chest[chestIndex].LootSizeItems();
    const totalWeapons = dragon_Chest[chestIndex].LootSizeWeapons();
    const totalArmors = dragon_Chest[chestIndex].LootSizeArmors();
    const totalLoot = dragon_Chest[chestIndex].LootSize();
    const cash = dragon_Chest[chestIndex].cash;
    var msgItems = "";

    if ( totalItems > 0 ) {
        msgItems += "You find: ";
        for (let i = 0; i < totalItems; i++ ) {
            const item = $dataItems[dragon_Chest[chestIndex].loot_id[i]] ? $dataItems[dragon_Chest[chestIndex].loot_id[i]] : 0;
            if ( item == 0 ) continue;

            $gameParty.gainItem( item, dragon_Chest[chestIndex].loot_count[i] );
            const i_reduced = i / 6;
            const msg_line = Math.floor( i_reduced );
            if ( (i_reduced == msg_line) && (msg_line > 0) ) msgItems += "\\LB          ";
            msgItems += ( String(dragon_Chest[chestIndex].loot_count[i]) + "x " + String( item.name ) );
            if ( i < (totalItems - 1) ) msgItems += ", ";
        }
        msgItems += ".";
        if ( (totalWeapons > 0) || (totalArmors > 0) || (cash > 0) ) msgItems += "\\LB";
    }
    if ( totalWeapons > 0 ) {
        msgItems += "You find: ";
        for (let i = 0; i < totalWeapons; i++ ) {
            const item = $dataWeapons[dragon_Chest[chestIndex].loot_id_w[i]] ? $dataWeapons[dragon_Chest[chestIndex].loot_id_w[i]] : 0;
            if ( item == 0 ) continue;

            $gameParty.gainItem( item, dragon_Chest[chestIndex].loot_count_w[i] );
            const i_reduced = i / 6;
            const msg_line = Math.floor( i_reduced );
            if ( (i_reduced == msg_line) && (msg_line > 0) ) msgItems += "\\LB          ";
            msgItems += ( String(dragon_Chest[chestIndex].loot_count_w[i]) + 'x ' + String( item.name ) );
            if ( i < (totalWeapons - 1) ) msgItems += ", ";
        }
        msgItems += ".";
        if ( (totalArmors > 0) || (cash > 0) ) msgItems += "\\LB";
    }
    if ( totalArmors > 0 ) {
        msgItems += "You find: ";
        for (let i = 0; i < totalArmors; i++ ) {
            const item = $dataArmors[dragon_Chest[chestIndex].loot_id_a[i]] ? $dataArmors[dragon_Chest[chestIndex].loot_id_a[i]] : 0;
            if ( item == 0 ) continue;

            $gameParty.gainItem( item, dragon_Chest[chestIndex].loot_count_a[i] );
            const i_reduced = i / 6;
            const msg_line = Math.floor( i_reduced );
            if ( (i_reduced == msg_line) && (msg_line > 0) ) msgItems += "\\LB          ";
            msgItems += ( String(dragon_Chest[chestIndex].loot_count_a[i]) + 'x ' + String( item.name ) );
            if ( i < (totalArmors - 1) ) msgItems += ", ";
        }
        msgItems += ".";
        if ( cash > 0 ) msgItems += "\\LB";
    }
    if ( cash > 0 ) {
        msgItems += "You find: " + cash.toLocaleString() + " GP.";

        $gameParty.gainGold( cash );
    }

    $gameMessage.setBackground(0);
    $gameMessage.setPositionType(2);
    if ( chestName ) $gameMessage.setSpeakerName( chestName );

    if ( totalLoot > 0 ) {
        $gameMessage.add( msgItems );

        Game_Interpreter.prototype.setWaitMode.call(this, 'message');
    }
    else if ( silent_if_empty == false ) {
        $gameMessage.add( "Empty!" );

        Game_Interpreter.prototype.setWaitMode.call(this, 'message');
    }

    dragon_Chest[chestIndex].Empty();
};
