DRAGON.prototype.SetPartyTargetRateMods = function() {
    const party_size = $gameParty.size();
    if (party_size < 2) {
        if ($gameParty.members()[0])
            $gameParty.members()[0].SetTargetRateMod(1.0);
        return;
    }

    for ( let i = 0; i < party_size; i++ ) {
        const mod_amt = Math.round(this.Lerp( 150.00000, 22.50000, i / (party_size - 1.00000) )) * 0.01;
        $gameParty.members()[i].SetTargetRateMod( mod_amt );
    }
};
DRAGON.prototype.ReparseTextAuto = function(input_text, line_max_chars=dragon_string_line_width_noFace) {
    if ( !input_text ) return "";
    const oldText = input_text;
    const oldText_length = oldText.length;
    if ( oldText_length < 1 ) return "";
    var nText = "";
    var lastChar = "";

    // Remove all carriage returns
    for ( let i = 0; i < oldText_length; i++ ) {
        const currentChar = oldText[i];
        if ( currentChar === "\n" ) {
            if ( (lastChar === ".") || (lastChar === "!") || (lastChar === "?") ) {
                nText += "  ";

                lastChar = currentChar;
                continue;
            }

            var will_add_space = true;

            if ( lastChar === "\n" ) will_add_space = false;
            if ( i > 2 ) {
                if ( (oldText[i - 1] == "B") && (oldText[i - 2] == "L") && (oldText[i - 3] == "\\") ) will_add_space = false;
            }
            if ( !lastChar ) will_add_space = false;
            if ( i == 0 ) will_add_space = false;
            if ( lastChar === " " ) will_add_space = false;

            if ( will_add_space == true ) nText += " ";

            lastChar = currentChar;
            continue;
        }

        nText += currentChar;
        lastChar = currentChar;
    }

    var nText2 = "";
    var char_x_count = 0;
    var letter_count = 0;
    var ignore_count = 0;
    const nText_length = nText.length;
    if ( nText_length < 1 ) return "";

    // Put in new line breaks
    for ( let i = 0; i < nText_length; i++ ) {
        const currentChar = nText[i];

        if ( ignore_count > 0 ) {
            ignore_count--;

            continue;
        }

        if ( currentChar === "\\" ) {
            const readAheadLimit = nText_length - (i + 1);
            if ( readAheadLimit < 2 ) break;

            if ( (nText[i + 1] == "L") && (nText[i + 2] == "B") ) {
                // Valid Line Break being inserted, and backslash isn't copied to new string
                nText2 += "\n";
                char_x_count = 0;
                ignore_count = 2;

                continue;
            }
        }

        if ( currentChar === " " ) {
            if ( i >= nText_length - 1 ) {
                nText2 += currentChar;
                char_x_count++;

                continue;
            } else {
                if ( nText[i + 1] !== " " ) {
                    var new_word_started = false;
                    const readAheadLimit = nText_length - (i + 1);
                    if ( readAheadLimit < 1 ) break;
                    var letter_count = 0;

                    for ( readAhead = 1; readAhead < readAheadLimit + 1; readAhead++ ) {
                        if (nText[i + readAhead] === " ") {
                            break;
                        }
                        if (nText[i + readAhead] === "\\") {
                            if ( (readAhead + 1) < readAheadLimit ) {
                                if ( (nText[i + readAhead + 1] === "L") && (nText[i + readAhead + 2] === "B") ) break;
                            }
                        }

                        letter_count++;
                    }

                    if ( letter_count == 0 ) {
                        nText2 += currentChar;
                        char_x_count++;

                        continue;
                    }
                    if ( (letter_count + char_x_count) > line_max_chars ) {
                        nText2 += currentChar;
                        nText2 += "\n";
                        char_x_count = 0;

                        continue;
                    } else {
                        nText2 += currentChar;
                        char_x_count++;

                        continue;
                    }

                } else {
                    nText2 += currentChar;
                    char_x_count++;

                    continue;
                }
            }
        } else {
            nText2 += currentChar;
            char_x_count++;

            continue;
        }
    }

    return nText2;
};
DRAGON.prototype.CalcItemPrice = function(item) {
    if ( !item ) return 0;

    var price = item.price;

    if ( item.food_price )
        price = DGN.CalcFoodPrice( item.food_price );
    else if ( item.leveled_by_chapter_price == true )
        price = DGN.CalcLevelByChapterPrice( price, item.level );

    return Math.ceil( price );
};
DRAGON.prototype.CalcLevelByChapterPrice = function(base_price, item_level) {
    const chapter = Number($gameVariables.value(dragon_variable_game_chapter));

    const item_level_factor = DGN.Lerp( 1.0, 20.0, (item_level.clamp( 1, dragon_max_item_levels ) - 1) / (dragon_max_item_levels - 1) );
    const factor1 = Math.pow( item_level_factor, 3.2 );
    const factor2 = DGN.LerpSkew( 1.0, 16.0, chapter.clamp( 0, dragon_max_chapters ) / dragon_max_chapters, -0.625 );
    const price = base_price * factor1 * factor2;

    return price;
};
DRAGON.prototype.CalcFoodPrice = function(base_price) {
    const chapter = Number($gameVariables.value(dragon_variable_game_chapter));

    const item_level = DGN.Lerp( 1.0, dragon_max_item_levels, chapter / dragon_max_chapters );
    const item_level_factor = DGN.Lerp( 1.0, 20.0, (item_level.clamp( 1, dragon_max_item_levels ) - 1) / (dragon_max_item_levels - 1) );
    const factor1 = Math.pow( item_level_factor, 3.2 );
    const factor2 = DGN.LerpSkew( 1.0, 16.0, chapter.clamp( 0, dragon_max_chapters ) / dragon_max_chapters, -0.625 );
    const price = base_price * factor1 * factor2;

    return price;
};
