DRAGON.prototype.GetSkillTypeNameAuto = function(weapon_type, armor_type, equipment_type) {
    if (weapon_type > 0) {
        return $dataSystem.weaponTypes[weapon_type];
    }
    else if ( equipment_type == DRAGON_INV_SLOT_BOOK ) {
        if ( armor_type == DRAGON_ARMOR_BOOK_SWORDMASTER ) return "Swordmaster Ability";
        else if ( armor_type == DRAGON_ARMOR_BOOK_AXEMASTER ) return "Axemaster Ability";
        else if ( armor_type == DRAGON_ARMOR_BOOK_KENSHI ) return "Kenshi Ability";
        else if ( armor_type == DRAGON_ARMOR_BOOK_NINJA ) return "Ninja Spell";
        else if ( armor_type == DRAGON_ARMOR_BOOK_MARTIAL_ARTIST ) return "Martial Arts Ability";
        else if ( armor_type == DRAGON_ARMOR_BOOK_RIFLEMAN ) return "Rifleman Ability";
        else if ( armor_type == DRAGON_ARMOR_BOOK_CLERIC ) return "Holy Cleric Spell";
        else if ( armor_type == DRAGON_ARMOR_BOOK_MAGE ) return "Mage Spell";
        else if ( armor_type == DRAGON_ARMOR_BOOK_WIZARD ) return "Wizard Spell";
        else if ( armor_type == DRAGON_ARMOR_BOOK_KENSEI ) return "Kensei Ability";
    }
    else if ( equipment_type == DRAGON_INV_SLOT_SHIELD ) {
        if ( armor_type == DRAGON_ARMOR_SHIELD_LIGHT ) return "Light Shield";
        else if ( armor_type == DRAGON_ARMOR_SHIELD_MEDIUM ) return "Medium Shield";
        else if ( armor_type == DRAGON_ARMOR_SHIELD_HEAVY ) return "Heavy Shield";
    }
    else {
        return $dataSystem.equipTypes[equipment_type] + " Power";
    }
    /*
    else if ( equipment_type > DRAGON_INV_SLOT_SHIELD ) {
        return $dataSystem.equipTypes[equipment_type] + " Power";
    }
    */

    return "";
};
DRAGON.prototype.GetWeaponID = function(item_level, weaponTypeText, nameText) {
    const items = $dataWeapons.filter( a => (a) ? (a.level == item_level) : false ).filter( a => DGN.GetIndexForWeaponType(weaponTypeText) == a.weapon_type );
    const item = items.filter( a => a.name.includes(nameText) );

    if (item.length > 0)
        return item[0];

    return null;
};
DRAGON.prototype.GetHalfPhysicalValueForSkill = function(equipTypeText, weaponTypeText, armorTypeText) {
    if ( (equipTypeText === "primary weapon") || (equipTypeText === "weapon") ) {
        if ( weaponTypeText === "staff" ) return 1.72500;
        else if ( weaponTypeText === "grenades" ) return 1.0;

        else return 1.42500;
    }
    else if ( (equipTypeText === "backup") || (equipTypeText === "backup weapon") ) {
        if ( weaponTypeText === "light pistol" ) return 1.42500;
        else if ( weaponTypeText === "heavy pistol" ) return 1.42500;
        else if ( weaponTypeText === "minor spellbook" ) return 1;
        else if ( weaponTypeText === "magic wand" ) return 1;
        else if ( weaponTypeText === "kaiken" ) return 1.42500;
        else if ( weaponTypeText === "whip" ) return 1.42500;

        else return 1;
    }
    else if ( equipTypeText === "book" ) {
        if ( armorTypeText === "martial artist's book" ) return 1.62500;
    }

    return 1.0;
};
DRAGON.prototype.GetAimAdjustForSkill = function(equipTypeText, weaponTypeText, armorTypeText) {
    if ( (equipTypeText === "primary weapon") || (equipTypeText === "weapon") ||
         (equipTypeText === "backup") || (equipTypeText === "backup weapon") ||
         (equipTypeText === "grenades") ) {
        if ( weaponTypeText === "longsword" ) return 1.625;
        if ( weaponTypeText === "dual swords" ) return 0.125;
        if ( weaponTypeText === "greatsword" ) return 0.925;

        if ( weaponTypeText === "hand axe" ) return -0.2;
        if ( weaponTypeText === "dual axes" ) return -1.25;
        if ( weaponTypeText === "battleaxe" ) return -0.75;

        if ( weaponTypeText === "kaiken" ) return 0.625;
        if ( weaponTypeText === "tanto" ) return 0.625;

        if ( weaponTypeText === "katana" ) return 1.6425;
        if ( weaponTypeText === "dual katanas" ) return 0.1425;
        if ( weaponTypeText === "ninjato" ) return 1.6425;
        if ( weaponTypeText === "dual ninjatos" ) return 0.1425;
        if ( weaponTypeText === "nodachi" ) return 0.92425;

        if ( weaponTypeText === "club" ) return 0.75;
        if ( weaponTypeText === "whip" ) return 0.625;

        if ( weaponTypeText === "staff" ) return 4.25;
        if ( weaponTypeText === "magic wand" ) return 1.825;
        if ( weaponTypeText === "minor spellbook" ) return 0.925;

        if ( weaponTypeText === "grenades" ) return 0.75;
        if ( weaponTypeText === "shotgun" ) return 2.5;
        if ( weaponTypeText === "light pistol" ) return 0.625;
        if ( weaponTypeText === "medium pistol" ) return 1.125;
        if ( weaponTypeText === "heavy pistol" ) return 1.425;
        if ( weaponTypeText === "smg" ) return 1.425;
        if ( weaponTypeText === "rifle" ) return 3.0;
        if ( weaponTypeText === "machine gun" ) return 4.0;

        return 0.0;
    }
    else if ( equipTypeText === "book" ) {
        if ( armorTypeText === "cleric's book" ) return 0.825;
        if ( armorTypeText === "mage's book" ) return 1.125;
        if ( armorTypeText === "wizard's book" ) return 0.625;
        if ( armorTypeText === "ninja's book" ) return 0.9625;
        if ( armorTypeText === "martial artist's book" ) return 1.325;

        return 1.0;
    }
    else if ( equipTypeText === "ring" ) {
        return 3.25;
    }

    return 0.0;
};
DRAGON.prototype.GetNumberOfEquipmentUpgrades = function(item) {
    const equip_type = item.equip_type;
    const weapon_type = item.weapon_type;
    let upgrades = 0;

    if (equip_type == DRAGON_INV_SLOT_WEAPON) upgrades = 6;
    else if (equip_type == DRAGON_INV_SLOT_BACKUP_WEAPON) upgrades = 4;
    else if (equip_type == DRAGON_INV_SLOT_GRENADES) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_BOOK) upgrades = 12;
    else if (equip_type == DRAGON_INV_SLOT_SHIELD) upgrades = 6;
    else if (equip_type == DRAGON_INV_SLOT_TORSO) upgrades = 10;
    else if (equip_type == DRAGON_INV_SLOT_LEGS) upgrades = 8;
    else if (equip_type == DRAGON_INV_SLOT_FEET) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_HEAD) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_FACE) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_HANDS) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_SHIRT) upgrades = 3;
    else if (equip_type == DRAGON_INV_SLOT_JACKET) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_CLOAK) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_BELT) upgrades = 6;
    else if (equip_type == DRAGON_INV_SLOT_NECKLACE) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_WRISTBAND) upgrades = 4;
    else if (equip_type == DRAGON_INV_SLOT_BRACELET) upgrades = 4;
    else if (equip_type == DRAGON_INV_SLOT_RING) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_EARRING) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_EAR_CUFF) upgrades = 4;
    else if (equip_type == DRAGON_INV_SLOT_SOCKS) upgrades = 4;
    else if (equip_type == DRAGON_INV_SLOT_ACCESSORY) upgrades = 0;
    else if (equip_type == DRAGON_INV_SLOT_TOOTH) upgrades = 5;
    else if (equip_type == DRAGON_INV_SLOT_FACE_PIERCING) upgrades = 6;
    else if (equip_type == DRAGON_INV_SLOT_BODY_PIERCING) upgrades = 6;
    else if (equip_type == DRAGON_INV_SLOT_MAGIC_BODY_ART) upgrades = 5;

    if (DGN.IsDualWeapon(item)) upgrades = 9;
    if (DGN.IsTwoHandedWeapon(item)) upgrades = 12;
    if (weapon_type == DRAGON_WEAPON_KAIKEN) upgrades = 3;
    if (weapon_type == DRAGON_WEAPON_TANTO) upgrades = 5;
    if (weapon_type == DRAGON_WEAPON_CLUB) upgrades = 5;
    if (weapon_type == DRAGON_WEAPON_WHIP) upgrades = 8;
    if (weapon_type == DRAGON_WEAPON_MAGIC_STAFF) upgrades = 12;
    if (weapon_type == DRAGON_WEAPON_MAGIC_WAND) upgrades = 9;
    if (weapon_type == DRAGON_WEAPON_MINOR_SPELLBOOK) upgrades = 12;
    if (weapon_type == DRAGON_WEAPON_SHOTGUN) upgrades = 4;
    if (weapon_type == DRAGON_WEAPON_LIGHT_PISTOL) upgrades = 4;
    if (weapon_type == DRAGON_WEAPON_MEDIUM_PISTOL) upgrades = 5;
    if (weapon_type == DRAGON_WEAPON_HEAVY_PISTOL) upgrades = 6;
    if (weapon_type == DRAGON_WEAPON_SMG) upgrades = 6;
    if (weapon_type == DRAGON_WEAPON_ASSAULT_RIFLE) upgrades = 10;
    if (weapon_type == DRAGON_WEAPON_MACHINE_GUN) upgrades = 12;

    if (DGN.IsElemental(item) || DGN.IsSpecialWeapon(item)) upgrades += 3;
    if (DGN.IsNotSoldInStores(item)) upgrades += 3;

    return upgrades;
};
