DRAGON.prototype.GetDiscoveredActors = function() {
    return $dataActors.filter( actor => (this.IsActorDiscovered(actor)) );
};
DRAGON.prototype.GetDiscoveredEnemies = function() {
    const discovered_enemies = $dataEnemies.filter( enemy => (this.IsEnemyDiscovered(enemy)) );

    return DGN.DeepCopy(discovered_enemies).sort( (a, b) => ((a.params[0] != b.params[0]) ? (a.params[0] - b.params[0]) : (a.exp - b.exp)) );
};
DRAGON.prototype.SetActorDiscovered = function(actor_id) {
    $gameSystem.actorDiscovered[actor_id] = true;
};
DRAGON.prototype.SetEnemyDiscovered = function(enemy_id) {
    $gameSystem.enemyDiscovered[enemy_id] = true;
};
DRAGON.prototype.IsActorDiscovered = function(actor) {
    if ( !actor ) return false;
    if ( actor.actorId ) {
        if ( actor.actorId > 0 ) {
            if ( $gameSystem.actorDiscovered[actor.actorId] == true ) return true;
        }
    }
    if ( actor.id ) {
        if ( actor.id > 0 ) {
            if ( $gameSystem.actorDiscovered[actor.id] == true ) return true;
        }
    }

    return false;
};
DRAGON.prototype.IsEnemyDiscovered = function(enemy) {
    if ( !enemy ) return false;
    if ( enemy.name.length < 2 ) return false;
    if ( enemy.enemyId ) {
        if ( enemy.enemyId > 0 ) {
            if ( $gameSystem.enemyDiscovered[enemy.enemyId] == true ) return true;
        }
    }
    if ( enemy.id ) {
        if ( enemy.id > 0 ) {
            if ( $gameSystem.enemyDiscovered[enemy.id] == true ) return true;
        }
    }

    return false;
};
DRAGON.prototype.Sleep = function(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
};
DRAGON.prototype.PlayItemSoundEffect = async function(item) {
    if ( !item ) return;
    if ( item.animationId < 1 ) {
        if ( item.itypeId ) {
            SoundManager.playUseItem();

            return;
        }
        else if ( item.stypeId ) {
            SoundManager.playUseSkill();

            return;
        }
    }

    const animation = $dataAnimations[item.animationId];
    const wait_size = Math.round( 1000.00000 / (animation.speed * 0.01000 * 60.00000) );

    if ( animation.soundTimings.length < 1 ) {
        if ( item.itypeId ) {
            SoundManager.playUseItem();

            return;
        }
        else if ( item.stypeId ) {
            SoundManager.playUseSkill();

            return;
        }
    }

    var delay_count_frame = 0;
    for ( i = 0; i < animation.soundTimings.length; i++ ) {
        const sound = animation.soundTimings[i];
        const delay = sound.frame - delay_count_frame;
        if ( delay > 0 ) {
            await this.Sleep( delay * wait_size );
        }

        AudioManager.playSe( sound.se );

        delay_count_frame = sound.frame;
    }
};
DRAGON.prototype.RGBA2Hex = function(rgba, forceRemoveAlpha = false) {
  return "#" + rgba.replace(/^rgba?\(|\s+|\)$/g, '') // Get's rgba / rgb string values
    .split(',') // splits them at ","
    .filter((string, index) => !forceRemoveAlpha || index !== 3)
    .map(string => parseFloat(string)) // Converts them to numbers
    .map((number, index) => index === 3 ? Math.round(number * 255) : number) // Converts alpha to 255 number
    .map(number => number.toString(16)) // Converts numbers to hex
    .map(string => string.length === 1 ? "0" + string : string) // Adds 0 when length of one number is 1
    .join("") // Puts the array to togehter to a string
};
DRAGON.prototype.CalculateAverageActorLevel = function() {
    var highest_level = 0;

    for ( let i = 0; i < $gameParty.size(); i++ )
        highest_level += $gameParty.members()[i].level;
    highest_level /= $gameParty.size();

    $gameSystem.average_actor_level = Math.round( highest_level );
};
DRAGON.prototype.SetSoftLevelCap = function() {
    const index = Number( $gameVariables.value(dragon_variable_game_chapter) ).clamp( 0, dragon_chapter_level_caps.length - 1 );

    $gameSystem.soft_level_cap = dragon_chapter_level_caps[index];
};
DRAGON.prototype.CalcExpValue = function( level_factor ) {
    const level_fac = level_factor.clamp( 0, 1 );
    const base_multiplier = 1000.0;
    const powers = [ 2.5, 5.25 ];

    let base_min = 0;
    base_min += Math.pow( base_multiplier / dragon_max_character_level, powers[0] );
    base_min += Math.pow( base_multiplier / dragon_max_character_level, powers[1] );
    let base_max = 0;
    base_max += Math.pow( base_multiplier, powers[0] );
    base_max += Math.pow( base_multiplier, powers[1] );
    base_max -= base_min;

    let sum = 0;
    sum += Math.pow( level_fac * base_multiplier, powers[0] );
    sum += Math.pow( level_fac * base_multiplier, powers[1] );
    sum -= base_min;

    const fac = Math.pow( 10.0, 11.5 ) / base_max;
    const result = sum * fac;

    return result;
};
