DRAGON.prototype.CustomHpColor = function(value, value_max) {
    const percent = Math.round(100.0 * value / value_max);

    if ( percent <= 0 ) return ( dragon_color_hp_zero );
    else if ( percent <= 8 ) return ( dragon_color_hp_near_zero );
    else if ( percent <= 15 ) return ( dragon_color_hp_very_low );
    else if ( percent <= 25 ) return ( dragon_color_hp_low );
    else if ( percent <= 50 ) return ( dragon_color_hp_medium_low );
    else if ( percent <= 75 ) return ( dragon_color_hp_medium );
    else if ( percent <= 99 ) return ( dragon_color_hp_slight );
    else return ( dragon_color_hp_max );

    return ( dragon_color_hp_max );
};
