    if (!ct.etype_rate) ct.etype_rate = [];
    if (!ct.wtype_rate) ct.wtype_rate = [];
    if (!ct.race_rate) ct.race_rate = [];
    if (!ct.class_rate) ct.class_rate = [];
    if (!meta.dgnSkillPowers) meta.dgnSkillPowers = "";
    if (!meta.dgnElementPowers) meta.dgnElementPowers = "";
    if (!meta.dgnWeaponPowers) meta.dgnWeaponPowers = "";
    if (!meta.dgnRacePowers) meta.dgnRacePowers = "";
    if (!meta.dgnClassPowers) meta.dgnClassPowers = "";
    if (!meta.dgnSkillRate) meta.dgnSkillRate = "";
