DRAGON.prototype.ConcatCustomTraits = function(ctraits, other_ctraits) {
    if (!ctraits) return null;
    if (!other_ctraits) return ctraits;

    ctraits.to_hit_physical_add += other_ctraits.to_hit_physical_add;
    ctraits.to_hit_physical_multiply *= other_ctraits.to_hit_physical_multiply;
    ctraits.to_hit_magical_add += other_ctraits.to_hit_magical_add;
    ctraits.to_hit_magical_multiply *= other_ctraits.to_hit_magical_multiply;
    ctraits.magic_focus_add += other_ctraits.magic_focus_add;
    ctraits.magic_focus_multiply *= other_ctraits.magic_focus_multiply;
    ctraits.magic_focus_debuff_rate *= other_ctraits.magic_focus_debuff_rate;
    ctraits.max_tactical_points_add += other_ctraits.max_tactical_points_add;
    ctraits.max_tactical_points_multiply *= other_ctraits.max_tactical_points_multiply;
    ctraits.physical_critical_hit_rate += other_ctraits.physical_critical_hit_rate;
    ctraits.magical_critical_hit_rate += other_ctraits.magical_critical_hit_rate;
    ctraits.physical_critical_evade_rate += other_ctraits.physical_critical_evade_rate;
    ctraits.magical_critical_evade_rate += other_ctraits.magical_critical_evade_rate;
    ctraits.extra_actions_multiply += other_ctraits.extra_actions_multiply;
    ctraits.stype_power = ctraits.stype_power.map((v,index) => v * other_ctraits.stype_power[index]);
    ctraits.etype_power = ctraits.etype_power.map((v,index) => v * other_ctraits.etype_power[index]);
    ctraits.wtype_power = ctraits.wtype_power.map((v,index) => v * other_ctraits.wtype_power[index]);
    ctraits.race_power = ctraits.race_power.map((v,index) => v * other_ctraits.race_power[index]);
    ctraits.class_power = ctraits.class_power.map((v,index) => v * other_ctraits.class_power[index]);
    ctraits.stype_rate = ctraits.stype_rate.map((v,index) => v * other_ctraits.stype_rate[index]);
    ctraits.etype_rate = ctraits.etype_rate.map((v,index) => v * other_ctraits.etype_rate[index]);
    ctraits.wtype_rate = ctraits.wtype_rate.map((v,index) => v * other_ctraits.wtype_rate[index]);
    ctraits.race_rate = ctraits.race_rate.map((v,index) => v * other_ctraits.race_rate[index]);
    ctraits.class_rate = ctraits.class_rate.map((v,index) => v * other_ctraits.class_rate[index]);

    for (const equip of other_ctraits.disable_equip) {
        if (!ctraits.disable_equip.includes(equip))
            ctraits.disable_equip.push(equip);
    }

    return ctraits;
};
DRAGON.prototype.ConcatCustomTraitsWithUsageTraits = function(ctraits, other_ctraits) {
    if (!ctraits) return null;
    if (!other_ctraits) return ctraits;

    ctraits.stype_power = ctraits.stype_power.map((v,index) => v * other_ctraits.stype_power[index]);
    ctraits.etype_power = ctraits.etype_power.map((v,index) => v * other_ctraits.etype_power[index]);
    ctraits.wtype_power = ctraits.wtype_power.map((v,index) => v * other_ctraits.wtype_power[index]);
    ctraits.race_power = ctraits.race_power.map((v,index) => v * other_ctraits.race_power[index]);
    ctraits.class_power = ctraits.class_power.map((v,index) => v * other_ctraits.class_power[index]);

    for (const equip of other_ctraits.disable_equip) {
        if (!ctraits.disable_equip.includes(equip))
            ctraits.disable_equip.push(equip);
    }

    return ctraits;
};
DRAGON.prototype.CustomTraitsVsCustomTraits = function(ctraits_attacker, ctraits_defender) {
    let result = DGN.MakeInitializedCustomTraits();
    result.stype_effect = result.stype_power.map( (p,index) => Math.max(ctraits_attacker.stype_power[index] * ctraits_defender.stype_rate[index], 0.0) );
    result.etype_effect = result.etype_power.map( (p,index) => Math.max(ctraits_attacker.etype_power[index] * ctraits_defender.etype_rate[index], 0.0) );
    result.wtype_effect = result.wtype_power.map( (p,index) => Math.max(ctraits_attacker.wtype_power[index] * ctraits_defender.wtype_rate[index], 0.0) );
    result.race_effect = result.race_power.map( (p,index) => Math.max(ctraits_attacker.race_power[index] * ctraits_defender.race_rate[index], 0.0) );
    result.class_effect = result.class_power.map( (p,index) => Math.max(ctraits_attacker.class_power[index] * ctraits_defender.class_rate[index], 0.0) );
    return result;
};
DRAGON.prototype.StateScaleVsCustomTraits = function(ctraits_attacker, ctraits_defender) {
    let ctraits = DGN.CustomTraitsVsCustomTraits(ctraits_attacker, ctraits_defender);
    let effects = [];
    ctraits.stype_effect.forEach(value => (Math.abs(value - 1.0) >= 0.00001) ? effects.push(value) : 0);
    ctraits.etype_effect.forEach(value => (Math.abs(value - 1.0) >= 0.00001) ? effects.push(value) : 0);
    ctraits.wtype_effect.forEach(value => (Math.abs(value - 1.0) >= 0.00001) ? effects.push(value) : 0);
    ctraits.race_effect.forEach(value => (Math.abs(value - 1.0) >= 0.00001) ? effects.push(value) : 0);
    ctraits.class_effect.forEach(value => (Math.abs(value - 1.0) >= 0.00001) ? effects.push(value) : 0);
    return effects.length < 1 ? 1.0 : effects.reduce((accum,value) => accum + value, 0.0) / effects.length;
};
DRAGON.prototype.CalculateAttackDamageScaleMain = function(element=1) {
    if (!DGN.attacker) return 1.0;
    if (!DGN.defender) return 1.0;
    if (!DGN.active_item) return 1.0;
    const atk_ct = DGN.attacker.CustomTraits();
    const def_ct = DGN.defender.CustomTraits();
    const item_ut = DGN.active_item.usage_traits;
    const elm = element ? element : 1;
    const a_rc = DGN.attacker.race.id;
    const d_rc = DGN.defender.race.id;
    const a_cls = DGN.attacker.currentClass().id;
    const d_cls = DGN.defender.currentClass().id;

    if (DGN.active_item.stypeId) {
        const skl = DGN.active_item.stypeId;
        const wpn = DGN.active_item.weapon_type;
        let scale = item_ut.stype_power[skl] * atk_ct.stype_power[skl] * def_ct.stype_rate[skl];
        if (DGN.active_item.weapon_type > 0) scale *= item_ut.wtype_power[wpn] * atk_ct.wtype_power[wpn] * def_ct.wtype_rate[wpn];
        scale *= item_ut.etype_power[elm] * atk_ct.etype_power[elm] * def_ct.etype_rate[elm];
        scale *= item_ut.race_power[d_rc] * atk_ct.race_power[d_rc] * def_ct.race_rate[a_rc];
        scale *= item_ut.class_power[d_cls] * atk_ct.class_power[d_cls] * def_ct.class_rate[a_cls];
        return scale;
    }
    let scale = item_ut.etype_power[elm] * atk_ct.etype_power[elm] * def_ct.etype_rate[elm];
    scale *= item_ut.race_power[d_rc] * atk_ct.race_power[d_rc] * def_ct.race_rate[a_rc];
    scale *= item_ut.class_power[d_cls] * atk_ct.class_power[d_cls] * def_ct.class_rate[a_cls];
    return scale;
};
DRAGON.prototype.CalculateAttackDamageScaleElemental = function(element=1) {
    if (!DGN.attacker) return 1.0;
    if (!DGN.defender) return 1.0;
    if (!DGN.active_item) return 1.0;
    const atk_ct = DGN.attacker.CustomTraits();
    const def_ct = DGN.defender.CustomTraits();
    const item_ut = DGN.active_item.usage_traits;
    const elm = element ? element : 1;
    const a_rc = DGN.attacker.race.id;
    const d_rc = DGN.defender.race.id;
    const a_cls = DGN.attacker.currentClass().id;
    const d_cls = DGN.defender.currentClass().id;

    let scale = item_ut.etype_power[elm] * atk_ct.etype_power[elm] * def_ct.etype_rate[elm];
    scale *= item_ut.race_power[d_rc] * atk_ct.race_power[d_rc] * def_ct.race_rate[a_rc];
    scale *= item_ut.class_power[d_cls] * atk_ct.class_power[d_cls] * def_ct.class_rate[a_cls];
    return scale;
};
DRAGON.prototype.UpgradeItemRandom_Weapon = function(item) {
    if (!item) return null;

    const max_upgrade_type_factor0 = 49;
    const max_upgrade_type_factor1 = 24;
    const max_upgrade_type_factor2 = 24;
    const max_upgrade_type_factor3 = 5000;
    // const max_upgrade_type_factor4 = 1250;
    const max_upgrade_type_factor5 = 250;
    const max_upgrade_type_array_power = 250;
    const upgrade0 = Math.round( Math.random() * max_upgrade_type_factor0 );
    const upgrade1 = Math.round( Math.random() * max_upgrade_type_factor1 );
    const upgrade2 = Math.round( Math.random() * max_upgrade_type_factor2 );
    const upgrade3 = Math.round( Math.random() * max_upgrade_type_factor3 );
    // const upgrade4 = Math.round( Math.random() * max_upgrade_type_factor4 );
    const upgrade5 = Math.round( Math.random() * max_upgrade_type_factor5 );
    let t = item.traits;
    let ct = item.custom_traits;
    let ut = item.usage_traits;
    const level_factor = (item.level / dragon_max_item_levels).clamp(0.0005, 1.0);
    const r0 = ((Math.random() * 0.99) + 0.01) * 10.0;
    const r1 = (Math.random() * 0.95) + 0.05;
    const r2 = (Math.random() * 0.95) + 0.05;
    const r3 = (Math.random() * 0.95) + 0.05;
    const r4 = (Math.random() * 0.975) + 0.025;
    const r5 = (Math.random() * 0.99) + 0.01;

    if (upgrade0 < 1) item.params[0] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 2) item.params[1] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 3) item.params[2] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 4) item.params[3] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 5) item.params[4] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 6) item.params[5] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 7) item.params[6] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 8) item.params[7] += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );
    else if (upgrade0 < 9) ct.magic_focus_add += Math.ceil( r0 * DGN.Lerp( 1.0, 50.0, level_factor ) );

    if (upgrade1 < 1) ut.to_hit_physical_multiply += 0.05 * r1;
    else if (upgrade1 < 2) ut.to_hit_magical_multiply += 0.05 * r1;
    else if (upgrade1 < 3) ut.physical_critical_hit_rate += 0.05 * r1;
    else if (upgrade1 < 4) ut.magical_critical_hit_rate += 0.05 * r1;
    else if (upgrade1 < 5) t.push({ code: Game_BattlerBase.TRAIT_XPARAM, dataId: 6, value: 0.0125 * r1 });

    if (upgrade2 < 1) { ut.aim_multiply[0] += 0.1 * r2; ut.aim_multiply[1] += 0.1 * r2; }
    else if (upgrade2 < 2) { ut.critical_chance_multiply[0] += 0.1 * r2; ut.critical_chance_multiply[1] += 0.1 * r2; }
    else if (upgrade2 < 3) { ut.critical_damage_multiply[0] += 0.5 * r2; ut.critical_damage_multiply[1] += 0.5 * r2; }
    else if (upgrade2 < 4) { ut.attack_damage_multiply[0] += 0.2 * r2; ut.attack_damage_multiply[1] += 0.2 * r2; }
    else if (upgrade2 < 5) { ut.target_defense_multiply[0] *= DGN.Lerp(1.0, 0.8, r2); ut.target_defense_multiply[1] *= DGN.Lerp(1.0, 0.8, r2); }

    if (upgrade3 < 100) t.push({ code: Game_BattlerBase.TRAIT_ATTACK_SPEED, dataId: 0, value: Math.ceil( r3 * DGN.Lerp(5, 25, level_factor) ) });

    /* if (upgrade4 < 1000) */ ct.max_tactical_points_add += Math.ceil( r4 * DGN.Lerp(40, 320, level_factor) );

    if (item.max_uses > 0) {
        if (upgrade5 < 100) { item.max_uses += Math.ceil(item.max_uses * r5 * 0.125); item.uses = item.max_uses; }
    }

    if (Math.random() * max_upgrade_type_array_power < 100) {
        let array = ut.stype_power;
        const index = Math.round(Math.random() * (array.length - 2)) + 1;
        array[index] += ((Math.random() * 0.95) + 0.05) * 0.1;
    }
    if (Math.random() * max_upgrade_type_array_power < 100) {
        let array = ut.etype_power;
        const index = Math.round(Math.random() * (array.length - 3)) + 2;
        array[index] += ((Math.random() * 0.95) + 0.05) * 0.1;
    }
    if (Math.random() * max_upgrade_type_array_power < 100) {
        let array = ut.wtype_power;
        const index = Math.round(Math.random() * (array.length - 2)) + 1;
        array[index] += ((Math.random() * 0.95) + 0.05) * 0.1;
    }
    if (Math.random() * max_upgrade_type_array_power < 100) {
        let array = ut.race_power;
        const index = Math.round(Math.random() * (array.length - 1));
        array[index] += ((Math.random() * 0.95) + 0.05) * 0.1;
    }
    if (Math.random() * max_upgrade_type_array_power < 100) {
        let array = ut.class_power;
        const index = Math.round(Math.random() * (array.length - 2)) + 1;
        array[index] += ((Math.random() * 0.95) + 0.05) * 0.1;
    }

    item.price += Math.ceil(item.price * 0.2);

    return item;
};
