///-----------------------------------------------------------------------------
/// Spriteset_Map
///
/// The set of sprites on the map screen.
Spriteset_Map.prototype.updateShadow = function() {
    const vehicle = $gamePlayer.vehicle();
    if ( vehicle ) {
        this._shadowSprite.x = vehicle.shadowX();
        this._shadowSprite.y = vehicle.shadowY();
        this._shadowSprite.opacity = vehicle.shadowOpacity();
    }
    else {
        this._shadowSprite.opacity = 0;

        if ( DGN.vehicle_transition_count ) {
            if ( (DGN.vehicle_transition_count > 0) && ($gameSystem.vehicle_data.map_id == $gameMap.mapId()) ) this._shadowSprite.opacity = 255;
        }
    }
};

///-----------------------------------------------------------------------------
/// Dgn_Window_ActionList
///
/// A window class with a list of options or commands, based upon Window_Selectable.
function Dgn_Window_ActionList() {
    this.initialize(...arguments);
}
Dgn_Window_ActionList.prototype = Object.create(Window_Selectable.prototype);
Dgn_Window_ActionList.prototype.constructor = Dgn_Window_ActionList;

Dgn_Window_ActionList.prototype.initialize = function(rect, in_parent, in_data_list, in_config, in_msg_code, xtra=null) {
    this.up = 0;
    this.right = 1;
    this.down = 2;
    this.left = 3;

    this.window_focused = false;
    this.window_ready = false;
    this.highlight = -10;

    this.data = in_data_list;
    this.index_last = -1;
    this.parent_scene = in_parent;
    this.xtra = xtra;
    this.page = 0;
    this.item_display_override_index = -10;
    this.selection_lock = false;
    this.cursor_blink_held = false;
    this._wrap_enabled = false;

    this.config = {
        window_name: "",
        cols: 1,
        data_complex: false,
        item_height: 40,
        single_view: false,
        single_view_toggle_scroll: false,
        unselection_index: -1
    };
    this.parent_id_message_code = {
        item_activated: -1,
        window_focused: -1,
        item_focused: -1,
        item_unfocused: -1,
        exit: -1,
        border_wrap: -1
    };

    this.SetConfig(in_config);
    this.SetMessage_IDs(in_msg_code);

    Window_Selectable.prototype.initialize.call(this, rect);

    this.loadFaceImages();
    this.drawAllItems();
    this.refresh();
    this.deactivate();
};
Dgn_Window_ActionList.prototype.loadFaceImages = function() {
    if (!this.data) return;
    if (!this.config.data_complex) return;

    for (let i = 0; i < this.data.length; i++) {
        const data = this.data[i];
        const dat_array = data[2] ? data[2] : null;
        if (dat_array.length < 1) continue;
        const dat = dat_array[0];

        if (dat.actor_party_init || dat.actor_info_window) {
            if (dat.actor_id >= $dataActors.length) return;
            const actor = $gameActors.actor(dat.actor_id);
            if (!actor) return;

            ImageManager.loadFace(actor.faceName());
        }
    }
};
Dgn_Window_ActionList.prototype.SetParent = function(parent_object) {
    this.parent_scene = parent_object;
};
Dgn_Window_ActionList.prototype.Parent = function() {
    if (!this.parent_scene) return null;

    return this.parent_scene;
};
Dgn_Window_ActionList.prototype.ParentNotBusy = function() {
    if (!this.parent_scene) return false;
    if (!this.parent_scene.not_busy) return false;

    return this.parent_scene.not_busy;
};
Dgn_Window_ActionList.prototype.GetReadyParent = function() {
    if (!this.parent_scene) return null;
    if (!this.parent_scene.not_busy) return null;
    if (this.parent_scene.not_busy === true) return this.parent_scene;

    return null;
};
Dgn_Window_ActionList.prototype.SetConfig = function(cfg) {
    if (!cfg) return;

    if (cfg.window_name) this.config.window_name = cfg.window_name;
    if (cfg.cols) this.config.cols = cfg.cols;
    if (cfg.data_complex) this.config.data_complex = cfg.data_complex;
    if (cfg.item_height) this.config.item_height = cfg.item_height;
    if (cfg.single_view) this.config.single_view = cfg.single_view;
    if (cfg.single_view_toggle_scroll) this.config.single_view_toggle_scroll = cfg.single_view_toggle_scroll;
    if (cfg.unselection_index) this.config.unselection_index = cfg.unselection_index;
};
Dgn_Window_ActionList.prototype.SetMessage_IDs = function(ids) {
    if (!ids) return;

    if (ids.item_activated) this.parent_id_message_code.item_activated = Number(ids.item_activated);
    if (ids.window_focused) this.parent_id_message_code.window_focused = Number(ids.window_focused);
    if (ids.item_focused) this.parent_id_message_code.item_focused = Number(ids.item_focused);
    if (ids.item_unfocused) this.parent_id_message_code.item_unfocused = Number(ids.item_unfocused);
    if (ids.exit) this.parent_id_message_code.exit = Number(ids.exit);
    if (ids.border_wrap) this.parent_id_message_code.border_wrap = Number(ids.border_wrap);
};
Dgn_Window_ActionList.prototype.DirectionText = function(direction) {
    if (direction == this.up) return "up";
    if (direction == this.right) return "right";
    if (direction == this.down) return "down";
    if (direction == this.left) return "left";

    return "none";
};
Dgn_Window_ActionList.prototype.ParentMessage_ItemActivated = function(idx=-1) {
    if (!this.window_ready) return;
    const parent_scene = this.GetReadyParent();
    if (!parent_scene) return;
    const message_id = this.parent_id_message_code.item_activated;
    if (message_id < 0) return;
    const index = (idx >= 0) ? idx : this.index();
    const direction = -1;

    try {
        parent_scene.ChildToParentMessage( message_id, index, direction, this.config.window_name );
    } catch (e) {
        console.log( "ERROR: Action List Window Child-to-Parent message failed.\n" +
                    "Window Name: " + this.config.window_name + ", Parent Scene Name: " + parent_scene.scene_name + "\n" +
                    "Message ID: " + message_id + ", Message Index: " + index + ", direction: " + this.DirectionText(direction) + "\n" +
                    "Action: Action List Item Activated / Pressed / Clicked\n" +
                    e );
    }
};
