Dgn_Window_ActionList.prototype.ParentMessage_Exit = function(idx=-1) {
    if (!this.window_ready) return;
    const parent_scene = this.GetReadyParent();
    if (!parent_scene) return;
    const message_id = this.parent_id_message_code.exit;
    if (message_id < 0) return;
    const index = (idx >= 0) ? idx : this.index();
    const direction = -1;

    try {
        parent_scene.ChildToParentMessage( message_id, index, direction, this.config.window_name );
    } catch (e) {
        console.log( "ERROR: Action List Window Child-to-Parent message failed.\n" +
                    "Window Name: " + this.config.window_name + ", Parent Scene Name: " + parent_scene.scene_name + "\n" +
                    "Message ID: " + message_id + ", Message Index: " + index + ", direction: " + this.DirectionText(direction) + "\n" +
                    "Action: Exit out of Action List\n" +
                    e );
    }
};
Dgn_Window_ActionList.prototype.ParentMessage_BorderWrap = function(idx=-1, direction=-1) {
    if (!this.window_ready) return;
    const parent_scene = this.GetReadyParent();
    if (!parent_scene) return;
    const message_id = this.parent_id_message_code.border_wrap;
    if (message_id < 0) return;
    const index = (idx >= 0) ? idx : this.index();

    try {
        parent_scene.ChildToParentMessage( message_id, index, direction, this.config.window_name );
    } catch (e) {
        console.log( "ERROR: Action List Window Child-to-Parent message failed.\n" +
                    "Window Name: " + this.config.window_name + ", Parent Scene Name: " + parent_scene.scene_name + "\n" +
                    "Message ID: " + message_id + ", Message Index: " + index + ", direction: " + this.DirectionText(direction) + "\n" +
                    "Action: Wrap / Exit at border.\n" +
                    e );
    }
};
Dgn_Window_ActionList.prototype.maxItems = function() {
    if (!this.data)
        return 0;

    if (this.config.single_view)
        return 1;

    return this.data.length;
};
Dgn_Window_ActionList.prototype.maxCols = function() {
    return this.config.cols;
};
Dgn_Window_ActionList.prototype.maxVisibleItems = function() {
    if (this.config.single_view)
        return 1;

    const visibleRows = Math.ceil(this.contentsHeight() / this.itemHeight());
    return visibleRows * this.maxCols();
};
Dgn_Window_ActionList.prototype.Focused = function() {
    return this.window_focused;
};
Dgn_Window_ActionList.prototype.Lock = function() {
    this.selection_lock = true;
};
Dgn_Window_ActionList.prototype.Unlock = function() {
    this.selection_lock = false;
};
Dgn_Window_ActionList.prototype.ClearSelection = function() {
    if (this.selection_lock) return;

    this.index_last = this._index;
    this._index = this.config.unselection_index;
    // this.setPendingIndex(this._index);
    this.refreshCursor();
    this.callUpdateHelp();
};
Dgn_Window_ActionList.prototype.select_auto = function(index_in) {
    const parent_scene = this.Parent();
    if (!parent_scene) return;

    let index = index_in;
    if (index < 0) index = this.config.unselection_index;
    if (this.selection_lock) index = this._index;

    this.index_last = this._index;
    this._index = index;
    // this.setPendingIndex(index);

    this.refreshCursor();
    this.callUpdateHelp();
};
Dgn_Window_ActionList.prototype.select = function(index_in) {
    const parent_scene = this.Parent();
    if (!parent_scene) return;

    let index = index_in;
    if (index < 0) index = this.config.unselection_index;
    if (this.selection_lock) index = this._index;

    if (!parent_scene.not_busy) {
        this.select_auto(index);

        return;
    }

    const i_old = this._index;
    const i_new = index;
    this.index_last = i_old;
    this._index = i_new;

    if ((index_in < 0) && (this.window_focused)) {
        this.ParentMessage_ItemUnfocused(i_old);
        // this.setPendingIndex(-1);
        this.refreshCursor();
        this.callUpdateHelp();

        return;
    }

    if (this.window_focused) {
        this.ParentMessage_ItemFocused(i_new);
        // this.setPendingIndex(i_new);
        this.refreshCursor();
        this.callUpdateHelp();

        return;
    }

    this.ParentMessage_ListFocused(i_new);
    this.ParentMessage_ItemFocused(i_new);
    // this.setPendingIndex(i_new);

    this.refreshCursor();
    this.callUpdateHelp();
};
Dgn_Window_ActionList.prototype.DisplayOverride = function(override_index) {
    this.item_display_override_index = override_index;
};
Dgn_Window_ActionList.prototype.ClearDisplayOverride = function() {
    this.item_display_override_index = -10;
};
Dgn_Window_ActionList.prototype.itemRect = function(index_in) {
    let index = (!this.config.single_view) ? index_in : 0;
    // if (this.item_display_override_index >= -1) index = this.item_display_override_index;

    const maxCols = this.maxCols();
    const itemWidth = this.itemWidth();
    const itemHeight = this.itemHeight();
    const colSpacing = this.colSpacing();
    const rowSpacing = this.rowSpacing();
    const col = index % maxCols;
    const row = Math.floor(index / maxCols);
    const x = col * itemWidth + colSpacing / 2 - this.scrollBaseX();
    const y = row * itemHeight + rowSpacing / 2 - this.scrollBaseY();
    const width = itemWidth - colSpacing;
    const height = itemHeight - rowSpacing;
    return new Rectangle(x, y, width, height);
};
Dgn_Window_ActionList.prototype.DrawItemNameAndIcon = function(item, x, y, width) {
    if (item) {
        const rect = this.itemRect( this.index() );

        this.resetTextColor();
        this.drawIcon(item.iconIndex, x, y);
        this.drawText(item.name, x + 37, y + 16, width - 37);
    }
};
Dgn_Window_ActionList.prototype._updateCursor = function() {
    this._cursorSprite.alpha = this.cursor_blink_held ? 0 : this._makeCursorAlpha();
    this._cursorSprite.visible = this.isOpen() && this.cursorVisible;
    this._cursorSprite.x = this._cursorRect.x;
    this._cursorSprite.y = this._cursorRect.y;
};
Dgn_Window_ActionList.prototype.HoldCursor = function(hold_active=true) {
    this.cursor_blink_held = hold_active;
};
Dgn_Window_ActionList.prototype.clearItem = function(index) {
    const rect = this.itemRect(index);
    this.contents.clearRect(rect.x, rect.y, rect.width, rect.height);
    this.contentsBack.clearRect(rect.x, rect.y, rect.width, rect.height);
};
Dgn_Window_ActionList.prototype.drawAllItems = function() {
    if (this.config.single_view) {
        let index = this._index;

        if (this.item_display_override_index >= -1) index = this.item_display_override_index;

        this.drawItemBackground(this._index);
        this.drawItem(index);

        return;
    }

    const topIndex = this.topIndex();
    for (let i = 0; i < this.maxVisibleItems(); i++) {
        const index = topIndex + i;
        if (index < this.maxItems()) {
            this.drawItemBackground(index);
            this.drawItem(index);
        }
    }
};
Dgn_Window_ActionList.prototype.drawItemBackground = function(index_in) {
    let index = index_in;
    if (this.item_display_override_index >= -1) index = this.item_display_override_index;
    if (this.config.single_view) {
        index = 0;
    }

    const rect = this.itemRect(index);
    this.drawBackgroundRect(rect);
};
Dgn_Window_ActionList.prototype.HighlightIndex = function() {
    return this.highlight;
};
/*
Dgn_Window_ActionList.prototype.setPendingIndex = function(index) {
    const lastPendingIndex = this._pendingIndex;
    this.highlight = index;
    this.redrawItem(this._pendingIndex);
    this.redrawItem(lastPendingIndex);
};
*/
Dgn_Window_ActionList.prototype.SetHighlight = function(index) {
    const highlighted_last = this.highlight;
    this.highlight = index;
    this.redrawItem(this.highlight);
    this.redrawItem(highlighted_last);
};
Dgn_Window_ActionList.prototype.ClearHighlight = function(index) {
    this.SetHighlight(-10);
};
/*
Dgn_Window_ActionList.prototype.drawPendingItemBackground = function(index) {
    if (index == this._pendingIndex) {
        const rect = this.itemRect( (!this.config.single_view) ? index : 0 );

        const color = ColorManager.pendingColor();
        this.changePaintOpacity(false);
        this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        this.changePaintOpacity(true);
    }
};
*/
Dgn_Window_ActionList.prototype.DrawHighlightBG = function(index) {
    if (index == this.highlight) {
        const rect = this.itemRect(index);

        const color = ColorManager.pendingColor();
        this.changePaintOpacity(false);
        this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        this.changePaintOpacity(true);
    }
};
Dgn_Window_ActionList.prototype.processCursorMove = function() {
    if (this.isCursorMovable()) {
        const lastIndex = this.index();
        if (Input.isRepeated("down")) {
            this.cursorDown(Input.isTriggered("down") && this._wrap_enabled);
        }
        if (Input.isRepeated("up")) {
            this.cursorUp(Input.isTriggered("up") && this._wrap_enabled);
        }
        if (Input.isRepeated("right")) {
            this.cursorRight(Input.isTriggered("right") && this._wrap_enabled);
        }
        if (Input.isRepeated("left")) {
            this.cursorLeft(Input.isTriggered("left") && this._wrap_enabled);
        }
        if (!this.isHandled("pagedown") && Input.isTriggered("pagedown")) {
            this.cursorPagedown();
        }
        if (!this.isHandled("pageup") && Input.isTriggered("pageup")) {
            this.cursorPageup();
        }
        if (this.index() !== lastIndex) {
            this.playCursorSound();
        }
    }
};
Dgn_Window_ActionList.prototype.cursorLeft = function(wrap) {
    if (!this.window_focused)
        return;
    const index_old = this._index;

    if (this.config.single_view) {
        this.ParentMessage_BorderWrap(this._index, this.left);

        return;
    }
    if (this._index < 0) {
        this.select(0);

        return;
    }
    if ((this._index % this.maxCols()) == 0) {
        // this.select_auto(-1);
        this.ParentMessage_BorderWrap(index_old, this.left);
        Input.update();

        return;
    }

    const index = Math.max(0, this.index());
    const maxItems = this.maxItems();
    const maxCols = this.maxCols();
    const horizontal = this.isHorizontal();
    if (maxCols >= 2 && (index > 0 || (wrap && horizontal))) {
        this.smoothSelect((index - 1 + maxItems) % maxItems);
    }
};
Dgn_Window_ActionList.prototype.cursorRight = function(wrap) {
    if (!this.window_focused)
        return;
    const index_old = this._index;

    if (this.config.single_view) {
        this.ParentMessage_BorderWrap(this._index, this.right);

        return;
    }
    if (this._index < 0) {
        this.select(0);

        return;
    }
    if ((this._index % this.maxCols()) == (this.maxCols() - 1)) {
        // this.select_auto(-1);
        this.ParentMessage_BorderWrap(index_old, this.right);
        Input.update();

        return;
    }

    const index = this.index();
    const maxItems = this.maxItems();
    const maxCols = this.maxCols();
    const horizontal = this.isHorizontal();
    if (maxCols >= 2 && (index < maxItems - 1 || (wrap && horizontal))) {
        this.smoothSelect((index + 1) % maxItems);
    }
};
Dgn_Window_ActionList.prototype.cursorUp = function(wrap) {
    if (!this.window_focused)
        return;
    const index_old = this._index;

    if (this.config.single_view) {
        const index = this._index;
        this.ParentMessage_BorderWrap(index, this.up);

        return;
    }
    if (this._index < 0) {
        this.select(0);

        return;
    }
    if (this._index < this.maxCols()) {
        // this.select_auto(-1);
        this.ParentMessage_BorderWrap(index_old, this.up);
        Input.update();

        return;
    }

    const index = Math.max(0, this.index());
    const maxItems = this.maxItems();
    const maxCols = this.maxCols();
    if (index >= maxCols || (wrap && maxCols === 1)) {
        this.smoothSelect((index - maxCols + maxItems) % maxItems);
    }
};
Dgn_Window_ActionList.prototype.cursorDown = function(wrap) {
    if (!this.window_focused)
        return;
    const index_old = this._index;

    if (this.config.single_view) {
        const index = this._index;
        this.ParentMessage_BorderWrap(index, this.down);

        return;
    }
    if (this._index < 0) {
        this.select(0);

        return;
    }
    if ((this.maxItems() - this._index) <= this.maxCols()) {
        // this.select_auto(-1);
        this.ParentMessage_BorderWrap(index_old, this.down);
        Input.update();

        return;
    }

    const index = this.index();
    const maxItems = this.maxItems();
    const maxCols = this.maxCols();
    const was_on_bottom_edge = (index > (this.maxItems() - this.maxRows())) ? true : false;
    if (index < maxItems - maxCols || (wrap && maxCols === 1)) {
        this.smoothSelect((index + maxCols) % maxItems);
    }
};
Dgn_Window_ActionList.prototype.CycleDataPage = function(new_page=-1) {
//    if (!this.window_focused)
//        return;

    if (this.config.single_view) {
        const data = this.data[this._index];
        if (data[2]) {
            const data_array = data[2];
            const max_data_pages = data_array.length;
            this.page++;
            if (new_page >= 0)
                this.page = new_page;
            if (this.page >= max_data_pages)
                this.page = 0;
        } else {
            this.page = 0;
        }
    }
};
Dgn_Window_ActionList.prototype.processOk = function() {
    if (!this.window_focused)
        return;

    this.playOkSound();
    this.updateInputData();
    this.ParentMessage_ItemActivated(this._index);
};
Dgn_Window_ActionList.prototype.processCancel = function() {
    if (!this.window_focused)
        return;

    SoundManager.playCancel();
    this.updateInputData();
    this.ParentMessage_Exit(this._index);
};
Dgn_Window_ActionList.prototype.isOkEnabled = function() {
    return true;
};
Dgn_Window_ActionList.prototype.isCancelEnabled = function() {
    return true;
};
Dgn_Window_ActionList.prototype.isCursorMovable = function() {
    return (
        this.isOpenAndActive() &&
        !this._cursorFixed &&
        !this._cursorAll &&
        this.maxItems() > 0
    );
};
Dgn_Window_ActionList.prototype.hitTest = function(x, y) {
    if (this.innerRect.contains(x, y)) {
        const cx = this.origin.x + x - this.padding;
        const cy = this.origin.y + y - this.padding;
        const topIndex = this.topIndex();

        for (let i = 0; i < this.maxVisibleItems(); i++) {
            const index = topIndex + i;
            // let index1 = topIndex + i;
            // if (this.item_display_override_index >= -1) index1 = this.item_display_override_index;

            if (this.config.single_view) {
                const rect = this.itemRect(0);
                if (rect.contains(cx, cy))
                    return this._index;
                else
                    return -1;
            };

            if (index < this.maxItems()) {
                const rect = this.itemRect(index);
                if (rect.contains(cx, cy)) {
                    return index;
                }
            }
        }
    }
    return -1;
};
Dgn_Window_ActionList.prototype.drawActorFace = function(actor, x, y, width, height) {
    this.drawFace(actor.faceName(), actor.faceIndex(), x, y, width, height);
};
Dgn_Window_ActionList.prototype.itemHeight = function() {
    return this.config.item_height;
};
Dgn_Window_ActionList.prototype.lineHeight = function() {
    return 20;
};
Dgn_Window_ActionList.prototype.drawItem = function(index_in) {
    if (!this.data) return;

    this.DrawHighlightBG(index_in);

    const idx = (index_in < 0) ? this.config.unselection_index : index_in;
    if (idx != idx.clamp(0, this.data.length - 1)) return;
    const data = this.data[idx];

    if (!this.config.data_complex) {
        const line_rect = this.itemLineRect( (!this.config.single_view) ? idx : 0 );
        this.drawText(String( data[1] ), line_rect.x, line_rect.y, line_rect.width, "left");

        return;
    }

    const dat_array = data[2];
    if (!dat_array) return;
    if (dat_array.length < 1) return;
    const page = (this.page >= dat_array.length) ? dat_array.length - 1 : this.page;
    const dat = dat_array[page];

    this.changePaintOpacity(true);

    if (dat.actor_party_init) {
        var party_manager = this.xtra;
        if (!party_manager) return;
        if (dat.actor_id >= $dataActors.length) return;
        const actor = $gameActors.actor(dat.actor_id);
        if (!actor) return;

        const rect = this.itemRect(idx);
        this.drawActorFace(actor, rect.x + 2, rect.y + 2, ImageManager.faceWidth, ImageManager.faceWidth);

        const tx = rect.x + 148;
        const ty = rect.y + 2;
        const text_width = 230;
        const line_height = 20;
        const cls = actor.currentClass();

        let txt0 = actor.name();
        let txt1 = actor.nickname();
        let txt2 = "";
        let txt3 = "";
        let txt4 = "";
        let txt5 = "";
        let txt6 = "";
        if (dat.actor_is_party === true) {
            if (cls.id == 1) {
                txt2 = "No Class Assigned";
                txt4 = "Please select a class";
                txt5 = "   for this character";
            } else {
                txt2 = cls.name;
                if (party_manager.IsPartyReady())
                    txt4 = "Ready to go";
            }
        } else {
            if (cls.id == 1) {
                txt2 = "No Class Assigned";
            } else {
                txt2 = cls.name;
            }

            if (party_manager.SizeParty() < dragon_max_starting_party_members)
                txt4 = "Available";
        }

        this.drawText( txt0, tx, ty, text_width );
        this.drawText( txt1, tx, ty + line_height, text_width );
        this.drawText( txt2, tx, ty + (line_height * 2), text_width );
        this.drawText( txt3, tx, ty + (line_height * 3), text_width );
        this.drawText( txt4, tx, ty + (line_height * 4), text_width );
        this.drawText( txt5, tx, ty + (line_height * 5), text_width );
        this.drawText( txt6, tx, ty + (line_height * 6), text_width );
    }
    else if (dat.actor_info_window) {
        var party_manager = this.xtra;
        if (!party_manager) return;
        if (dat.actor_id >= $dataActors.length) return;
        const actor = $gameActors.actor(dat.actor_id);
        if (!actor) return;

        const rect = this.itemRect( (!this.config.single_view) ? idx : 0 );
        this.changePaintOpacity(true);
        this.drawActorFace(actor, rect.x + 2, rect.y + 2, ImageManager.faceWidth, ImageManager.faceWidth);

        const sx0 = rect.x + 154;
        const wx0 = rect.width - (sx0 + 19.5);
        const sx1 = sx0 + (wx0 / 3);
        const wx1 = rect.width - (sx1 + 19.5);
        const sx2 = sx0 + (wx0 * 2 / 3);
        const wx2 = rect.width - (sx2 + 19.5);
        const sxa = sx0 + (wx0 / 2);
        const wxa = rect.width - (sxa + 19.5);
        const y = rect.y + 2;
        const sy0 = y;
        const sy1 = y + 20;
        const sy2 = y + 40;
        const sy3 = y + 60;
        const sy4 = y + 80;
        const sy5 = y + 100;
        const sy6 = y + 120;

        const pp = actor.currentClass().id == 1 ? "%" : "";
        const prms = [
            DGN.GetParameterNameFromNumber(0) + ": " + pp + Math.round(actor.param(0)),
            DGN.GetParameterNameFromNumber(1) + ": " + pp + Math.round(actor.param(1)),
            DGN.GetParameterNameFromNumber(2) + ": " + pp + Math.round(actor.param(2)),
            DGN.GetParameterNameFromNumber(3) + ": " + pp + Math.round(actor.param(3)),
            DGN.GetParameterNameFromNumber(4) + ": " + pp + Math.round(actor.param(4)),
            DGN.GetParameterNameFromNumber(5) + ": " + pp + Math.round(actor.param(5)),
            DGN.GetParameterNameFromNumber(6) + ": " + pp + Math.round(actor.param(6)),
            DGN.GetParameterNameFromNumber(8) + ": " + pp + Math.round(actor.param(8)),
            DGN.GetParameterNameFromNumber(7) + ": " + pp + Math.round(actor.param(7))
        ];
        const prmsS0 = [
            "Max Tactical Points: " + String(Math.round(actor.maxTp(5))),
            "Tactical Point Rate: %" + String(Math.round( actor.sparam(5) * 100.00000 )),
            "Experience Gain Rate: %" + String(Math.round( actor.sparam(9) * 100.00000 )),
            "Magic Cost Rate: %" + String(Math.round( actor.sparam(4) * 100.00000 ))
        ];

        this.changeTextColor( dragon_color_white );

        this.drawText( actor.name(), sx0, sy0, wx0, "left" );
        this.drawText( actor.nickname(), sx1, sy1, wx1, "left" );
        this.drawText( actor.currentClass().name, sx0, sy1, wx0, "left" );

        this.changeTextColor( dragon_color_yellow );

        this.drawText( prmsS0[0], sx2, sy2, wx2, "left" );
        this.drawText( prmsS0[1], sx2, sy3, wx2, "left" );
        this.drawText( prmsS0[2], sx0, sy3, wx0, "left" );
        this.drawText( prmsS0[3], sx1, sy3, wx1, "left" );

        this.drawText( prms[0], sx0, sy4, wx0, "left" );
        this.drawText( prms[1], sx1, sy4, wx1, "left" );
        this.drawText( prms[2], sx2, sy4, wx2, "left" );
        this.drawText( prms[3], sx0, sy5, wx0, "left" );
        this.drawText( prms[4], sx1, sy5, wx1, "left" );
        this.drawText( prms[5], sx2, sy5, wx2, "left" );
        this.drawText( prms[6], sx0, sy6, wx0, "left" );
        this.drawText( prms[7], sx1, sy6, wx1, "left" );
        this.drawText( prms[8], sx2, sy6, wx2, "left" );

        this.changeTextColor( dragon_color_white );

        const tx = rect.x + 6;
        const tw = rect.width - 16;
        const twh = tw / 2;
        const cw = Math.floor(tw / this.CharWidth());
        const ty = y + 149;
        const th = rect.height;

        if (page == 0) {
            this.changeTextColor( dragon_color_white );

            let p_text = "";
            if (actor.actor().profile.length > 0) p_text += "    " + actor.actor().profile + "\\LB";
            if (actor.currentClass().description.length > 0) p_text += "    " + actor.currentClass().description + "\\LB";
            if (actor.actor().description2.length > 0) p_text += "    " + actor.actor().description2 + "\\LB";
            p_text += "\\LB    " + "To view more information about this character, activate this window.  " +
                "(To \"activate\" a window, click on it with a mouse, or press a space bar, or the \"A\" button on a game controller.)\\LB" +
                "Once the game starts, there will be options during the game to change the order of the members of the party, as well as " +
                "an option to rename the player characters in the party to whatever name you want.";

            this.drawTextEx( p_text.AutoFormat(cw), tx, ty, tw );
        }
        else if (page == 1) {
            this.changeTextColor( dragon_color_white );
            const p_text = actor.race ? actor.race.info : "";
            if (p_text.length > 0) this.drawTextEx( p_text.AutoFormat(cw), tx, ty, tw );
        }
        else if (page == 2) {
            const prmsEX = [
                "Physical Hit Bonus: " + Math.round(actor.xparam(10) * 100.0),
                "Magical Hit Bonus: " + Math.round(actor.xparam(11) * 100.0),
                "Physical Critical Hit Rate: " + Math.round(actor.xparam(12) * 100.0),
                "Magical Critical Hit Rate: " + Math.round(actor.xparam(13) * 100.0),

                "Physical Evade: " + Math.round(actor.xparam(1) * 100.0),
                "Magical Evade: " + Math.round(actor.xparam(4) * 100.0),
                "Physical Critical Evade: " + Math.round(actor.xparam(14) * 100.0),
                "Magical Critical Evade: " + Math.round(actor.xparam(15) * 100.0)
            ];

            this.changeTextColor( dragon_color_yellow );

            this.drawText( prmsEX[0], tx, ty, twh, "left" );
            this.drawText( prmsEX[1], twh, ty, twh, "left" );
            this.drawText( prmsEX[2], tx, ty + 20, twh, "left" );
            this.drawText( prmsEX[3], twh, ty + 20, twh, "left" );
            this.drawText( prmsEX[4], tx, ty + 60, twh, "left" );
            this.drawText( prmsEX[5], twh, ty + 60, twh, "left" );
            this.drawText( prmsEX[6], tx, ty + 80, twh, "left" );
            this.drawText( prmsEX[7], twh, ty + 80, twh, "left" );

            this.changeTextColor( dragon_color_white );
        }
        else if (page == 3) {
            this.changeTextColor( dragon_color_white );

            // console.log(actor);

            let skill_types = [];
            if (actor.race.name.includes("Magic Blood")) {
                this.drawText( "Special Abilities (Magic Blooded):", tx, ty, tw, "left" );
                skill_types = ["Magic Blooded"];
            } else if (actor.race.name.includes("Orc")) {
                if (actor.race.name.includes("Half")) {
                    this.drawText( "Special Abilities (Half Orc):", tx, ty, tw, "left" );
                    skill_types = ["Half Orc"];
                } else {
                    this.drawText( "Special Abilities (Orc):", tx, ty, tw, "left" );
                    skill_types = ["Half Orc", "Orc"];
                }
            } else if (actor.race.name.includes("Elf")) {
                if (actor.race.name.includes("Half")) {
                    this.drawText( "Special Abilities (Half Elf):", tx, ty, tw, "left" );
                    skill_types = ["Half Elf"];
                } else {
                    this.drawText( "Special Abilities (Elf):", tx, ty, tw, "left" );
                    skill_types = ["Half Elf", "Elf", "Elf, Gaze"];
                }
            } else if (actor.race.name.includes("Dragon")) {
                if (actor.race.name.includes("Half")) {
                    this.drawText( "Special Abilities (Half Dragon):", tx, ty, tw, "left" );
                    skill_types = ["Half Dragon", "Half Dragon, Gaze", "Half Dragon, Breath"];
                } else {
                    this.drawText( "Special Abilities (Dragon):", tx, ty, tw, "left" );
                    skill_types = ["Half Dragon", "Half Dragon, Gaze", "Half Dragon, Breath",
                                    "Dragon", "Dragon, Gaze", "Dragon, Breath"];
                }
            } else
                this.drawText( "No Special Abilities.", tx, ty, tw, "left" );

            if (skill_types.length > 0) {
                const list_y = ty + 26;
                const h = th - 169;
                const list_item_h = 34;
                const tx2 = tx + twh;
                const tx2_text = tx2 + 34;
                const num_list_items = Math.floor(h / list_item_h);
                const skills = actor.skills();
                const list = skills.filter( skill => skill_types.includes($dataSystem.skillTypes[skill.stypeId]) );
                const length_left = Math.min(list.length, num_list_items);
                const length_right = Math.max(list.length - length_left, 0);

                for (let i = 0; i < length_left; i++) {
                    const itm = list[i];
                    this.DrawSkillEx(itm, tx, list_y + (list_item_h * i), twh);
                }
                for (let i = length_left; i < Math.min(list.length, num_list_items * num_list_items); i++) {
                    const itm = list[i];
                    this.DrawSkillEx(itm, tx2, list_y + (list_item_h * (i - length_left)), twh);
                }
            }
        }
    }
    else if (dat.text_window) {
        this.changeTextColor( dragon_color_white );

        const rect = this.itemRect( idx );
        let x = rect.x + 8;
        let y = rect.y + 5;
        let w = rect.width - 19.5;
        const cw = Math.floor(w / 9.5);

        if (dat.text_header) {
            this.drawTextEx( dat.text_header, x, y, w );
            y += 40;
        }

        let p_text = "";
        if (dat.text)
            p_text += dat.text + "\\LB";
        p_text += "\\LB    " + "To view more information about anything in this window, activate this window.  " +
            "(To \"activate\" a window, click on it with a mouse, or press a space bar, or the \"A\" button on a game controller.)";

        this.drawTextEx( p_text.AutoFormat(cw), x, y, w );
    }
};
Dgn_Window_ActionList.prototype.actor = function(index) {
    if (!this.data)
        return null;

    const idx = index.clamp(0, this.data.length - 1);
    if (idx != index)
        return null;
    const data = this.data[idx];
    const actor_index = data[0].clamp(0, $dataActors.length - 1);
    if (actor_index < 1)
        return null;

    return $gameActors.actor(actor_index);
};
Dgn_Window_ActionList.prototype.DrawFace = function(index) {
    const actor = this.actor(index);
    if (!actor)
        return;

    const rect = this.itemRect(index);
    const width = ImageManager.faceWidth;
    const height = rect.height;
    this.changePaintOpacity(true);
    this.drawActorFace(actor, rect.x + 1, rect.y + 1, width, height - 2);
};

///-----------------------------------------------------------------------------
/// Dgn_Window_ActionList_Actor
///
/// A window class with a list of options or commands, based upon Dgn_Window_ActionList.
function Dgn_Window_ActionList_Actor() {
    this.initialize(...arguments);
}
Dgn_Window_ActionList_Actor.prototype = Object.create(Dgn_Window_ActionList.prototype);
Dgn_Window_ActionList_Actor.prototype.constructor = Dgn_Window_ActionList_Actor;

Dgn_Window_ActionList_Actor.prototype.initialize = function(rect, data_list, cols=1) {
    Dgn_Window_ActionList.prototype.initialize.call(this, rect, data_list, cols);

    this.loadFaceImages();
};
Dgn_Window_ActionList_Actor.prototype.loadFaceImages = function() {
    if (!this.data)
        return;

    for (const index of this.data) {
        const data = this.data[index];
        const actor = $gameActors.actor( data[0].clamp(1, $dataActors.length - 1) );
        ImageManager.loadFace( actor.faceName() );
    }
};
Dgn_Window_ActionList_Actor.prototype.refresh = function() {
    Window_Selectable.prototype.refresh.call(this);
};
Dgn_Window_ActionList_Actor.prototype.drawActorFace = function(actor, x, y, width, height) {
    this.drawFace(actor.faceName(), actor.faceIndex(), x, y, width, height);
};
Dgn_Window_ActionList_Actor.prototype.itemHeight = function() {
    return 146;
};
Dgn_Window_ActionList_Actor.prototype.drawPendingItemBackground = function(index) {
    if (index === this.index()) {
        const rect = this.itemRect(index);
        const color = ColorManager.pendingColor();
        this.changePaintOpacity(false);
        this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        this.changePaintOpacity(true);
    }
};
Dgn_Window_ActionList_Actor.prototype.actor = function(index) {
    if (!this.data)
        return null;

    const idx = index.clamp(0, this.data.length - 1);
    if (idx != index)
        return null;
    const rect = this.itemLineRect(index);
    const data = this.data[idx];
    const actor_index = data[0].clamp(0, $dataActors.length - 1);
    if (actor_index < 1)
        return null;

    return $gameActors.actor(actor_index);
};
Dgn_Window_ActionList_Actor.prototype.DrawFace = function(index) {
    const actor = this.actor(index);
    if (!actor)
        return;

    const rect = this.itemRect(index);
    const width = ImageManager.faceWidth;
    const height = rect.height;
    this.changePaintOpacity(true);
    this.drawActorFace(actor, rect.x + 1, rect.y + 1, width, height - 2);
};
Dgn_Window_ActionList_Actor.prototype.TextWidth = function(index) {
    return 152;
};
Dgn_Window_ActionList_Actor.prototype.DrawItemInfo = function(index) {
    const actor = this.actor(index);
    if (!actor)
        return;

    const rect = this.itemRect(index);
    const x = rect.x + 150;
    const y = rect.y - 6;
    const text_width = this.TextWidth();
    const line_height = 20;

    this.drawText( actor.name(), x, y, text_width );
    this.drawText( actor.currentClass().name, x, y + line_height, text_width );
    this.drawText( "Level: " + actor.level, x, y + (line_height * 3), text_width );
};
Dgn_Window_ActionList_Actor.prototype.drawItem = function(index) {
    if (!this.data)
        return;

    const idx = index.clamp(0, this.data.length - 1);
    if (idx != index)
        return;

    const data = this.data[idx];

    this.drawPendingItemBackground(index);
    this.DrawFace(data[0]);
    this.DrawItemInfo(data[0]);
};

///-----------------------------------------------------------------------------
/// Dgn_Window_ActionList_PartyInitActor
///
/// A window class with a list of options or commands, based upon Dgn_Window_ActionList_Actor.
function Dgn_Window_ActionList_PartyInitActor() {
    this.initialize(...arguments);
}
Dgn_Window_ActionList_PartyInitActor.prototype = Object.create(Dgn_Window_ActionList_Actor.prototype);
Dgn_Window_ActionList_PartyInitActor.prototype.constructor = Dgn_Window_ActionList_PartyInitActor;

Dgn_Window_ActionList_PartyInitActor.prototype.initialize = function(rect, data_list, cols, party_mgr, is_party) {
    Dgn_Window_ActionList_Actor.prototype.initialize.call(this, rect, data_list, cols);

    this.party_manager = party_mgr;
    this.is_party = is_party;
    this._pendingIndex = -1;

    this.refresh();
};
Dgn_Window_ActionList_PartyInitActor.prototype.maxItems = function() {
    if (!this.party_manager)
        return 1;

    if (this.is_party == true)
        return this.party_manager.SizeParty();
    else
        return this.party_manager.SizePool();
};
Dgn_Window_ActionList_PartyInitActor.prototype.numVisibleRows = function() {
    return 7;
};
Dgn_Window_ActionList_PartyInitActor.prototype.maxCols = function() {
    return 1;
};
Dgn_Window_ActionList_PartyInitActor.prototype.TextWidth = function() {
    return 230;
};
Dgn_Window_ActionList_PartyInitActor.prototype.Width = function() {
    return 146 + this.TextWidth() + 4; // 340
};
Dgn_Window_ActionList_PartyInitActor.prototype.actor = function(index) {
    if (!this.party_manager)
        return null;
    if (index < 0)
        return null;

    if (this.is_party == true) {
        const party = this.party_manager.Party();

        if (index >= party.length) return null;

        return $gameActors.actor(party[index]);
    }
    else {
        const pool = this.party_manager.Pool();

        if (index >= pool.length) return null;

        return $gameActors.actor(pool[index]);
    }
};
Dgn_Window_ActionList_PartyInitActor.prototype.drawItem = function(index) {
    const actor = this.actor(index);
    if (!actor)
        return;

    this.drawPendingItemBackground(index);
    this.drawItemImage(index);
    this.drawItemStatus(index);
};
Dgn_Window_ActionList_PartyInitActor.prototype.drawPendingItemBackground = function(index) {
    if (index == this._pendingIndex) {
        const rect = this.itemRect(index);
        const color = ColorManager.pendingColor();
        this.changePaintOpacity(false);
        this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        this.changePaintOpacity(true);
    }
};
Dgn_Window_ActionList_PartyInitActor.prototype.drawItemImage = function(index) {
    const actor = this.actor(index);
    if (!actor)
        return;

    const rect = this.itemRect(index);
    const width = ImageManager.faceWidth;
    const height = rect.height;
    this.changePaintOpacity(true);
    this.drawActorFace(actor, rect.x + 1, rect.y + 1, width, height - 2);
};
Dgn_Window_ActionList_PartyInitActor.prototype.drawItemStatus = function(index) {
    if (!this.party_manager)
        return;

    const actor = this.actor(index);
    const rect = this.itemRect(index);
    const x = rect.x + 148;
    const y = rect.y - 6;
    const text_width = this.TextWidth();
    const line_height = 20;
    const cls = actor.currentClass();

    let txt0 = actor.name();
    let txt1 = actor.nickname();
    let txt2 = "";
    let txt3 = "";
    let txt4 = "";
    let txt5 = "";
    let txt6 = "";
    if (this.is_party == true) {
        if (cls.id == 1) {
            txt3 = "No Class Assigned";
            txt5 = "Please select a class";
            txt6 = "   for this character";
        } else {
            txt2 = cls.name;
            if (this.party_manager.IsPartyReady())
                txt4 = "Ready to go";
        }
    } else {
        txt2 = "No Class Assigned";
        if (this.party_manager.SizeParty() < dragon_max_starting_party_members)
            txt4 = "Available";
    }

    this.drawText( txt0, x, y, text_width );
    this.drawText( txt1, x, y + line_height, text_width );
    this.drawText( txt2, x, y + (line_height * 2), text_width );
    this.drawText( txt3, x, y + (line_height * 3), text_width );
    this.drawText( txt4, x, y + (line_height * 4), text_width );
    this.drawText( txt5, x, y + (line_height * 5), text_width );
    this.drawText( txt6, x, y + (line_height * 6), text_width );
};
