Window_EquipItem.prototype.lineHeight = function() {
    return 20;
};
Window_EquipItem.prototype.itemHeight = function() {
    return 43;
};
Window_EquipItem.prototype.item = function() {
    return this.itemAt(this.index());
};
Window_EquipItem.prototype.itemAt = function(index) {
    return this._data && index >= 0 ? this._data[index] : null;
};
Window_EquipItem.prototype.drawItem = function(index) {
    const item = this.itemAt(index);
    if (item) {
        const rect = this.itemRect(index);
        this.changePaintOpacity(1);
        this.DrawItemScaled_NameLevelUses(item, rect.x + 4, rect.y + 5, rect.width - 3);
    }
};
Window_EquipItem.prototype.includes = function(item) {
    if (item === null) {
        return true;
    }
    return (
        this._actor &&
        this._actor.canEquip(item) &&
        item.equip_type === this.etypeId()
    );
};
Window_EquipItem.prototype.makeItemList = function() {
    /*
    this._data = [null];
    if (this._category === "equipment") {
        this._data = $gameParty.InventoryEquipment().filter(item => this.includes(item));
    }
    else if (this._category === "item") {
        this._data = $gameParty.InventoryItems();
        this._data.push(null);
    }
    */
    const idx = this._slotId.clamp(0, this._actor._inventory_slots.length - 1);
    const equip_is_item = this._actor._inventory_slots[idx].shared_item;
    if (!equip_is_item)
        this._data = $gameParty.InventoryEquipment().filter(item => this.includes(item));
    else
        this._data = $gameParty.InventoryItems();
};
Window_EquipItem.prototype.etypeId = function() {
    if (this._actor && this._slotId >= 0) {
        return this._actor.GetInventorySlotEquipType(this._slotId);
    } else {
        return 0;
    }
};
Window_EquipItem.prototype.updateHelp = function() {
    Window_ItemList.prototype.updateHelp.call(this);
    if (this._actor && this._statusWindow && this._slotId >= 0) {
        // if (this.index() < 0) return;
        const actor = JsonEx.makeDeepCopy(this._actor);
        actor.ClearInventorySlot(this._slotId);
        const item = this.item() ? this.item().Deep() : null;
        actor.AddInventorySlotItem(item, this._slotId);
        this._statusWindow.setTempActor(actor);
    }
};

