Game_Actor.prototype.CanEquipInventorySlot = function(item, slot_index) {
    if (item === null) return true;
    if (!slot_index.IsWithin(0, this._inventory_slots.length - 1)) return false;
    let slot = this._inventory_slots[slot_index];
    const is_item = item.itypeId ? true : false;
    if (is_item != slot.shared_item) return false;
    else if (is_item === true && slot.shared_item === true) return true;
    // if (item.itypeId) return false;
    if (item.equip_type != slot.equip_type) return false;
    const is_weapon = item.wtypeId ? true : false;
    const is_armor = item.atypeId ? true : false;
    if (is_weapon != slot.weapon) return false;
    if (is_armor != slot.armor) return false;
    if (!this.CanEquipSubType(item)) return false;
    return true;
};
Game_Actor.prototype.InventorySlotItem = function(slot_index) {
    if (!slot_index.IsWithin(0, this._inventory_slots.length)) return null;
    return this._inventory_slots[slot_index].item;
};
Game_Actor.prototype.AddInventorySlotItem = function(item, slot_index) {
    if (this.CanEquipInventorySlot(item, slot_index) === false) return;
    let slot = this._inventory_slots[slot_index];
    if (slot.item != null) return;
    slot.item = item ? item.Deep() : null;
    this.UpdateCombinedData();
};
Game_Actor.prototype.ClearInventorySlot = function(slot_index) {
    let slot = this._inventory_slots[slot_index];
    if (!slot_index.IsWithin(0, this._inventory_slots.length)) return;
    slot.item = null;
    slot.skills = [];
    this.UpdateCombinedData();
};
Game_Actor.prototype.ClearInventorySlots = function() {
    for (let slot_index = 0; slot_index < this._inventory_slots.length; slot_index++) {
        let slot = this._inventory_slots[slot_index];
        slot.item = null;
        slot.item.skills = [];
    }
    this.UpdateCombinedData();
};
Game_Actor.prototype.GetInventorySlotCount = function() {
    return this._inventory_slots.length;
};
Game_Actor.prototype.GetInventorySlotDisabled = function(index) {
    if (index.IsWithin(0, this._inventory_slots.length - 1))
        return this._inventory_slots[index].disabled;
    else
        return false;
};
Game_Actor.prototype.GetInventorySlotName = function(index) {
    if (index.IsWithin(0, this._inventory_slots.length - 1))
        return this._inventory_slots[index].name;
    else
        return "";
};
Game_Actor.prototype.GetInventorySlotNames = function() {
    return this._inventory_slots.map(slot => slot.name);
};
Game_Actor.prototype.GetInventorySlotItem = function(index) {
    if (index.IsWithin(0, this._inventory_slots.length - 1))
        return this._inventory_slots[index].item;
    else
        return null;
};
Game_Actor.prototype.GetInventorySlotItems = function() {
    return this._inventory_slots.map(slot => slot.item);
};
Game_Actor.prototype.GetInventorySlotEquipType = function(index) {
    if (index.IsWithin(0, this._inventory_slots.length - 1))
        return this._inventory_slots[index].equip_type;
    else
        return 0;
};
Game_Actor.prototype.ClearInventory = function() {
    for (let i = 0; i < this._inventory_slots.length; i++) {
        if (!this._inventory_slots[i].item) continue;
        const success = $gameParty.InventoryAddItem(this._inventory_slots[i].item);
        if (!success) continue;
        this._inventory_slots[i].item = null;
    }
    this.UpdateCombinedData();
};
Game_Actor.prototype.isEquipChangeOk = function(index) {
    return (
        !this.isEquipTypeLocked(this._inventory_slots[index].equip_type) &&
        !this.isEquipTypeSealed(this._inventory_slots[index].equip_type)
    );
};
Game_Actor.prototype.releaseUnequippableItems = function(forcing) {
    for (let i = 0; i < this._inventory_slots.length; i++) {
        if (!this._inventory_slots[i].item) continue;
        if (this._inventory_slots[i].shared_item === true) continue;
        if (this.canEquip(this._inventory_slots[i].item)) continue;
        if (!forcing) $gameParty.InventoryAddItem(this._inventory_slots[i].item.Deep());
        this._inventory_slots[i].item = null;
    }
};
Game_Actor.prototype.InitRace = function() {
    // this._race = $dataActors[this._actorId].race;
    this._race = DGN.GetRaceFromText(this.actor().nickname);
    if (!this._race) this._race = $dataRaces[0];

    this.UpdateRaceSkills();
    this.UpdateCombinedData();
    /*
    this._race = null;
    let r = $dataActors[this._actorId].race;
    if (!r) r = 1;
    */
    /*
    const races = $dataRaces.map( rc => rc.race );
    const r_index = races.indexOf(r);

    this._race = $dataRaces[r_index >= 0 ? r_index : 0];
    */
    /*
    this._race = $dataRaces.find(rc => rc.race == r);
    this.UpdateRaceSkills();
    */
};
Game_Actor.prototype.GetRace = function() {
    return this._race;
};
Game_Actor.prototype.GetRacetext = function() {
    return this._race ? this._race.name : $dataActors[this._actorId].racetext;
};
Game_Actor.prototype.UpdateRaceSkills = function() {
    this._race_skills = [];
    if (!this._race) return;
    const race_skills = this._race.traits.filter( t => t.code == Game_BattlerBase.TRAIT_SKILL_ADD ).map( t => t.dataId );
    const race_learned_skills = this._race.learnings.filter( skill => skill.level <= this.level ).map( skill => skill.skillId );

    for (const id of race_skills) {
        if (!this._race_skills.includes(id))
            this._race_skills.push(id);
    }
    for (const id of race_learned_skills) {
        if (!this._race_skills.includes(id))
            this._race_skills.push(id);
    }

    // console.log("Actor: " + this.name() + " has updated race skills.", this._race_skills);
};
Game_Actor.prototype.skills = function() {
    const list = [];
    const skills = this._skills.concat(this.addedSkills(), this._race_skills).Deep();
    const inventory_skills = this.combined_data ? this.combined_data.skills.Deep() : null;
    for (const id of skills) {
        if ( !list.some(s => s.id == id) ) {
            let skill = $dataSkills[id].Deep();
            skill.level = this.level;
            list.push(skill);
        }
    }
    if (!inventory_skills) return list;
    const list_ids = list.map(i => i.id);
    for (let skill of inventory_skills) {
        if (list.some(s => s.id == skill.id)) {
            let existing_skill = list[list.indexOf(skill)];
            if (skill.level > existing_skill.level) existing_skill.level = Number(skill.level);
        } else
            list.push(skill.Deep());
    }
    return list;
};
Game_Actor.prototype.skillsInnate = function() {
    const list = [];
    const skills = this._skills.concat(this.addedSkills(), this._race_skills).Deep();
    for (const id of skills) {
        if ( !list.some(s => s.id == id) ) {
            let skill = $dataSkills[id].Deep();
            skill.level = this.level;
            list.push(skill);
        }
    }
    return list;
};
Game_Actor.prototype.skillsEquipment = function() {
    const list = [];
    const inventory_skills = this.combined_data ? this.combined_data.skills.Deep() : null;
    if (!inventory_skills) return list;
    for (let skill of inventory_skills) {
        if (list.some(s => s.id == skill.id)) {
            let existing_skill = list[list.indexOf(skill)];
            if (skill.level > existing_skill.level) existing_skill.level = Number(skill.level);
        } else
            list.push(skill.Deep());
    }
    return list;
};
Game_Actor.prototype.traitObjects = function() {
    const objects = Game_Battler.prototype.traitObjects.call(this);
    objects.push(this.actor(), this.currentClass());
    if (this._race)
        objects.push(this._race);
    objects.push({traits: this.combined_data.traits});
    // objects.push(this.combined_data);
    if (this.race) {
        if (this.race.race == Game_BattlerBase.RACE_CLOUD_WARRIOR_CLAN_M || this.race.race == Game_BattlerBase.RACE_RAGE_ASSAULT_CLAN_M) {
            for (let object of objects) {
                for (let trait of object.traits) {
                    if (trait.code == Game_BattlerBase.TRAIT_EQUIP_ATYPE) {
                        if (trait.dataId == DRAGON_ARMOR_SHIELD_LIGHT) trait.dataId = DRAGON_ARMOR_CLAN_SHIELD_LIGHT;
                        else if (trait.dataId == DRAGON_ARMOR_SHIELD_MEDIUM) trait.dataId = DRAGON_ARMOR_CLAN_SHIELD_MEDIUM;
                        else if (trait.dataId == DRAGON_ARMOR_SHIELD_HEAVY) trait.dataId = DRAGON_ARMOR_CLAN_SHIELD_HEAVY;
                    }
                }
            }
        }
    }
    /*
    for (const item of this._inventory_slots()) {
        if (item) {
            objects.push(item);
        }
    }
    */
    return objects;
};
Game_Actor.prototype.ResetUsageTraits = function() {
    this.item_usage_traits = {
        skill_slot: -1,
        skill_level: -1,
        aim_add: 0,
        aim_multiply: 1.0,
        critical_chance_multiply: 1.0,
        critical_damage_multiply: 1.0,
        attack_damage_add: 0,
        attack_damage_multiply: 1.0,
        target_defense_add: 0,
        target_defense_multiply: 1.0
    };
};
Game_Actor.prototype.CustomTraits = function() {
    return this.combined_traits.ctraits;
};
Game_Actor.prototype.UsageTraits = function() {
    return this.item_usage_traits;
};
Game_Actor.prototype.CalcUsageTraits = function(item_in) {
    this.ResetUsageTraits();
    if (!item_in) return;
    let item = null;
    let active_slot = -1;
    let active_level = -1;

    if (item_in.stypeId) {
        if (!item_in.equipment_slot) return;
        item = this.InventorySlotItem(item_in.equipment_slot);
        active_slot = item_in.equipment_slot ? item_in.equipment_slot : -1;
        active_level = item_in.level ? item_in.level : -1;
    } else
        item = item_in;

    if (!item) return;
    if (!item.level) return;
    if (!item.usage_traits) return;
    const level_factor = ((item.level - 1).clamp(0, dragon_max_item_levels - 1) / (dragon_max_item_levels - 1).clamp(1, 50000)).clamp(0.0, 1.0);
    try {
        this.item_usage_traits = {
            skill_slot: active_slot,
            skill_level: active_level,
            aim_add: DGN.LerpSkew(
                item.usage_traits.aim_add[0], item.usage_traits.aim_add[1],
                level_factor, item.usage_traits.level_lerp_skew),
            aim_multiply: DGN.LerpSkew(
                item.usage_traits.aim_multiply[0], item.usage_traits.aim_multiply[1],
                level_factor, item.usage_traits.level_lerp_skew),
            critical_chance_multiply: DGN.LerpSkew(
                item.usage_traits.critical_chance_multiply[0], item.usage_traits.critical_chance_multiply[1],
                level_factor, item.usage_traits.level_lerp_skew),
            critical_damage_multiply: DGN.LerpSkew(
                item.usage_traits.critical_damage_multiply[0], item.usage_traits.critical_damage_multiply[1],
                level_factor, item.usage_traits.level_lerp_skew),
            attack_damage_add: DGN.LerpSkew(
                item.usage_traits.attack_damage_add[0], item.usage_traits.attack_damage_add[1],
                level_factor, item.usage_traits.level_lerp_skew),
            attack_damage_multiply: DGN.LerpSkew(
                item.usage_traits.attack_damage_multiply[0], item.usage_traits.attack_damage_multiply[1],
                level_factor, item.usage_traits.level_lerp_skew),
            target_defense_add: DGN.LerpSkew(
                item.usage_traits.target_defense_add[0], item.usage_traits.target_defense_add[1],
                level_factor, item.usage_traits.level_lerp_skew),
            target_defense_multiply: DGN.LerpSkew(
                item.usage_traits.target_defense_multiply[0], item.usage_traits.target_defense_multiply[1],
                level_factor, item.usage_traits.level_lerp_skew)
        };
    } catch (e) {
        console.log( item, String(e) );
    };
};
Game_Actor.prototype.changeExp = function(exp, show) {
    if ( !this._exp[this._classId] ) this._exp[this._classId] = 0;
    var exp_change = exp - this._exp[this._classId];

    if ( exp_change > 0 ) {
        if ( ($gameSystem.average_actor_level >= $gameSystem.soft_level_cap) && (this._level >= ($gameSystem.average_actor_level * 0.75)) )
            exp_change *= 0.001;
    }

    this._exp[this._classId] = Math.max( this._exp[this._classId] + exp_change, 0 );

    const lastLevel = this._level;
    const lastSkills = this.skills();
    while (!this.isMaxLevel() && this.currentExp() >= this.nextLevelExp()) {
        this.levelUp();
    }
    while (this.currentExp() < this.currentLevelExp()) {
        this.levelDown();
    }
    if (this.level != lastLevel) this.UpdateRaceSkills();
    if (show && this._level > lastLevel) {
        this.displayLevelUp(this.findNewSkills(lastSkills));
    }
    this.refresh();
};
Game_Actor.prototype.levelUp = function() {
    this._level++;
    for (const learning of this.currentClass().learnings) {
        if (learning.level === this._level) {
            this.learnSkill(learning.skillId);
        }
    }

    DGN.CalculateAverageActorLevel();
};
