Game_Actor.prototype.ParamBaseForLevel = function(paramId, level) {
    const level_factor = this.GetNormalizedLevel();
    let value = DGN.LerpSkew(100.0, 100.0 * dragon_max_stat_multiplier, level_factor, dragon_actor_parameter_skew);
    if (paramId == 8) value = Math.round(value * this.currentClass().magic_focus_param_mult * 0.01);
    // value += this.combined_data.params[paramId];
    // console.log(this.combined_data);
    return value;
};
