Game_Actor.prototype.paramBase = function(paramId) {
    return this.ParamBaseForLevel(paramId, this._level) + this.perms.param_add[paramId];
};
Game_Actor.prototype.paramPlus = function(paramId) {
    return Game_Battler.prototype.paramPlus.call(this, paramId) + this.combined_data.params[paramId];
};
Game_Actor.prototype.param = function(paramId) {
    if (paramId == DRAGON_PARAM_MAGIC_FOCUS) return this.GetAtr_MagicFocus();
    const value = (this.ParamBaseForLevel(paramId, this._level) + this.perms.param_add[paramId]
        + Game_Battler.prototype.paramPlus.call(this, paramId) + this.combined_data.params[paramId])
        * this.paramRate(paramId)
        * this.paramBuffRate(paramId) * this.perms.param_multiply[paramId] * (paramId == 0 ? dragon_master_hp_adjust : 1);
    return Math.round(Math.max(value, 1));

    /*
    let value = ((this.paramBasePlus(paramId) + this.combined_data.params[paramId]) * this.paramRate(paramId)) * this.paramBuffRate(paramId) * this.perms.param_multiply[paramId];
    if (paramId == 0) value = Math.round(value * dragon_master_hp_adjust);
    return Math.round(Math.max(value, 1));
    */
};
Game_Actor.prototype.setLastMenuSkill = function(skill) {
    this._lastMenuSkill.setObject( $dataSkills[skill.id] );
};
Game_Actor.prototype.setLastBattleSkill = function(skill) {
    this._lastBattleSkill.setObject( $dataSkills[skill.id] );
};
Game_Actor.prototype.GetDp = function() {
    var pct = this._hp / this.param(0);
    pct = Math.pow(pct, 2.00000);
    pct = 1.00000 - pct;
    pct *= dragon_combat_hp_dampening;
    pct = 1.00000 - pct;

    return pct;
};
Game_Actor.prototype.lerp = function(f0, f1) {
    return DGN.Lerp( f0, f1, (this.level - 1) / (dragon_max_character_level - 1.0) );
};
Game_Actor.prototype.lerpBook = function(f0, f1) {
    return this.lerpItem(f0, f1);
};
Game_Actor.prototype.lerpItem = function(f0, f1) {
    if (this.item_usage_traits.skill_level) {
        if (this.item_usage_traits.skill_level > 0)
            return DGN.Lerp(f0, f1, Math.max(this.item_usage_traits.skill_level - 1.0, 0.0) / Math.max(dragon_max_item_levels - 1.0, 1.0));
    }
    return DGN.Lerp( f0, f1, Math.max(this.level - 1.0, 0.0) / Math.max(dragon_max_character_level - 1.0, 1.0) );
};
Game_Actor.prototype.GetLevelMultiplierForEquip = function(slot_index) {
    return (this.InventorySlotItem(slot_index).level - 1.0).clamp(0, dragon_max_item_levels - 1.0) / (dragon_max_item_levels - 1.0);
    /*
    var levelFactor = 1;
    if ( this.equips()[slot_index] ) var levelFactor = this.equips()[slot_index].level;

    levelFactor -= 1;
    levelFactor = Math.max(levelFactor, 0);
    levelFactor /= dragon_max_item_levels - 1.0;

    if ( slot_index < 0 ) {
        levelFactor = (this.level - 1) / (dragon_max_character_level - 1.00000);
    }

    return levelFactor;
    */
};
