Game_Actor.prototype.a_shotgun = function(multiplier_low, multiplier_high, opponent, opponent_defense, opponent_def_multiplier) {
    var pct = opponent.hp / opponent.mhp;
    pct *= dragon_combat_hp_dampening_inverse;
    pct = 1.00000 - pct;

    let attack = this.sa1;
    let defend = opponent_defense;
    if (this.attacker_traits) {
        attack = Math.max(attack + this.attacker_traits.attack_damage_add, 0.0) * this.attacker_traits.attack_damage_multiply;
        defend = Math.max(defend + this.attacker_traits.target_defense_add, 0.0) * this.attacker_traits.target_defense_multiply;
    }

    const attack_value = attack * DGN.Lerp(multiplier_low, multiplier_high, this.GetLevelValueForSkill(this._active_skill_id)) * dragon_attack_adjust_static * pct;
    const defense_value = defend * opponent_def_multiplier * dragon_defense_adjust_static;
    const total = attack_value + defense_value;
    return attack_value * attack_value / total;
};
Game_Actor.prototype.a_static = function(multiplier_low, multiplier_high, opponent, opponent_defense, opponent_def_multiplier) {
    var pct = opponent.hp / opponent.mhp;
    pct *= dragon_combat_hp_dampening_inverse;
    pct = 1.00000 - pct;

    let attack = this.sa1;
    let defend = opponent_defense;
    if (this.attacker_traits) {
        attack = Math.max(attack + this.attacker_traits.attack_damage_add, 0.0) * this.attacker_traits.attack_damage_multiply;
        defend = Math.max(defend + this.attacker_traits.target_defense_add, 0.0) * this.attacker_traits.target_defense_multiply;
    }

    const attack_value = attack * DGN.Lerp(multiplier_low, multiplier_high, this.GetLevelValueForSkill(this._active_skill_id)) * dragon_attack_adjust_static;
    const defense_value = defend * opponent_def_multiplier * dragon_defense_adjust_static;
    return (attack_value * pct) - defense_value;
};
