Game_Enemy.prototype.initialize = function(enemyId, x, y) {
    Game_Battler.prototype.initialize.call(this);

    // Custom DGN stuff
    this.level = 1;
    this.initial_tp = 50;
    this.attack_levels = [1];
    this.level_factor = 0.01;
    this.custom_traits = DGN.MakeInitializedCustomTraits();
    this.perms = {
        param_add: Array(9).fill(0),
        param_multiply: Array(9).fill(1.0),
        xparam_add: Array(10).fill(0),
        xparam_multiply: Array(10).fill(1.0),
        sparam_add: Array(10).fill(0),
        sparam_multiply: Array(10).fill(1.0),
        custom_traits: DGN.MakeInitializedCustomTraits()
    };

    this._active_skill_id = -1;
    this._active_skill_index = -1;

    this.setup(enemyId, x, y);
};
