Window_ShopBuy.prototype.processHandling = function() {
    if (this.isOpenAndActive()) {
        if (this.isOkEnabled() && this.isOkTriggered()) {
            return this.processOk();
        }
        if (this.isCancelEnabled() && this.isCancelTriggered()) {
            return this.processCancel();
        }
        if (this.isHandled("pagedown") && Input.isTriggered("pagedown")) {
            return this.processPagedown();
        }
        if (this.isHandled("pageup") && Input.isTriggered("pageup")) {
            return this.processPageup();
        }
        if (this.isHandled("info") && Input.isTriggered("shift")) {
            return this.ProcessItemInfo();
        }
    }
};
Window_ShopBuy.prototype.ProcessItemInfo = function() {
    this.updateInputData();
    this.deactivate();
    this.callItemInfoHandler();
};
Window_ShopBuy.prototype.callItemInfoHandler = function() {
    this.callHandler("info");
};
Window_ShopBuy.prototype.GetPrice = function(item) {
    var price = item.price;

    if ( item.food_price )
        price = DGN.CalcFoodPrice( item.food_price );
    else if ( item.leveled_by_chapter_price == true )
        price = DGN.CalcLevelByChapterPrice( price, item.level );

    return Math.ceil(price);
};
