Window_BattleStatus.prototype.update = function() {
    if ( DGN._currentTargetedActor > -1 ) {
        for (let i = 0; i < $gameParty.battleMembers().length; i++) this.deselect(i);

        this.select( DGN._currentTargetedActor );

        if ( DGN._currentTargetedActor > 999 ) DGN._currentTargetedActor = -1;

        if ( DGN._currentTargetedActor > -1 ) {
            const actor_height = this.itemRect( 0 ).height * Math.floor( DGN._currentTargetedActor * 0.1251 );
            this.smoothScrollTo( 0, actor_height );
        }
    }

    Window_StatusBase.prototype.update.call(this);
    if ($gameTemp.isBattleRefreshRequested()) {
        this.preparePartyRefresh();
    }
};
Window_BattleStatus.prototype.updateArrows = function() {
    this.downArrowVisible = false;
    this.upArrowVisible = false;
};

