Window_EquipStatus.prototype.drawParamName = function(x, y, paramId) {
    const width = this.paramX() - this.itemPadding() * 2;

    this.changeTextColor(dragon_color_gold);
    if ( paramId <= 7 ) this.DrawTextScaled(TextManager.param(paramId), x, y, width);
    else if ( paramId == DRAGON_PARAM_MAGIC_FOCUS ) this.DrawTextScaled("Magic Focus", x, y, width);
    this.resetTextColor();
};
Window_EquipStatus.prototype.drawParamNameCustom = function(x, y, cparamId) {
    const width = this.paramX() - this.itemPadding() * 2;
    this.changeTextColor(dragon_color_gold);

    if (cparamId == 0) this.DrawTextScaled("Max Tactical Points", x, y, width);
    else if (cparamId == 1) this.DrawTextScaled("Physical Hit Bonus", x, y, width);
    else if (cparamId == 2) this.DrawTextScaled("Magical Hit Bonus", x, y, width);

    this.resetTextColor();
};
Window_EquipStatus.prototype.drawParamNameX = function(x, y, xparamId) {
    const width = this.paramX() - this.itemPadding() * 2;
    this.changeTextColor(dragon_color_gold);
    if (xparamId == 0) {this.DrawTextScaled("Hit Rate", x, y, width);}
    else if (xparamId == 1) {this.DrawTextScaled("Physical Evade", x, y, width);}
    else if (xparamId == 2) {this.DrawTextScaled("Crit. Hit Rate", x, y, width);}
    else if (xparamId == 3) {this.DrawTextScaled("Critical Evade", x, y, width);}
    else if (xparamId == 4) {this.DrawTextScaled("Magical Evade", x, y, width);}
    else if (xparamId == 5) {this.DrawTextScaled("Magic Reflect", x, y, width);}
    else if (xparamId == 6) {this.DrawTextScaled("Counter Attack", x, y, width);}
    else if (xparamId == 7) {this.DrawTextScaled("HP Regen.", x, y, width);}
    else if (xparamId == 8) {this.DrawTextScaled("MP Regen.", x, y, width);}
    else if (xparamId == 9) {this.DrawTextScaled("TP Regen.", x, y, width);}
    else if ( xparamId == 12 ) this.DrawTextScaled("Phys. Crit. Hit Rate", x, y, width);
    else if ( xparamId == 13 ) this.DrawTextScaled("Mag. Crit. Hit Rate", x, y, width);
    else if ( xparamId == 14 ) this.DrawTextScaled("Phys. Critical Evade", x, y, width);
    else if ( xparamId == 15 ) this.DrawTextScaled("Mag. Critical Evade", x, y, width);

    this.resetTextColor();
};
Window_EquipStatus.prototype.drawParamNameS = function(x, y, sparamId) {
    const width = this.paramX() - this.itemPadding() * 2;
    this.changeTextColor(dragon_color_gold);
    if (sparamId == 0) {this.DrawTextScaled("Targeted Rate", x, y, width);}
    else if (sparamId == 1) {this.DrawTextScaled("Guard Effect", x, y, width);}
    else if (sparamId == 2) {this.DrawTextScaled("Heal Rate, Spells", x, y, width);}
    else if (sparamId == 3) {this.DrawTextScaled("Heal Rate, Potions", x, y, width);}
    else if (sparamId == 4) {this.DrawTextScaled("MP Cost Rate", x, y, width);}
    else if (sparamId == 5) {this.DrawTextScaled("TP Gain Rate", x, y, width);}
    else if (sparamId == 6) {this.DrawTextScaled("Physical Damage", x, y, width);}
    else if (sparamId == 7) {this.DrawTextScaled("Magical Damage", x, y, width);}
    else if (sparamId == 8) {this.DrawTextScaled("Floor Damage", x, y, width);}
    else if (sparamId == 9) {this.DrawTextScaled("EXP Gain Rate", x, y, width);}

    this.resetTextColor();
};
Window_EquipStatus.prototype.drawCurrentParam = function(x, y, paramId) {
    const paramWidth = this.paramWidth();
    var v = 0;
    if ( paramId <= 7 ) v = Math.round( Math.max(Math.min(this._actor.param(paramId), 9999999), -999999) ).toLocaleString();
    else if ( paramId == DRAGON_PARAM_MAGIC_FOCUS ) v = Math.round( Math.max(Math.min(this._actor.magic_focus, 9999999), -999999) ).toLocaleString();

    this.resetTextColor();
    this.DrawTextScaled( v, x, y, paramWidth, "right" );
};
Window_EquipStatus.prototype.drawCurrentParamCustom = function(x, y, cparamId) {
    const paramWidth = this.paramWidth();

    var value = 0;
    if ( cparamId == DRAGON_CUSTOM_PARAM_MAX_TACTICAL_POINTS ) var value = this._actor.maxTp();
    else if ( cparamId == DRAGON_CUSTOM_PARAM_PHYSICAL_HIT_BONUS ) var value = this._actor.hit_rate_physical * 100.00000;
    else if ( cparamId == DRAGON_CUSTOM_PARAM_MAGICAL_HIT_BONUS ) var value = this._actor.hit_rate_magical * 100.00000;

    const v = Math.round( Math.max(Math.min(value, 9999999), -999999) ).toLocaleString();
    this.resetTextColor();
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawCurrentParamX = function(x, y, xparamId) {
    const paramWidth = this.paramWidth();
    const value = this._actor.xparam(xparamId);
    const v = Math.round( Math.max(Math.min(value * 100, 999999), -99999) ).toLocaleString();
    this.resetTextColor();
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawCurrentParamS = function(x, y, sparamId) {
    const paramWidth = this.paramWidth();
    const value = this._actor.sparam(sparamId);
    const v = Math.round( Math.max(Math.min(value * 100, 999999), -99999) ).toLocaleString();
    this.resetTextColor();
    this.DrawTextScaled(v + "%", x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawRightArrow = function(x, y) {
    const rightArrowWidth = this.rightArrowWidth();
    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled("\u2192", x, y, rightArrowWidth, "center");
};
Window_EquipStatus.prototype.drawNewParam = function(x, y, paramId) {
    const paramWidth = this.paramWidth();
    var newValue = 0;
    var diffValue = 0;

    if ( paramId <= 7 ) {
        newValue = this._tempActor.param(paramId);
        diffValue = newValue - this._actor.param(paramId);
    }
    else if ( paramId == DRAGON_PARAM_MAGIC_FOCUS ) {
        newValue = this._tempActor.magic_focus;
        diffValue = newValue - this._actor.magic_focus;
    }

    const v = Math.round( Math.max(Math.min(newValue, 9999999), -999999) ).toLocaleString();
    this.changeTextColor(ColorManager.paramchangeTextColor(diffValue));
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawNewParamCustom = function(x, y, cparamId) {
    const paramWidth = this.paramWidth();
    var newValue = 0;
    var diffValue = 0;

    if ( cparamId == DRAGON_CUSTOM_PARAM_MAX_TACTICAL_POINTS ) {
        newValue = this._tempActor.maxTp();
        diffValue = newValue - this._actor.maxTp();
    }
    else if ( cparamId == DRAGON_CUSTOM_PARAM_PHYSICAL_HIT_BONUS ) {
        newValue = this._tempActor.hit_rate_physical;
        diffValue = newValue - this._actor.hit_rate_physical;
        newValue *= 100.00000;
    }
    else if ( cparamId == DRAGON_CUSTOM_PARAM_MAGICAL_HIT_BONUS ) {
        newValue = this._tempActor.hit_rate_magical;
        diffValue = newValue - this._actor.hit_rate_magical;
        newValue *= 100.00000;
    }

    const v = Math.round( Math.max(Math.min(newValue, 999999), -99999) ).toLocaleString();
    this.changeTextColor(ColorManager.paramchangeTextColor(diffValue));
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawNewParamX = function(x, y, xparamId) {
    const paramWidth = this.paramWidth();
    const newValue = this._tempActor.xparam(xparamId);
    const diffValue = newValue - this._actor.xparam(xparamId);
    const v = Math.round( Math.max(Math.min(newValue * 100, 999999), -99999) ).toLocaleString();
    this.changeTextColor(ColorManager.paramchangeTextColor(diffValue));
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.drawNewParamS = function(x, y, sparamId) {
    const paramWidth = this.paramWidth();
    const newValue = this._tempActor.sparam(sparamId);
    const diffValue = newValue - this._actor.sparam(sparamId);
    const v = Math.round( Math.max(Math.min(newValue * 100, 999999), -99999) ).toLocaleString();

    if ( (sparamId == 0) || (sparamId == 4) || (sparamId == 6) || (sparamId == 7) ) {
        this.changeTextColor(ColorManager.paramchangeTextColor(-diffValue));
    } else {
        this.changeTextColor(ColorManager.paramchangeTextColor(diffValue));
    }

    this.DrawTextScaled(v + "%", x, y, paramWidth, "right");
};
Window_EquipStatus.prototype.rightArrowWidth = function() {
    return 24;
};
Window_EquipStatus.prototype.paramWidth = function() {
    return 60;
};
Window_EquipStatus.prototype.paramX = function() {
    return 185;
};
Window_EquipStatus.prototype.paramY = function(index) {
    return Math.floor( this.lineHeightB() * (index + 1) );
};

