Window_StatusBase.prototype.Draw_ParamName = function(x, y, paramId) {
    const width = this.ParamNameWidth();

    this.changeTextColor(dragon_color_gold);
    if ( paramId <= 7 ) this.DrawTextScaled(TextManager.param(paramId), x, y, width);
    else if ( paramId == DRAGON_PARAM_MAGIC_FOCUS ) this.DrawTextScaled("Magic Focus", x, y, width);
    this.resetTextColor();
};
Window_StatusBase.prototype.Draw_ParamNameCustom = function(x, y, cparamId) {
    const width = this.ParamNameWidth();
    this.changeTextColor(dragon_color_gold);

    if (cparamId == 0) this.DrawTextScaled("Max Tactical Points", x, y, width);
    else if (cparamId == 1) this.DrawTextScaled("Physical Hit Bonus", x, y, width);
    else if (cparamId == 2) this.DrawTextScaled("Magical Hit Bonus", x, y, width);

    this.resetTextColor();
};
Window_StatusBase.prototype.Draw_ParamNameX = function(x, y, xparamId) {
    const width = this.ParamNameWidth();
    this.changeTextColor(dragon_color_gold);
    if (xparamId == 0) {this.DrawTextScaled("Hit Rate", x, y, width);}
    else if (xparamId == 1) {this.DrawTextScaled("Physical Evade", x, y, width);}
    else if (xparamId == 2) {this.DrawTextScaled("Crit. Hit Rate", x, y, width);}
    else if (xparamId == 3) {this.DrawTextScaled("Critical Evade", x, y, width);}
    else if (xparamId == 4) {this.DrawTextScaled("Magical Evade", x, y, width);}
    else if (xparamId == 5) {this.DrawTextScaled("Magic Reflect", x, y, width);}
    else if (xparamId == 6) {this.DrawTextScaled("Counter Attack", x, y, width);}
    else if (xparamId == 7) {this.DrawTextScaled("HP Regen.", x, y, width);}
    else if (xparamId == 8) {this.DrawTextScaled("MP Regen.", x, y, width);}
    else if (xparamId == 9) {this.DrawTextScaled("TP Regen.", x, y, width);}
    else if ( xparamId == 12 ) this.DrawTextScaled("Phys. Crit. Hit Rate", x, y, width);
    else if ( xparamId == 13 ) this.DrawTextScaled("Mag. Crit. Hit Rate", x, y, width);
    else if ( xparamId == 14 ) this.DrawTextScaled("Phys. Critical Evade", x, y, width);
    else if ( xparamId == 15 ) this.DrawTextScaled("Mag. Critical Evade", x, y, width);

    this.resetTextColor();
};
Window_StatusBase.prototype.Draw_ParamNameS = function(x, y, sparamId) {
    const width = this.ParamNameWidth();
    this.changeTextColor(dragon_color_gold);
    if (sparamId == 0) {this.DrawTextScaled("Targeted Rate", x, y, width);}
    else if (sparamId == 1) {this.DrawTextScaled("Guard Effect", x, y, width);}
    else if (sparamId == 2) {this.DrawTextScaled("Heal Rate, Spells", x, y, width);}
    else if (sparamId == 3) {this.DrawTextScaled("Heal Rate, Potions", x, y, width);}
    else if (sparamId == 4) {this.DrawTextScaled("MP Cost Rate", x, y, width);}
    else if (sparamId == 5) {this.DrawTextScaled("TP Gain Rate", x, y, width);}
    else if (sparamId == 6) {this.DrawTextScaled("Physical Damage", x, y, width);}
    else if (sparamId == 7) {this.DrawTextScaled("Magical Damage", x, y, width);}
    else if (sparamId == 8) {this.DrawTextScaled("Floor Damage", x, y, width);}
    else if (sparamId == 9) {this.DrawTextScaled("EXP Gain Rate", x, y, width);}

    this.resetTextColor();
};
Window_StatusBase.prototype.Draw_CurrentParam = function(x, y, paramId) {
    const paramWidth = this.ParamWidth();
    var v = 0;
    if ( paramId <= 7 ) v = Math.round(Math.max(Math.min(this._actor.param(paramId), 99999), -9999)).toLocaleString();
    else if ( paramId == DRAGON_PARAM_MAGIC_FOCUS ) v = Math.round(Math.max(Math.min(this._actor.magic_focus, 99999), -9999)).toLocaleString();

    this.resetTextColor();
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_StatusBase.prototype.Draw_CurrentParamCustom = function(x, y, cparamId) {
    const paramWidth = this.ParamWidth();

    var param_value = 0;
    if ( cparamId == 0 ) param_value = this._actor.maxTp();
    if ( cparamId == 1 ) param_value = this._actor.hit_rate_physical * 100.00000;
    if ( cparamId == 2 ) param_value = this._actor.hit_rate_magical * 100.00000;

    const v = Math.round(Math.max(Math.min(param_value, 99999), -9999)).toLocaleString();
    this.resetTextColor();
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_StatusBase.prototype.Draw_CurrentParamX = function(x, y, xparamId) {
    const paramWidth = this.ParamWidth();
    const value = this._actor.xparam(xparamId);
    const v = Math.round(Math.max(Math.min(value * 100, 99999), -9999)).toLocaleString();
    this.resetTextColor();
    this.DrawTextScaled(v, x, y, paramWidth, "right");
};
Window_StatusBase.prototype.Draw_CurrentParamS = function(x, y, sparamId) {
    const paramWidth = this.ParamWidth();
    const value = this._actor.sparam(sparamId);
    const v = Math.round(Math.max(Math.min(value * 100, 99999), -9999)).toLocaleString();
    const end_char = sparamId == 0 ? " " : "%";
    this.resetTextColor();
    this.DrawTextScaled(v + end_char, x, y, paramWidth, "right");
};
Window_StatusBase.prototype.ParamWidth = function() {
    return this.CharWidthScaled() * 6;
};
Window_StatusBase.prototype.ParamNameWidth = function() {
    return this.CharWidthScaled() * 20;
};
Window_StatusBase.prototype.Draw_MaxNumberActionsPerTurn = function(actor, x, y) {
    const width = this.CharWidthScaled() * 14;

    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled( "Maximum number", x, y, width );
    this.DrawTextScaled( "of actions per", x, y + this.lineHeightB(), width );
    this.DrawTextScaled( "combat turn:", x, y + (this.lineHeightB() * 2), width );
    this.resetTextColor();

    if (!actor) return;
    this.DrawTextScaled( (actor.actionPlusSet().length + 1) + " actions", x, y + (this.lineHeightB() * 3), width, "left" );
};
Window_StatusBase.prototype.Draw_ChancesActionsPerTurn = function(actor, x, y, single_column=false) {
    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled( "Chances of actions", x, y, this.CharWidthScaled(18) );
    this.DrawTextScaled( "per turn:", x, y + this.lineHeightB(), this.CharWidthScaled(18) );
    this.resetTextColor();

    if (!actor) return;
    const values = actor.actionPlusSet().sort((a, b) => (b - a));
    const valuesSize = values.length;
    const x_width = this.CharWidthScaled() * 8;

    this.DrawTextScaled( "1: ", x, y + (this.lineHeightB() * 2), x_width, );
    this.DrawTextScaled( "100%", x, y + (this.lineHeightB() * 2), x_width, "right" );

    if (single_column == false) {
        var x_offset = 0;
        var y_offset = 0;
        for (let i = 0; i < valuesSize; i++) {
            const v = Math.round(values[i] * 100);
            const y2 = y + (this.lineHeightB() * (i+3)) + y_offset;
            const x2 = x + x_offset;

            this.DrawTextScaled( (i+2) + ":", x2, y2, x_width, );
            this.DrawTextScaled( v + "%", x2, y2, x_width, "right" );

            if ( i == 15 ) {
                x_offset = x_width + (this.CharWidthScaled() * 5);
                y_offset = -17 * this.lineHeightB();
            }
            if ( i == 32 ) {
                x_offset = x_width + x_width + (this.CharWidthScaled() * 10);
                y_offset = -34 * this.lineHeightB();
            }
            else if ( i == 43 ) break;
        }
    } else {
        for (let i = 0; i < Math.min(valuesSize, 27); i++) {
            const v = Math.round(values[i] * 100);
            const y2 = y + (this.lineHeightB() * (i+3));

            this.DrawTextScaled( (i+2) + ":", x, y2, x_width, );
            this.DrawTextScaled( v + "%", x, y2, x_width, "right" );
        }
    }
};
Window_StatusBase.prototype.Draw_DebuffResistances = function(actor, x, y) {
    const width = this.CharWidthScaled() * 26;
    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled( "Resistances to Debuffs:", x, y, width );

    for ( let i = 0; i <= 6; i++ )
        this.DrawTextScaled( DGN.GetParameterNameFromNumber(i), x, y + (this.lineHeightB() * (i + 1)), width );
    this.DrawTextScaled( DGN.GetParameterNameFromNumber(8), x, y + (this.lineHeightB() * 8), width );
    this.DrawTextScaled( DGN.GetParameterNameFromNumber(7), x, y + (this.lineHeightB() * 9), width );

    if ( !actor ) return;

    this.resetTextColor();
    for ( let i = 0; i <= 6; i++ ) {
        const v = (Math.round((1.00000 - actor.debuffRate(i)) * 10000.00000) / 100).toLocaleString() + "%";
        this.DrawTextScaled( v, x, y + (this.lineHeightB() * (i + 1)), width, "right" );
    }
    const v8 = (Math.round((1.00000 - actor.debuffRate(8)) * 10000.00000) / 100).toLocaleString() + "%";
    this.DrawTextScaled( v8, x, y + (this.lineHeightB() * 8), width, "right" );
    const v7 = (Math.round((1.00000 - actor.debuffRate(7)) * 10000.00000) / 100).toLocaleString() + "%";
    this.DrawTextScaled( v7, x, y + (this.lineHeightB() * 9), width, "right" );
};
Window_StatusBase.prototype.Draw_DebuffResistances_2Cols = function(actor, x, y) {
    const width = this.CharWidthScaled() * 27;
    const width_between_cols = this.CharWidthScaled() * 5;

    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled( "Resistances to Debuffs:", x, y, width );

    for ( let i = 0; i <= 4; i++ )
        this.DrawTextScaled( DGN.GetParameterNameFromNumber(i), x, y + (this.lineHeightB() * (i + 1)), width );
    for ( let i = 5; i <= 6; i++ )
        this.DrawTextScaled( DGN.GetParameterNameFromNumber(i), x + width + width_between_cols, y + (this.lineHeightB() * (i - 4)), width );
    this.DrawTextScaled( DGN.GetParameterNameFromNumber(8), x + width + width_between_cols, y + (this.lineHeightB() * 3), width );
    this.DrawTextScaled( DGN.GetParameterNameFromNumber(7), x + width + width_between_cols, y + (this.lineHeightB() * 4), width );

    if ( !actor ) return;

    this.resetTextColor();
    for ( let i = 0; i <= 4; i++ ) {
        const v = (Math.round((1.00000 - actor.debuffRate(i)) * 10000.00000) / 100).toLocaleString() + "%";
        this.DrawTextScaled( v, x, y + (this.lineHeightB() * (i + 1)), width, "right" );
    }
    for ( let i = 5; i <= 6; i++ ) {
        const v = (Math.round((1.00000 - actor.debuffRate(i)) * 10000.00000) / 100).toLocaleString() + "%";
        this.DrawTextScaled( v, x + width + width_between_cols, y + (this.lineHeightB() * (i - 4)), width, "right" );
    }
    const v8 = (Math.round((1.00000 - actor.debuffRate(8)) * 10000.00000) / 100).toLocaleString() + "%";
    this.DrawTextScaled( v8, x + width + width_between_cols, y + (this.lineHeightB() * 3), width, "right" );
    const v7 = (Math.round((1.00000 - actor.debuffRate(7)) * 10000.00000) / 100).toLocaleString() + "%";
    this.DrawTextScaled( v7, x + width + width_between_cols, y + (this.lineHeightB() * 4), width, "right" );
};
Window_StatusBase.prototype.actorSlotName = function(actor, index) {
    return actor.GetInventorySlotName(index);
};
/// Scaled Text End

///-----------------------------------------------------------------------------
/// Window_Status
///
/// The window for displaying full status on the status screen.
Window_Status.prototype.drawBasicInfo = function(x, y) {
    const lineHeight = this.lineHeight() * 0.8;
    this.drawActorLevel(this._actor, x, y + lineHeight * 0);
    this.drawActorIcons(this._actor, x, y + lineHeight * 1);
    this.placeBasicGauges(this._actor, x, y + lineHeight * 2);
};
Window_Status.prototype.expTotalValue = function() {
    if (this._actor.isMaxLevel()) {
        return this._actor.expForLevel(this._actor.maxLevel()).toLocaleString() + " (Max)";
    } else {
        return Math.round( this._actor.currentExp() ).toLocaleString();
    }
};
Window_Status.prototype.expNextValue = function() {
    if (this._actor.isMaxLevel()) {
        return "(None)";
    } else {
        return Math.round( this._actor.nextRequiredExp() ).toLocaleString();
    }
};
Window_Status.prototype.expOneHigherValue = function() {
    if (this._actor.isMaxLevel()) {
        return "- Max Level Attained -";
    } else {
        const lvl_higher = this._actor.level + 1;
        if (lvl_higher >= dragon_max_character_level)
            return " " + Math.round( this._actor.expForLevel(lvl_higher) ).toLocaleString() + " (Max)";
        return " " + Math.round( this._actor.expForLevel(lvl_higher) ).toLocaleString();
    }
};
Window_Status.prototype.expNextValuePercent = function() {
    if (this._actor.isMaxLevel()) {
        return "0% Remaining (Max Level Attained)";
    } else {
        const percent_remaining = Math.round(10000.0 * this._actor.nextRequiredExpUnrounded() / ( this._actor.expForLevelUnrounded(this._actor.level + 1) - this._actor.expForLevelUnrounded(this._actor.level) )).clamp(0, 10000) / 100;
        return String( percent_remaining ) + "% Remaining";
    }
};
Window_Status.prototype.drawExpInfo = function(x, y) {
    const lineHeight = this.lineHeightB();
    const expTotal = "Current EXP:";
    const expNext = "Until Next Level:";
    const expOneHigher = "Next Level:";
    const value_exp_total = this.expTotalValue();
    const value_exp_next = this.expNextValue();
    const value_exp_higher = this.expOneHigherValue();
    const exp_display_width = this.CharWidth() * 36;
    const value_exp_next_percent = this.expNextValuePercent();
    const exp_percent_width = exp_display_width + this.CharWidth() * 34; // 15

    this.changeTextColor(dragon_color_gold);
    this.drawText( expTotal, x, y, exp_display_width );
    this.drawText( expOneHigher, x + exp_display_width + (this.CharWidth() * 3), y, exp_display_width );
    this.drawText( expNext, x, y + lineHeight, exp_display_width );

    this.resetTextColor();
    this.drawText( value_exp_total, x, y, exp_display_width, "right" );
    this.drawText( value_exp_higher, x + exp_display_width + (this.CharWidth() * 15), y, exp_display_width, "left" );
    this.drawText( value_exp_next, x, y + lineHeight, exp_display_width, "right" );
    this.drawText( value_exp_next_percent, x + exp_display_width + (this.CharWidth() * 3), y + lineHeight, exp_percent_width, "left" );
};
Window_Status.prototype.drawBlock1 = function() {
    const y = this.block1Y();
    this.drawActorName(this._actor, 2, y - 5, 160);
    this.drawActorClass(this._actor, 200, y - 5, 300);
    this.drawActorNickname(this._actor, this.CharWidth() * 60, y - 5, 300);
};
Window_Status.prototype.drawBlock2 = function() {
    const y = this.block2Y() - 26;
    this.drawActorFace(this._actor, 2, y);
    this.drawBasicInfo(198, y);
    this.drawExpInfo(this.CharWidth() * 60, y);
};
Window_Status.prototype.refresh = function() {
    Window_StatusBase.prototype.refresh.call(this);
    if (this._actor) {
        this.drawBlock1();
        this.drawBlock2();

        this.DrawListOfElementRates( this._actor, 0, this.lineHeightB() * 8 ); // y = 164

        this.changeTextColor(dragon_color_gold);
        this.DrawTextScaled( "Current Effects:", 220, this.lineHeightB() * 8, this.CharWidth() * 34 ); // y = 164, width = 310
        this.resetTextColor();
        this.DrawListOfStatesText( this._actor, 220, this.lineHeightB() * 9, 13 ); // y = 186

        this.Draw_Params( this.CharWidth() * 60, this.lineHeightB() * 4 ); // x = 500
        this.Draw_ParamsX( this.CharWidth() * 89, this.lineHeightB() * 4 ); // x = 760
        this.Draw_ParamsS( this.CharWidth() * 118, this.lineHeightB() * 4 ); // x = 1010

        this.Draw_MaxNumberActionsPerTurn( this._actor, 0, this.lineHeightB() * 23 ); // 600, 428
        this.Draw_ChancesActionsPerTurn( this._actor, this.CharWidth() * 17, this.lineHeightB() * 23 ); // this.CharWidth() * 17, this.lineHeightB() * 20

        this.DrawListOfStatesImmuneTo( this._actor, this.CharWidth() * 60, this.lineHeightB() * 15, 23 ); // x=390
        this.DrawListOfStatesResistantTo( this._actor, this.CharWidth() * 95, this.lineHeightB() * 15, 23 );

        this.Draw_DebuffResistances_2Cols( this._actor, (this.CharWidth() * 145.5) - 2, this.lineHeightB() * 33.2 ); // this._actor, this.CharWidth() * 145, this.lineHeightB() * 28
    }
};

