///-----------------------------------------------------------------------------
/// Window_EquipSlot
///
/// The window for selecting an equipment slot on the equipment screen.
Window_EquipSlot.prototype.lineHeight = function() {
    return 20;
};
Window_EquipSlot.prototype.itemHeight = function() {
    return 43;
};
Window_EquipSlot.prototype.slotNameWidth = function() {
    return this.CharWidthScaled() * 15; // return 14;
};
/*
Window_EquipSlot.prototype.itemHeight = function() {
    return this.lineHeight() + 6;
};
*/
Window_EquipSlot.prototype.maxItems = function() {
    return this._actor ? this._actor.GetInventorySlotCount() : 0;
};
Window_EquipSlot.prototype.itemAt = function(index) {
    return this._actor ? this._actor.GetInventorySlotItem(index) : null;
};
Window_EquipSlot.prototype.drawItem = function(index) {
    if (this._actor) {
        const slotName = this.actorSlotName(this._actor, index);
        const item = this.itemAt(index);
        const slotNameWidth = this.slotNameWidth();
        const item_disabled = this._actor ? this._actor.GetInventorySlotDisabled(index) : false;
        const rect = this.itemRect(index);
        // const itemWidth = (rect.width - slotNameWidth) - 36;
        this.changePaintOpacity(true);
        this.changeTextColor(item_disabled ? dragon_color_red : dragon_color_gold);
        this.DrawTextScaled(slotName, rect.x + 6, rect.y + 10, slotNameWidth);
        if (!item) return;
        this.DrawItemScaled_NameLevelUses(item, rect.x + slotNameWidth + 8, rect.y + 5, rect.width - 2);
    }
};
Window_EquipSlot.prototype.processCursorMove = function() {
    if (this.isCursorMovable()) {
        const lastIndex = this.index();
        if (Input.isRepeated("down")) {
            this.cursorDown(Input.isTriggered("down"));
        }
        if (Input.isRepeated("up")) {
            this.cursorUp(Input.isTriggered("up"));
        }
        /*
        if (Input.isRepeated("right")) {
            this.cursorRight(Input.isTriggered("right"));
        }
        if (Input.isRepeated("left")) {
            this.cursorLeft(Input.isTriggered("left"));
        }
        if (!this.isHandled("pagedown") && Input.isTriggered("pagedown")) {
            this.cursorPagedown();
        }
        if (!this.isHandled("pageup") && Input.isTriggered("pageup")) {
            this.cursorPageup();
        }
        */
        if (this.index() !== lastIndex) {
            this.playCursorSound();
        }
    }
};
Window_EquipSlot.prototype.processHandling = function() {
    if (this.isOpenAndActive()) {
        if (this.isOkEnabled() && this.isOkTriggered()) {
            return this.processOk();
        }
        if (this.isCancelEnabled() && this.isCancelTriggered()) {
            return this.processCancel();
        }
        if (this.isHandled("right") && Input.isTriggered("right")) {
            return this.processRight();
        }
        if (this.isHandled("left") && Input.isTriggered("left")) {
            return this.processLeft();
        }
        if (this.isHandled("pagedown") && Input.isTriggered("pagedown")) {
            return this.processPagedown();
        }
        if (this.isHandled("pageup") && Input.isTriggered("pageup")) {
            return this.processPageup();
        }
    }
};
Window_EquipSlot.prototype.processLeft = function() {
    this.updateInputData();
    // this.deactivate();
    this.callHandler("left");
};
Window_EquipSlot.prototype.processRight = function() {
    this.updateInputData();
    // this.deactivate();
    this.callHandler("right");
};
Window_EquipSlot.prototype.processPageup = function() {
    this.updateInputData();
    // this.deactivate();
    this.callHandler("pageup");
};
