Scene_Equip.prototype.createHelpWindow = function() {
    const rect = this.helpWindowRect();
    this._helpWindow = new Window_Help(rect);
    this._helpWindow.deactivate();
    this._helpWindow.hide();
};
Scene_Equip.prototype.createSlotWindow = function() {
    const rect = this.slotWindowRect();
    this._slotWindow = new Window_EquipSlot(rect);
    this._slotWindow.setHelpWindow(this._helpWindow);
    this._slotWindow.setStatusWindow(this._statusWindow);
    this._slotWindow.setHandler("ok", this.onSlotOk.bind(this));
    this._slotWindow.setHandler("cancel", this.onSlotCancel.bind(this));
    this._slotWindow.setHandler("pagedown", this.nextActor.bind(this));
    this._slotWindow.setHandler("pageup", this.previousActor.bind(this));
    this._slotWindow.setHandler("right", this.nextActor.bind(this));
    this._slotWindow.setHandler("left", this.previousActor.bind(this));
    this.addWindow(this._slotWindow);
};
Scene_Equip.prototype.onSlotOk = function() {
    /*
    const idx = this._slotWindow.index().clamp(0, this._itemWindow._actor._inventory_slots.length - 1);
    const equip_is_item = this._itemWindow._actor._inventory_slots[this._slotWindow.index()].name === "Item";
    this._itemWindow._category = equip_is_item ? "item" : "equipment";
    */

    this._slotWindow.hide();
    this._itemWindow.show();
    this._itemWindow.refresh();
    this._itemWindow.activate();
    this._itemWindow.select(0);
};
Scene_Equip.prototype.onItemOk = function() {
    const success = this.executeEquipChange();
    if (success === true) SoundManager.playEquip();
    this.hideItemWindow();
    this._slotWindow.refresh();
    this._itemWindow.refresh();
    this._statusWindow.refresh();
};
Scene_Equip.prototype.executeEquipChange = function() {
    const actor = this.actor();
    const slot_index = this._slotWindow.index();
    const item = this._itemWindow.item();
    const item_in_slot = actor.InventorySlotItem(slot_index) ? actor.InventorySlotItem(slot_index).Deep() : null;

    if (!actor.CanEquipInventorySlot(item, slot_index)) {
        SoundManager.playBuzzer();
        return false;
    }

    if (item) {
        if (item_in_slot)
            actor.ClearInventorySlot(slot_index);
        actor.AddInventorySlotItem(item, slot_index);
        $gameParty.InventoryRemoveItem(item.inv_index);
        if (item_in_slot)
            $gameParty.InventoryAddItem(item_in_slot);
        actor.refresh();
    } else {
        if (!item_in_slot) return false;
        if (!$gameParty.InventoryHasSpace()) {
            SoundManager.playBuzzer();
            return false;
        }
        actor.ClearInventorySlot(slot_index);
        $gameParty.InventoryAddItem(item_in_slot);
        actor.refresh();
    }
    return true;
};
Scene_Equip.prototype.commandClear = function() {
    SoundManager.playEquip();
    this.actor().ClearInventory();
    this._statusWindow.refresh();
    this._slotWindow.refresh();
    this._commandWindow.activate();
};

