Window_StatusEquip.prototype.itemHeight = function() {
    return this.lineHeight() - 3;
};
Window_StatusEquip.prototype.drawItem = function(index) {
    if (!this._actor) return;
    const rect = this.itemLineRect(0);
    const x = rect.x - 2;
    const y = rect.y + (index * this.itemHeight()) - 2;
    const equips = this._actor.equips();
    const item = equips[index];
    const slotName = this.actorSlotName(this._actor, index);
    const slotNameWidth = this.CharWidthScaled() * 14;
    const itemWidth = 4 + (rect.width - slotNameWidth) - 36;

    this.changePaintOpacity(true);
    this.changeTextColor(dragon_color_gold);
    this.DrawTextScaled(slotName, x, y, slotNameWidth);
    this.changeTextColor(dragon_color_white);

    if (!item) return;
    this.drawIcon(item.iconIndex, x + slotNameWidth, y + 2);
    this.changeTextColor(dragon_color_white);
    this.DrawTextScaled(item.name, x + slotNameWidth + 36, y, itemWidth);
    this.changeTextColor(dragon_color_white);

    /*
    this.changeTextColor(ColorManager.systemColor());
    this.drawText(slotName, rect.x, rect.y, sw, rect.height);
    this.drawItemName(item, rect.x + sw, rect.y, rect.width - sw);
    */
};

