/// Window_SavefileList
///
/// The window for selecting a save file on the save and load screens.
Window_SavefileList.prototype.numVisibleRows = function() {
    return 3;
};
Window_SavefileList.prototype.drawItem = function(index) {
    const savefileId = this.indexToSavefileId(index);
    const info = DataManager.savefileInfo(savefileId);
    const rect = this.itemRectWithPadding(index);
    this.resetTextColor();
    this.changePaintOpacity(this.isEnabled(savefileId));
    this.drawTitle(savefileId, rect.x, rect.y);
    if (info) {
        this.drawContents(info, rect);
    }
};
Window_SavefileList.prototype.drawTitle = function(savefileId, x, y) {
    if (savefileId === 0) {
        this.drawText(TextManager.autosave, x, y, this.CharWidth() * 13, "left");
    } else {
        this.drawText(TextManager.file + " " + savefileId, x, y, this.CharWidth() * 13, "left");
    }
};
Window_SavefileList.prototype.drawContents = function(info, rect) {
    const bottom = rect.y + rect.height;
    const right = rect.width;
    const lineHeight = this.lineHeightB();
    const text_scale = 1.0 / 1.15;
    const left_block_width = this.CharWidth() * 13 * text_scale; // Left-Edge Stuff.
    const center_block_a_width = this.CharWidth() * 17 * text_scale; // Actor Name.
    const center_block_b_width = this.CharWidth() * 13 * text_scale; // Actor Class.
    const center_block_c_width = this.CharWidth() * 5 * text_scale; // Actor Level.
    const center_block_d_width = this.CharWidth() * 18 * text_scale; // Actor Health Points. // 8
    const center_block_e_width = this.CharWidth() * 2 * text_scale; // Actor Maximum Health Points. // 10
    const center_block_a_x = rect.x + left_block_width + (this.CharWidth() * 2 * text_scale);
    const center_block_b_x = center_block_a_x + center_block_a_width + (this.CharWidth() * text_scale);
    const center_block_c_x = center_block_b_x + center_block_b_width + (this.CharWidth() * 2 * text_scale);
    const center_block_d_x = center_block_c_x + center_block_c_width + (this.CharWidth() * 2 * text_scale);
    const center_block_e_x = center_block_d_x + center_block_d_width + (this.CharWidth() * 1 * text_scale);
    const right_block_x = center_block_e_x + center_block_e_width + (this.CharWidth() * 2 * text_scale);
    // const right_block_width = right_block_x + (this.CharWidth() * 23); // Party Location.
    const right_block_width = (this.CharWidth() * 23 * text_scale); // Party Location.
    const face_width = 144;
    const face_height = 144;
    const face_block_width = face_width * 7;
    const face_block_x = 4 + right - face_block_width;

    this.resetTextColor();

    if ( info.playtime ) {
        this.resetTextColor();
        this.DrawTextScaled( "Time Elapsed:", rect.x, rect.y + (lineHeight * 1), left_block_width);
        this.changeTextColor( dragon_color_lvl );
        this.DrawTextScaled( info.playtime, rect.x, rect.y + (lineHeight * 2), left_block_width, "right" );
    }

    if (info.cash) {
        this.resetTextColor();
        this.DrawTextScaled( "Cash:", rect.x, rect.y + (lineHeight*3), left_block_width, "left" );

        this.changeTextColor( dragon_color_gold );
        this.DrawTextScaled( (info.cash.GP).toLocaleString(), rect.x, rect.y + (lineHeight*4), left_block_width, "right" );
        this.DrawTextScaled( "Gold", rect.x, rect.y + (lineHeight*5), left_block_width, "right" );
        this.changeTextColor( dragon_color_silver );
        this.DrawTextScaled( (info.cash.SP).toLocaleString(), rect.x, rect.y + (lineHeight*6), left_block_width, "right" );
        this.DrawTextScaled( "Silver", rect.x, rect.y + (lineHeight*7), left_block_width, "right" );
        this.changeTextColor( dragon_color_copper );
        this.DrawTextScaled( (info.cash.CP).toLocaleString(), rect.x, rect.y + (lineHeight*8), left_block_width, "right" );
        this.DrawTextScaled( "Copper", rect.x, rect.y + (lineHeight*9), left_block_width, "right" );

        if ( info.actors ) {
            this.resetTextColor();
            this.DrawTextScaled( "Party Size:", rect.x, rect.y + (lineHeight*11), left_block_width, "left" );
            this.changeTextColor( dragon_color_lvl );
            this.DrawTextScaled( String(info.actors.length) + " members", rect.x, rect.y + (lineHeight*12), left_block_width, "right" );
        }
    }
    else if ( info.money != undefined ) {
        this.resetTextColor();
        this.DrawTextScaled( "Cash:", rect.x, rect.y + (lineHeight*3), left_block_width, "left" );
        this.changeTextColor( dragon_color_lvl );
        this.DrawTextScaled( (info.money).toLocaleString(), rect.x, rect.y + (lineHeight*4), left_block_width, "right" );
        this.DrawTextScaled( "  Gold Pieces", rect.x, rect.y + (lineHeight*5), left_block_width, "left" );

        if ( info.actors ) {
            this.resetTextColor();
            this.DrawTextScaled( "Party Size:", rect.x, rect.y + (lineHeight*6), left_block_width, "left" );
            this.changeTextColor( dragon_color_lvl );
            this.DrawTextScaled( String(info.actors.length) + " members", rect.x, rect.y + (lineHeight*7), left_block_width, "right" );
        }
    }
    if ( info.actors ) {
        for (let i = 0; i < info.actors.length; i++) {
            this.resetTextColor();
            if ( (info.actors[i]._name) && (info.actors[i].hp) && (info.actors[i].mhp) ) {
                this.changeTextColor( DGN.CustomHpColor( info.actors[i].hp, info.actors[i].mhp ) );
                this.DrawTextScaled( info.actors[i]._name + ",", center_block_a_x, rect.y + (lineHeight*i), center_block_a_width );
            }
            this.resetTextColor();
            if ( info.actors[i].class_name ) this.DrawTextScaled( info.actors[i].class_name, center_block_b_x, rect.y + (lineHeight*i), center_block_b_width );
            this.changeTextColor( dragon_color_lvl );
            if ( info.actors[i].level ) this.DrawTextScaled( "Lv " + String(info.actors[i].level), center_block_c_x, rect.y + (lineHeight*i), center_block_c_width, "left" );
            if ( (info.actors[i].hp) && (info.actors[i].mhp) ) {
                this.changeTextColor( DGN.CustomHpColor( info.actors[i].hp, info.actors[i].mhp ) );
                this.DrawTextScaled( (info.actors[i].hp).toLocaleString() + " / " + (info.actors[i].mhp).toLocaleString(), center_block_d_x, rect.y + (lineHeight*i), center_block_d_width, "right" );
            }
            this.resetTextColor();
            this.DrawTextScaled( "HP", center_block_e_x, rect.y + (lineHeight*i), center_block_e_width, "right" );

            if (i >= 14) break;
        }
    }
    if ( info.loc != undefined ) {
        this.resetTextColor();
        this.DrawTextScaled( "Location:", right_block_x, rect.y, right_block_width );
        const text_location = DGN.ReparseTextAuto(info.loc, 21);
        var text_loc1 = "  " + text_location;
        var text_loc2 = "";

        if ( text_location.includes("\n") ) {
            const text_line_break = text_location.indexOf("\n");
            text_loc1 = "  " + text_location.slice( 0, text_line_break );
            text_loc2 = "  " + text_location.slice( text_line_break + 1, text_location.length );
        }

        this.changeTextColor( dragon_color_tp );
        this.DrawTextScaled( text_loc1, right_block_x, rect.y + (lineHeight * 1), right_block_width );
        this.DrawTextScaled( text_loc2, right_block_x, rect.y + (lineHeight * 2), right_block_width );
    }
    if ( info.chapter != undefined ) {
        this.resetTextColor();
        this.DrawTextScaled( "World:", right_block_x, rect.y + (lineHeight*3), right_block_width );
        this.changeTextColor( dragon_color_tp );
        this.DrawTextScaled( "  " + DGN.GetChapterTextForVariable(info.chapter), right_block_x, rect.y + (lineHeight*4), right_block_width );
    }
    if ( info.chapter_max != undefined ) {
        this.resetTextColor();
        this.DrawTextScaled( "Farthest World Reached:", right_block_x, rect.y + (lineHeight*5), right_block_width );
        this.changeTextColor( dragon_color_tp );
        this.DrawTextScaled( "  " + DGN.GetChapterTextForVariable(info.chapter_max), right_block_x, rect.y + (lineHeight*6), right_block_width );
    }
    if ( info.start_date ) {
        this.resetTextColor();
        this.DrawTextScaled( "Game Started:", right_block_x, rect.y + (lineHeight*7), right_block_width );
        this.changeTextColor( dragon_color_lvl );
        this.DrawTextScaled( "  " + info.start_date.date, right_block_x, rect.y + (lineHeight*8), right_block_width );
        this.DrawTextScaled( "  " + info.start_date.time, right_block_x, rect.y + (lineHeight*9), right_block_width );
    }
    if ( info.save_date ) {
        this.resetTextColor();
        this.DrawTextScaled( "Game Saved:", right_block_x, rect.y + (lineHeight*10), right_block_width );
        this.changeTextColor( dragon_color_lvl );
        this.DrawTextScaled( "  " + info.save_date.date, right_block_x, rect.y + (lineHeight*11), right_block_width );
        this.DrawTextScaled( "  " + info.save_date.time, right_block_x, rect.y + (lineHeight*12), right_block_width );
    }
    if ( info.actors ) {
        const num_faces = Math.min( info.actors.length, 14 );
        const num_top = Math.ceil( num_faces * 0.5 );
        const num_bottom = num_faces - num_top;
        const offset = 7 - num_top;

        for ( let i = 0; i < num_top; i++ )
            this.drawFace( info.actors[i]._faceName, info.actors[i]._faceIndex, face_block_x + (face_width * (i + offset)), rect.y + 8, face_width, face_height );
        for ( let i = num_top; i < (num_top + num_bottom); i++ )
            this.drawFace( info.actors[i]._faceName, info.actors[i]._faceIndex, face_block_x + (face_width * (offset + i - num_top)), rect.y + face_height + 16, face_width, face_height );
    }

    this.resetTextColor();
};

///-----------------------------------------------------------------------------
/// DataManager
///
/// The static class that manages the database and game objects.
DataManager.isSkill = function(item) {
    if (!item) return false;
    if (!item.stypeId) return false;
    if (!item.id.IsWithin(1, $dataSkills.length)) return false;

    return true;
};
DataManager.isItem = function(item) {
    if (!item) return false;
    if (!item.itypeId) return false;
    if (!item.id.IsWithin(1, $dataItems.length)) return false;

    return true;
};
DataManager.isWeapon = function(item) {
    if (!item) return false;
    if (!item.wtypeId) return false;
    if (!item.id.IsWithin(1, $dataWeapons.length)) return false;

    return true;
};
DataManager.isArmor = function(item) {
    if (!item) return false;
    if (!item.atypeId) return false;
    if (!item.id.IsWithin(1, $dataArmors.length)) return false;

    return true;
};
DataManager.maxSavefiles = function() {
    return 50;
};
DataManager.makeSavefileInfo = function() {
    DGN.UpdateGlobalData();

    const info = {};
    info.title = $dataSystem.gameTitle;
    info.characters = $gameParty.charactersForSavefile();
    info.faces = $gameParty.facesForSavefile();
    info.playtime = $gameSystem.playtimeText();
    info.timestamp = Date.now();

    info.actors = [];
    for (let i = 0; i < $gameParty.size(); i++) {
        const member = $gameParty.members()[i];
        var actor = {};

        actor._name = member.name();
        actor.level = member.level;
        actor.class_name = member.currentClass().name;
        actor.hp = member.hp;
        actor.mhp = member.mhp;
        actor._faceName = member._faceName;
        actor._faceIndex = member._faceIndex;

        info.actors.push( actor );
    };
    info.chapter = DGN.DeepCopy( $gameVariables.value(dragon_variable_game_chapter) );
    info.chapter_max = DGN.DeepCopy( $gameVariables.value(dragon_variable_max_game_chapter) );
    info.money = DGN.DeepCopy( $gameParty.gold() );
    info.cash = $gameParty.Cash().Deep();
    info.loc = $gameMap.displayName();
    $gameSystem.CheckGameStartDateTime();
    info.start_date = DGN.DeepCopy( $gameSystem.time_started );
    info.save_date = DGN.GetCurrentDateTimeStringObject();

    return info;
};
DataManager.loadGame = function(savefileId) {
    const saveName = this.makeSavename(savefileId);
    return StorageManager.loadObject(saveName).then(contents => {
        this.createGameObjects();
        this.extractSaveContents(contents);
        this.correctDataErrors();

        $gameSystem.FixMissingData();
        $gameSystem.UpdateDiscoveredArrays();
        $gameMap.createVehicles();

        // $gameSystem.UpdateEncounterGroups();

        return 0;
    });
};
DataManager.PrepareDgnData_Special = function(item) {
    if ( !item ) return DRAGON_SPECIAL_NORMAL;
    if ( !item.special ) item.special = DRAGON_SPECIAL_NORMAL;
    if ( item.special != DRAGON_SPECIAL_NORMAL ) return item.special;
    const txt = DGN.DeepCopy(item.name).toLowerCase();
    const equip_type = item.equip_type;
    const weapon_type = item.weapon_type;
    const armor_type = item.armor_type;
    var special = DRAGON_SPECIAL_NORMAL;

    // Shared Items
    if ( item.itypeId ) {
        // Blank entries
        if ( item.name.length < 1 ) {
            special = DRAGON_SPECIAL_BLANK;

            return special;
        }
        // Debug items
        else if ( item.name.includes("TEST") ) {
            special = DRAGON_SPECIAL_DEBUG;

            return special;
        }
        // Common / Regular shared items
        else if ( item.itypeId == 1 ) {
            special = DRAGON_SPECIAL_MONSTER_DROP;

            if ( txt.includes("healing potion") ) special = DRAGON_SPECIAL_HEALING_HP;
            else if ( txt.includes("magic syrup") ) special = DRAGON_SPECIAL_HEALING_MP;
            else if ( txt.includes("tactical endurance potion") ) special = DRAGON_SPECIAL_HEALING_TP;
            else if ( txt.includes("hyperlife injection") ) special = DRAGON_SPECIAL_HEALING_DEATH;
            else if ( item.description.includes("Permanantly increases ") ) special = DRAGON_SPECIAL_ABILITY_GROW;
            else if ( item.description.includes("Buffs one's ") ) special = DRAGON_SPECIAL_ABILITY_BOOST;
            else if ( txt.includes("magic flower") ) special = DRAGON_SPECIAL_POWER_UP_GENERIC;
        }
        // Key Items
        else if ( item.itypeId == 2 ) {
            special = DRAGON_SPECIAL_KEY_ITEM;

            if ( txt.includes("healing potion") ) special = DRAGON_SPECIAL_HEALING_HP;
            else if ( txt.includes("magic syrup") ) special = DRAGON_SPECIAL_HEALING_MP;
            else if ( txt.includes("tactical endurance potion") ) special = DRAGON_SPECIAL_HEALING_TP;
            else if ( txt.includes("hyperlife injection") ) special = DRAGON_SPECIAL_HEALING_DEATH;
            else if ( item.description.includes("Permanantly increases ") ) special = DRAGON_SPECIAL_ABILITY_GROW;
            else if ( item.description.includes("Buffs one's ") ) special = DRAGON_SPECIAL_ABILITY_BOOST;
            else if ( txt.includes("magic flower") ) special = DRAGON_SPECIAL_POWER_UP_GENERIC;

            if ( txt.includes("orb") ) special = DRAGON_SPECIAL_ORB;
            if ( txt.includes("orb shards") ) special = DRAGON_SPECIAL_ORB_SHARDS;
        }
        // Hidden Key Items
        else if ( item.itypeId > 2 ) {
            special = DRAGON_SPECIAL_KEY_ITEM;
        }

        return special;
    }

    // Blank entries
    if ( item.name.length < 1 ) {
        special = DRAGON_SPECIAL_BLANK;

        return special;
    }
    // Debug items
    else if ( item.name.includes("TEST") ) {
        special = DRAGON_SPECIAL_DEBUG;

        return special;
    }
    // Comment Entries / Note "Items"
    else if ( txt.slice( 0, 2 ).includes("- ") ) {
        special = DRAGON_SPECIAL_NOTE;

        return special;
    }
    // Broken Items
    else if ( (weapon_type == 1) || (armor_type == 1) ) {
        special = DRAGON_SPECIAL_BROKEN;

        return special;
    }
    // Weapons and Backup Weapons
    else if ( (equip_type == 1) || (equip_type == 3) ) {
        if ( txt.includes("fire") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("flaming") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("incendiary") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("ice") ) special = DRAGON_SPECIAL_ICE;
        else if ( txt.includes("freezing") ) special = DRAGON_SPECIAL_ICE;
        else if ( txt.includes("lightning") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("thunder") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("electric") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("shocking") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("metal") ) special = DRAGON_SPECIAL_METAL;
        else if ( txt.includes("acid") ) special = DRAGON_SPECIAL_ACID;
        else if ( txt.includes("water") ) special = DRAGON_SPECIAL_WATER;
        else if ( txt.includes("earth") ) special = DRAGON_SPECIAL_EARTH;
        else if ( txt.includes("wind") ) special = DRAGON_SPECIAL_WIND;
        else if ( txt.includes("hasted") ) special = DRAGON_SPECIAL_HASTED;
        else if ( txt.includes("bleeding") ) special = DRAGON_SPECIAL_BLEEDING;
        else if ( txt.includes("blood") ) special = DRAGON_SPECIAL_BLEEDING;
        else if ( txt.includes("stunning") ) special = DRAGON_SPECIAL_STUNNING;
        else if ( txt.includes("stun") ) special = DRAGON_SPECIAL_STUNNING;
        else if ( txt.includes("antimagical") ) special = DRAGON_SPECIAL_ANTIMAGICAL;
        else if ( txt.includes("anti-magical") ) special = DRAGON_SPECIAL_ANTIMAGICAL;
        else if ( txt.includes("antimagic") ) special = DRAGON_SPECIAL_ANTIMAGICAL;
        else if ( txt.includes("anti-magic") ) special = DRAGON_SPECIAL_ANTIMAGICAL;
        else if ( txt.includes("draining") ) special = DRAGON_SPECIAL_ANTIMAGICAL;
        else if ( txt.includes("power") ) special = DRAGON_SPECIAL_POWER;
        else if ( txt.includes("mega") ) special = DRAGON_SPECIAL_POWER;
        else if ( txt.includes("rune") ) special = DRAGON_SPECIAL_WEAPON_RUNE;
        else if ( txt.includes("reflex") ) special = DRAGON_SPECIAL_WEAPON_REFLEX;

        if ( armor_type == 21 ) special = DRAGON_SPECIAL_MAGIC_WAND;
    }
    // Character Class Books
    else if ( equip_type == 4 ) {
        special = DRAGON_SPECIAL_CLASS_BOOK;
    }
    // Shields
    else if ( equip_type == 5 ) {
        if ( txt.includes("fire") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("flaming") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("incendiary") ) special = DRAGON_SPECIAL_FIRE;
        else if ( txt.includes("ice") ) special = DRAGON_SPECIAL_ICE;
        else if ( txt.includes("freezing") ) special = DRAGON_SPECIAL_ICE;
        else if ( txt.includes("lightning") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("thunder") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("electric") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("shocking") ) special = DRAGON_SPECIAL_LIGHTNING;
        else if ( txt.includes("metal") ) special = DRAGON_SPECIAL_METAL;
        else if ( txt.includes("acid") ) special = DRAGON_SPECIAL_ACID;
        else if ( txt.includes("water") ) special = DRAGON_SPECIAL_WATER;
        else if ( txt.includes("earth") ) special = DRAGON_SPECIAL_EARTH;
        else if ( txt.includes("wind") ) special = DRAGON_SPECIAL_WIND;
        else if ( txt.includes("darkness") ) special = DRAGON_SPECIAL_DARKNESS;
        else if ( txt.includes("immortality") ) special = DRAGON_SPECIAL_IMMORTALITY;
        else if ( txt.includes("rainbow") ) special = DRAGON_SPECIAL_RAINBOW;
        else if ( txt.includes("rune") ) special = DRAGON_SPECIAL_ARMOR_RUNE;
        else if ( txt.includes("reflex") ) special = DRAGON_SPECIAL_ARMOR_REFLEX;
    }
    // Armored Clothing
    else if ( (equip_type >= 6) && (equip_type <= 11) ) {
        special = DRAGON_SPECIAL_NORMAL;

        if ( txt.includes("rune") ) special = DRAGON_SPECIAL_ARMOR_RUNE;
    }
    // Magical Clothing and accessories
    else if ( (equip_type >= 12) && (equip_type <= 13) ) {
        special = DRAGON_SPECIAL_ENCHANTED;

        if ( txt.includes("rune") ) special = DRAGON_SPECIAL_ARMOR_RUNE;
    }
    // Rings
    else if ( equip_type == 14 ) {
        special = DRAGON_SPECIAL_GEAR_MAGICAL_RING_LEVELED;

        if ( item.has_levels == false ) {
            if ( txt.includes("minor") ) special = DRAGON_SPECIAL_GEAR_MAGICAL_RING_MINOR;
            else if ( txt.includes("major") ) special = DRAGON_SPECIAL_GEAR_MAGICAL_RING_MAJOR;
            else if ( txt.includes("ultra") ) special = DRAGON_SPECIAL_GEAR_MAGICAL_RING_ULTRA;
        }
    }
    // Accessories
    else if ( equip_type == 15 ) {
        special = DRAGON_SPECIAL_NORMAL;

        if ( txt.includes("rune") ) special = DRAGON_SPECIAL_RUNE;
    }

    return special;
};
DataManager.DgnDataFile_CompareNames = function(a, b) {
    const txt_a = DGN.RemoveLevelName( a.name, a.level );
    const txt_b = DGN.RemoveLevelName( b.name, b.level );

    return txt_a - txt_b;
};
DataManager.PrepareDgnDataFiles = function() {
    // Weapons
    for ( let i = 1; i < $dataWeapons.length; i++ ) {
        var item = $dataWeapons[i];
        if ( !item ) continue;

        item.special = this.PrepareDgnData_Special( item );
    }

    // Armors
    for ( let i = 1; i < $dataArmors.length; i++ ) {
        var item = $dataArmors[i];
        if ( !item ) continue;

        item.special = this.PrepareDgnData_Special( item );
    }

    // Items
    for ( let i = 1; i < $dataItems.length; i++ ) {
        var item = $dataItems[i];
        if ( !item ) continue;

        item.special = this.PrepareDgnData_Special( item );
    }
};
DataManager.CreateDgnDataFile_Actors = function() {
    var data_array = [];
    data_array.push( null );
    var data_actors = [];

    for ( let i = 1; i < $dataActors.length; i++ ) {
        const item = $dataActors[i];
        if ( !item ) continue;
        if ( item.name.length < 1 ) continue;
        if ( item.name[0] === "-" ) continue;
        if ( !item.custom_traits) continue;

        const data = DGN.DeepCopy( item );

        data_actors.push( data );
    }

    return DGN.DeepCopy( data_array.concat(data_actors) );
};
DataManager.CreateDgnDataFile_Enemies = function() {
    var data_array = [];
    data_array.push( null );
    var data_enemies = [];

    for ( let i = 1; i < $dataEnemies.length; i++ ) {
        const item = $dataEnemies[i];
        if ( !item ) continue;
        if ( item.name.length < 1 ) continue;
        if ( item.name[0] === "-" ) continue;
        if ( !item.custom_traits) continue;

        const data = DGN.DeepCopy( item );

        data_enemies.push( data );
    }
    data_enemies.sort( (a, b) => {
        const name_diff = a.name - b.name;
        const hp_diff = a.params[0] - b.params[0];

        return hp_diff || name_diff;
    });

    return DGN.DeepCopy( data_array.concat(data_enemies) );
};
DataManager.CreateDgnDataFile_Weapons = function() {
    var data_array = [];
    data_array.push( null );
    var data_init = [];
    var data_unleveled = [];
    var data_leveled = [];

    // Broken Item Listings
    for ( i = 1; i <= 20; i++ )
        data_init.push( DGN.DeepCopy($dataWeapons[i]) );

    // Unleveled Items
    for ( i = 21; i < $dataWeapons.length; i++ ) {
        var item = $dataWeapons[i].Deep();
        if ( !item ) continue;
        if ( item.name.length < 1 ) continue;
        if ( item.name[0] === "-" ) continue;
        if ( item.has_levels == true ) continue;
        if ( item.id <= 20 ) continue;
        if ( item.special == DRAGON_SPECIAL_BROKEN ) continue;

        item.description = "";
        item.note = "";
        if ( item.description2 ) delete item.description2;

        data_unleveled.push( item );
    }

    // Leveled Items
    for ( i = 21; i < $dataWeapons.length; i++ ) {
        var item = $dataWeapons[i].Deep();
        if ( !item ) continue;
        if ( item.name.length < 1 ) continue;
        if ( item.name[0] === "-" ) continue;
        if ( item.has_levels == false ) continue;
        if ( item.id <= 20 ) continue;
        if ( item.special == DRAGON_SPECIAL_BROKEN ) continue;

        item.description = "";
        item.note = "";
        if ( item.description2 ) delete item.description2;

        data_leveled.push( item );
    }

    data_unleveled.sort( (a, b) => {
        const weapon_type_diff = a.weapon_type - b.weapon_type;
        const special_diff = a.special - b.special;
        const name_diff = this.DgnDataFile_CompareNames( a, b );

        return weapon_type_diff || special_diff || name_diff;
    });
    data_leveled.sort( (a, b) => {
        const weapon_type_diff = a.weapon_type - b.weapon_type;
        const special_diff = a.special - b.special;
        const level_diff = a.level - b.level;
        const name_diff = this.DgnDataFile_CompareNames( a, b );

        return weapon_type_diff || special_diff || name_diff || level_diff;
    });

    return DGN.DeepCopy( data_array.concat(data_init, data_leveled, data_unleveled) );
};
