DataManager.WriteOldFormatDataFile_Items = function(data_array) {
    for ( var data of data_array ) {
        if ( !data ) continue;
        var custom_effects = data.custom_effects;

        data.note = "";

        data.note += "<dgnLevel:" + data.level + ">\n";
        if ( data.leveled_by_chapter_price == true ) data.note += "<dgnLeveledByChapterPrice>\n";
        data.note += "<dgnEquipType:" + DGN.GetNameForEquipmentType( data.equip_type ) + ">\n";
        data.note += "<dgnWeaponType:" + DGN.GetNameForWeaponType( data.weapon_type ) + ">\n";
        data.note += "<dgnArmorType:" + DGN.GetNameForArmorType( data.armor_type ) + ">\n";
        data.note += "<dgnAimAdjust:" + Math.round(data.aim_adjust) + ">\n";
        data.note += "<dgnSkillTypeName:" + data.skill_type_name + ">\n";
        if ( data.max_count != dragon_max_items )
            data.note += "<dgnMaxCount:" + data.max_count + ">\n";
        data.note += "<dgnLevelCount:" + Math.round(data.level_count) + ">\n";
        data.note += "<dgnFoodPrice:" + Math.round(data.food_price) + ">\n";
        data.note += "<dgnPriority:" + String(Math.round( data.priority * 100 ) / 100) + ">\n";
        if ( data.ranged ) data.note += "<dgnRanged>\n";
        var half_physical_auto = DGN.GetHalfPhysicalValueForSkill( DGN.GetNameForEquipmentType( data.equip_type ), DGN.GetNameForWeaponType( data.weapon_type ), DGN.GetNameForArmorType( data.armor_type ) );
        if ( data.damage.elementId == 1 ) half_physical_auto = 1;
        if ( data.half_physical == half_physical_auto )
            data.note += "<dgnHalfPhysical:auto>\n";
        else
            data.note += "<dgnHalfPhysical:" + String( Math.round(data.half_physical * 10000) / 10000 ) + ">\n";

        if ( data.treasure_type == DRAGON_TREASURE_PRIMARY_NONE ) data.note += "<dgnTreasurePrimaryNone>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_PRIMARY_COMMON ) data.note += "<dgnTreasurePrimaryCommon>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_PRIMARY_UNCOMMON ) data.note += "<dgnTreasurePrimaryUncommon>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_PRIMARY_RARE ) data.note += "<dgnTreasurePrimaryRare>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_SECONDARY_COMMON ) data.note += "<dgnTreasureSecondaryCommon>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_SECONDARY_UNCOMMON ) data.note += "<dgnTreasureSecondaryUncommon>\n";
        else if ( data.treasure_type == DRAGON_TREASURE_SECONDARY_RARE ) data.note += "<dgnTreasureSecondaryRare>\n";

        if ( data.auto_message == DRAGON_SKILL_MESSAGE_CUSTOM ) data.note += "<dgnMessageCustom>\n";
        if ( data.auto_message == DRAGON_SKILL_MESSAGE_USES ) data.note += "<dgnMessageUses>\n";
        if ( data.auto_message == DRAGON_SKILL_MESSAGE_ATTACKS ) data.note += "<dgnMessageAttacks>\n";
        if ( data.auto_message == DRAGON_SKILL_MESSAGE_ATTACKS_WITH ) data.note += "<dgnMessageAttacksWith>\n";
        if ( data.auto_message == DRAGON_SKILL_MESSAGE_CASTS ) data.note += "<dgnMessageCasts>\n";
        if ( data.message2.length > 0 ) data.note += "<dgnMessageOverride2:" + data.message2 + ">\n";

        if ( data.tpGain > 100 ) data.note += "<dgnTpGain:" + Math.round(data.tpGain) + ">\n";

        if ( custom_effects.apply_buff_magic_focus != 0 ) data.note += "<dgnEffectsBuffMagicFocus:" + Math.round(custom_effects.apply_buff_magic_focus) + ">\n";
        if ( custom_effects.apply_debuff_magic_focus != 0 ) data.note += "<dgnEffectsDebuffMagicFocus:" + Math.round(custom_effects.apply_debuff_magic_focus) + ">\n";
        if ( custom_effects.remove_buff_magic_focus == true ) data.note += "<dgnEffectsRemoveBuffMagicFocus>\n";
        if ( custom_effects.remove_debuff_magic_focus == true ) data.note += "<dgnEffectsRemoveDebuffMagicFocus>\n";
        if ( custom_effects.alter_tactical_points != 0 ) data.note += "<dgnEffectsAlterTacticalPoints:" + String(Math.round(custom_effects.alter_tactical_points * 100) / 100) + ">\n";
        if ( custom_effects.alter_magic_focus != 0 ) data.note += "<dgnEffectsAlterMagicFocus:" + Math.round(custom_effects.alter_magic_focus) + ">\n";

        if ( data.has_levels == true )
            data.note += "<dgnHasLevels>\n";

        data.note += "<dgnSpecial:" + data.special + ">\n";

        data.note += "<dgnInfo:" + data.description.AutoFormat(0) + ">\n";
        data.note += "<dgnInfo2:" + data.description2 + ">\n";

        delete data.level;
        delete data.has_levels;
        delete data.equip_type;
        delete data.weapon_type;
        delete data.armor_type;
        delete data.aim_adjust;
        delete data.skill_type_name;
        delete data.max_count;
        delete data.leveled_by_chapter_price;
        delete data.level_count;
        delete data.food_price;
        delete data.priority;
        delete data.ranged;
        delete data.half_physical;
        delete data.treasure_type;
        delete data.special;
        delete data.auto_message;

        delete data.custom_effects;
        data.description = "";
        delete data.description2;
    }

    StorageManager.SaveToJSON( "dev", "Items.json", data_array );
};
