DataManager.CheckDgnDataFilesExist = function() {
    this.dragon_custom_data_files_exist = false;

    if ( !StorageManager.exists( "DRAGON_Actors.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Classes.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Skills.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Items.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Weapons.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Armors.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_Enemies.json" ) ) return false;
    if ( !StorageManager.exists( "DRAGON_States.json" ) ) return false;

    this.dragon_custom_data_files_exist = true;
    return true;
};
DataManager.loadDatabase = function() {
    // if ( this.CheckDgnDataFilesExist() == false )
    //     console.log( "DGN Custom database files non-existant." );

    const test = this.isBattleTest() || this.isEventTest();
    const prefix = test ? "Test_" : "";
    const db_files = this.dragon_custom_data_files_exist ? this._dragon_databaseFiles : this._databaseFiles;

    for (const databaseFile of db_files) {
        this.loadDataFile(databaseFile.name, prefix + databaseFile.src);
    }
    if (this.isEventTest()) {
        this.loadDataFile("$testEvent", prefix + "Event.json");
    }
};
