        if ( data.meta.dgnEffectsRemoveBuffMagicFocus ) data.custom_effects.remove_buff_magic_focus = true;
        if ( data.meta.dgnEffectsRemoveDebuffMagicFocus ) data.custom_effects.remove_debuff_magic_focus = true;
        if ( data.meta.dgnEffectsAlterTacticalPoints ) data.custom_effects.alter_tactical_points = Number( data.meta.dgnEffectsAlterTacticalPoints );
        if ( data.meta.dgnEffectsAlterMagicFocus ) data.custom_effects.alter_magic_focus = Number( data.meta.dgnEffectsAlterMagicFocus );
