        if ($dataStates[i].meta.dgnIgnore) continue;
        if ($dataStates[i].name.length < 1) continue;
        if ($dataStates[i].name[0] === "-") continue;
        let data0 = $dataStates[i].Deep();
        let meta0 = $dataStates[i].meta.Deep();
