        if ( meta0.dgnMessage3 ) data1.message3 = String(meta0.dgnMessage3);
        if ( meta0.dgnMessage4 ) data1.message4 = String(meta0.dgnMessage4);

        if (meta0.dgnLinked) {
            let lk = {};
            const linked_txt = "lk = " + String(meta0.dgnLinked) + ";";
            try {
                eval(linked_txt);
            } catch (e) {
                console.log("Error evaluating meta tag dgnLinked for state: " + data1.id + " " + state.name + "\n" + e);
            }
            if (lk.skill) data1.resistances.skill = lk.skill;
            if (lk.element) data1.resistances.element = lk.element;
            if (lk.weapon) data1.resistances.weapon = lk.weapon;
            if (lk.race) data1.resistances.race = lk.race;
            if (lk.class) data1.resistances.class = lk.class;
        }

        if ( meta0.dgnInfo ) data1.description = String(meta0.dgnInfo);
        if ( meta0.dgnInfo2 ) data1.description2 = String(meta0.dgnInfo2);

        $dataStates[i] = data1.Deep();
