///-----------------------------------------------------------------------------
/// Window_PartyInitActor
///
/// The window for displaying a party member for the party initialization scene at the beginning of the game's playthrough.
function Window_PartyInitActor() {
    this.initialize(...arguments);
}
Window_PartyInitActor.prototype = Object.create(Window_StatusBase.prototype);
Window_PartyInitActor.prototype.constructor = Window_PartyInitActor;

Window_PartyInitActor.prototype.initialize = function(rect, party_mgr, is_pool) {
    Window_StatusBase.prototype.initialize.call(this, rect);
    this._formationMode = false;
    this._pendingIndex = -1;

    this.party_manager = party_mgr;
    this.is_pool = is_pool;
    this.last_selected = 0;

    this.refresh();
};
Window_PartyInitActor.prototype.maxItems = function() {
    if (!this.party_manager)
        return 1;

    if (this.is_pool == true)
        return this.party_manager.SizePool();
    else
        return this.party_manager.SizeParty();
};
Window_PartyInitActor.prototype.numVisibleRows = function() {
    return 6;
};
Window_PartyInitActor.prototype.maxCols = function() {
    return 1;
};
Window_PartyInitActor.prototype.itemHeight = function() {
    // return Math.floor(this.innerHeight / this.numVisibleRows());
    return 146;
};
Window_PartyInitActor.prototype.TextWidth = function() {
    // return Math.floor(this.innerHeight / this.numVisibleRows());
    return 230;
};
Window_PartyInitActor.prototype.Width = function() {
    // return Math.floor(this.innerHeight / this.numVisibleRows());
    return 146 + this.TextWidth() + 4; // 340
};
Window_PartyInitActor.prototype.actor = function(index) {
    if (!this.party_manager)
        return null;

    if (this.is_pool == true)
        return $gameActors.actor(this.party_manager.Pool()[index]);
    else
        return $gameActors.actor(this.party_manager.Party()[index]);
};
Window_PartyInitActor.prototype.drawItem = function(index) {
    const rect = this.itemRect(index);
    const actor_number = index + 1;

    this.drawPendingItemBackground(index);
    this.drawItemImage(index);
    this.drawText( actor_number, rect.x + 1, rect.y - 7, 19 );
    this.drawItemStatus(index);
};
Window_PartyInitActor.prototype.drawPendingItemBackground = function(index) {
    if (index === this._pendingIndex) {
        const rect = this.itemRect(index);
        const color = ColorManager.pendingColor();
        this.changePaintOpacity(false);
        this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        this.changePaintOpacity(true);
    }
};
Window_PartyInitActor.prototype.drawItemImage = function(index) {
    const actor = this.actor(index);
    const rect = this.itemRect(index);
    const width = ImageManager.faceWidth;
    const height = rect.height;
    this.changePaintOpacity(true);
    this.drawActorFace(actor, rect.x + 1, rect.y + 1, width, height - 2);
};
Window_PartyInitActor.prototype.drawItemStatus = function(index) {
    if (!this.party_manager)
        return;

    const actor = this.actor(index);
    const rect = this.itemRect(index);
    const x = rect.x + 148;
    const y = rect.y - 6;
    const text_width = this.TextWidth();
    const line_height = 20;
    const cls = actor.currentClass();

    let txt0 = actor.name();
    let txt1 = actor.nickname();
    let txt2 = "";
    let txt3 = "";
    let txt4 = "";
    let txt5 = "";
    let txt6 = "";
    if (this.is_pool == false) {
        if (cls.id == 1) {
            txt3 = "No Class Assigned";
            txt5 = "Please select a class";
            txt6 = "   for this character";
        } else {
            txt2 = cls.name;
            if (this.party_manager.IsPartyReady())
                txt4 = "Ready to go";
        }
    } else {
        txt2 = "No Class Assigned";
        if (this.party_manager.SizeParty() < dragon_max_starting_party_members)
            txt4 = "Available";
    }

    this.drawText( txt0, x, y, text_width );
    this.drawText( txt1, x, y + line_height, text_width );
    this.drawText( txt2, x, y + (line_height * 2), text_width );
    this.drawText( txt3, x, y + (line_height * 3), text_width );
    this.drawText( txt4, x, y + (line_height * 4), text_width );
    this.drawText( txt5, x, y + (line_height * 5), text_width );
    this.drawText( txt6, x, y + (line_height * 6), text_width );
};
Window_PartyInitActor.prototype.select = function(index) {
    this.last_selected = this.index();
    this._index = index;
    this.refreshCursor();

    if (this.party_manager)
        this.party_manager.Select(this._index, !this.is_pool);

    this.callUpdateHelp();
};
Window_PartyInitActor.prototype.processOk = function() {
    // Window_StatusBase.prototype.processOk.call(this);
    // const actor = this.actor(this.index());
    // $gameParty.setMenuActor(actor);

    this.playOkSound();
    this.updateInputData();

    if (!this.party_manager)
        return;

    if (this.is_pool == false) {
        this.party_manager.RemoveActorFromParty( this.index() );
    }
    else {
        this.party_manager.AddActorToParty( this.index() );
    }
};
Window_PartyInitActor.prototype.isCurrentItemEnabled = function() {
    return true;
};
Window_PartyInitActor.prototype.selectLast = function() {
    // this.smoothSelect($gameParty.menuActor().index() || 0);
    this.smoothSelect(this.last_selected || 0);
};
Window_PartyInitActor.prototype.formationMode = function() {
    return false;
};
Window_PartyInitActor.prototype.setFormationMode = function(formationMode) {
    this._formationMode = false;
};
Window_PartyInitActor.prototype.pendingIndex = function() {
    return this._pendingIndex;
};
Window_PartyInitActor.prototype.setPendingIndex = function(index) {
    const lastPendingIndex = this._pendingIndex;
    this._pendingIndex = index;
    this.redrawItem(this._pendingIndex);
    this.redrawItem(lastPendingIndex);
};

