Scene_Dgn_PartyInit.prototype.SetActiveWindow = function(wnd) {
    if (wnd != this.window_command) {
        this._MainCommandWindow.window_focused = false;
        this._MainCommandWindow.ClearSelection();
    } else {
        this._MainCommandWindow.window_focused = true;
    }
    if (wnd != this.window_class) {
        this._ClassSelectWindow.window_focused = false;
        this._ClassSelectWindow.ClearSelection();
    } else {
        this._ClassSelectWindow.window_focused = true;
    }
    if (wnd != this.window_party) {
        this._PartyWindow.window_focused = false;
        this._PartyWindow.ClearSelection();
    } else {
        this._PartyWindow.window_focused = true;
    }
    if (wnd != this.window_pool) {
        this._ActorPoolWindow.window_focused = false;
        this._ActorPoolWindow.ClearSelection();
    } else {
        this._ActorPoolWindow.window_focused = true;
    }
    if (wnd != this.window_info) {
        this._InfoWindow.window_focused = false;
        this._InfoWindow.ClearSelection();
    } else {
        this._InfoWindow.window_focused = true;
    }

    this._MainCommandWindow.refresh();
    this._ClassSelectWindow.refresh();
    this._PartyWindow.refresh();
    this._ActorPoolWindow.refresh();
    this._InfoWindow.refresh();

    this._MainCommandWindow.window_ready = true;
    this._ClassSelectWindow.window_ready = true;
    this._PartyWindow.window_ready = true;
    this._ActorPoolWindow.window_ready = true;
    this._InfoWindow.window_ready = true;
};
Scene_Dgn_PartyInit.prototype.EnableListFocus = function(wnd) {
    if (wnd != this.window_command) {
        this._MainCommandWindow.window_focused = false;
    } else {
        this._MainCommandWindow.window_focused = true;
    }
    if (wnd != this.window_class) {
        this._ClassSelectWindow.window_focused = false;
    } else {
        this._ClassSelectWindow.window_focused = true;
    }
    if (wnd != this.window_party) {
        this._PartyWindow.window_focused = false;
    } else {
        this._PartyWindow.window_focused = true;
    }
    if (wnd != this.window_pool) {
        this._ActorPoolWindow.window_focused = false;
    } else {
        this._ActorPoolWindow.window_focused = true;
    }
    if (wnd != this.window_info) {
        this._InfoWindow.window_focused = false;
    } else {
        this._InfoWindow.window_focused = true;
    }
};
Scene_Dgn_PartyInit.prototype.HighlightActiveActor = function(wnd) {
    const index_party = this.party_manager.PartyIndex();
    const index_pool = this.party_manager.PoolIndex();

    if (index_party > -1) this._PartyWindow.SetHighlight(index_party);
        else this._PartyWindow.ClearHighlight();
    if (index_pool > -1) this._ActorPoolWindow.SetHighlight(index_pool);
        else this._ActorPoolWindow.ClearHighlight(-1);

    this._PartyWindow.refresh();
    this._ActorPoolWindow.refresh();
};
Scene_Dgn_PartyInit.prototype.UpdateInfoWindow = function() {
    let actor_index = this.party_manager.ActorIndex() - 1;
    if (actor_index < 0) actor_index = -1;

    this._InfoWindow.Unlock();
    this._InfoWindow.select_auto( actor_index );
    this._InfoWindow.Lock();

    if ( this._InfoWindow.Focused() )
        this._InfoWindow.HoldCursor(false);
    else
        this._InfoWindow.HoldCursor(true);

    this._InfoWindow.refresh();
};
Scene_Dgn_PartyInit.prototype.ChildToParentMessage = function(message_id, index, direction, window_name) {
    if (!this.not_busy)
        return;

    // console.log ( window_name, message_id, index, direction );
    if (index < 0) return;

    this.not_busy = false;

    /// Command List
    if (message_id == this.id_message_code_CommandList.window_focused) {
        this.SetActiveWindow(this.window_command);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_CommandList.item_activated) {
        if (index == 0) {
            if ( this.party_manager.IsPartyReady() ) {
                let party = this.party_manager.Party();
                for (const actr of party)
                    $gameParty.addActor(actr);

                /*
                const item = DGN.GetWeaponID(1, "shotgun", "Pump-Action");
                if (item)
                    $gameParty.gainItem(item, dragon_max_starting_party_members * 5, false);
                */

                $gameParty.SetGold( dragon_starting_gp );
                $gameParty.SetSilver( dragon_starting_sp );
                $gameParty.SetCopper( dragon_starting_cp );

                for (const actr of $gameParty.members()) {
                    // if (item) actr.forceChangeEquip( 0, item );

                    actr.recoverAll();
                }

                $gameParty.InitMemberInventories();

                this.fadeOutAll();
                SceneManager.goto(Scene_Map);

                this.not_busy = true;
                return;
            }
        }
        else if (index == 1) {
            this.party_manager.Reset();
            this._PartyWindow.data = this.party_manager.DataParty();
            this._ActorPoolWindow.data = this.party_manager.DataPool();
        }
        else if (index == 2) {
            this.fadeOutAll();
            SceneManager.goto(Scene_Title);
            Window_TitleCommand.initCommandPosition();

            this.not_busy = true;
            return;
        }
        else if (index == 3) {
            const idx = this.party_manager.PoolIndex();
            this.party_manager.AddActorToParty(idx);
            this._PartyWindow.data = this.party_manager.DataParty();
            this._ActorPoolWindow.data = this.party_manager.DataPool();
        }
        else if (index == 4) {
            const idx = this.party_manager.PartyIndex();
            this.party_manager.RemoveActorFromParty(idx);
            this._PartyWindow.data = this.party_manager.DataParty();
            this._ActorPoolWindow.data = this.party_manager.DataPool();
        }
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_CommandList.item_focused) {
    }
    else if (message_id == this.id_message_code_CommandList.item_unfocused) {
    }
    else if (message_id == this.id_message_code_CommandList.exit) {
        this._InfoWindow.CycleDataPage(0);
        this.party_manager.Select(-1, false);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_CommandList.border_wrap) {
        if (direction == this._MainCommandWindow.left) {
            this.SetActiveWindow(this.window_party);
            this._PartyWindow.select_auto(0);
            this._PartyWindow.ensureCursorVisible(true);
        }
        else if (direction == this._MainCommandWindow.right) {
            this.SetActiveWindow(this.window_class);
            this._ClassSelectWindow.select_auto(0);
            this._ClassSelectWindow.ensureCursorVisible(true);
        }
        else if (direction == this._MainCommandWindow.up) {
            this.SetActiveWindow(this.window_command);
            this._MainCommandWindow.select_auto(0);
        }
        else if (direction == this._MainCommandWindow.down) {
            this.SetActiveWindow(this.window_info);
            this._InfoWindow.select_auto(0);
        }
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
        this.not_busy = true;
        return;
    }

    /// Class Selection List
    else if (message_id == this.id_message_code_ClassList.window_focused) {
        this.SetActiveWindow(this.window_class);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_ClassList.item_activated) {
        const data = this.class_list[index];
        const cls_id = data[0];
        let actor = this.party_manager.Actor();
        if (actor)
            actor.changeClass(cls_id, false);
        this.party_manager.UpdateData();
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_ClassList.item_focused) {
        this.SetActiveWindow(this.window_class);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_ClassList.item_unfocused) {
    }
    else if (message_id == this.id_message_code_ClassList.exit) {
        this.party_manager.Select(-1, false);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_ClassList.border_wrap) {
        if (direction == this._ClassSelectWindow.left) {
            this.SetActiveWindow(this.window_command);
            this._MainCommandWindow.select_auto(0);
        }
        else if (direction == this._ClassSelectWindow.right) {
            this.SetActiveWindow(this.window_pool);
            this._ActorPoolWindow.select_auto(0);
            this._ActorPoolWindow.ensureCursorVisible(true);
        }
        else if (direction == this._ClassSelectWindow.up) {
            this.SetActiveWindow(this.window_class);
            this._ClassSelectWindow.select_auto(0);
        }
        else if (direction == this._ClassSelectWindow.down) {
            this.SetActiveWindow(this.window_info);
            this._InfoWindow.select_auto(0);
        }
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
        this.not_busy = true;
        return;
    }

    /// Party Member List
    else if (message_id == this.id_message_code_PartyMembers.window_focused) {
        this.SetActiveWindow(this.window_party);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PartyMembers.item_activated) {
        const index_old = this.party_manager.PartyIndex();

        if (index_old == index) {
            this.party_manager.Select(-1, true);
            this.HighlightActiveActor();
            this.UpdateInfoWindow();

            this.not_busy = true;
            return;
        }

        this.party_manager.Select(index, true);
        this.SetActiveWindow(this.window_party);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PartyMembers.item_focused) {
        this.SetActiveWindow(this.window_party);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PartyMembers.item_unfocused) {
    }
    else if (message_id == this.id_message_code_PartyMembers.exit) {
        this._InfoWindow.CycleDataPage(0);
        this.party_manager.Select(-1, false);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PartyMembers.border_wrap) {
        if (direction == this._PartyWindow.right) {
            this.SetActiveWindow(this.window_command);
            this._MainCommandWindow.select_auto(0);
        } else
            this.SetActiveWindow(this.window_party);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
        this.not_busy = true;
        return;
    }

    /// Party Member Pool
    else if (message_id == this.id_message_code_PoolMembers.window_focused) {
        this.SetActiveWindow(this.window_pool);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PoolMembers.item_activated) {
        const index_old = this.party_manager.PoolIndex();
        if (index_old == index) {
            this.party_manager.Select(-1, false);
            this.HighlightActiveActor();
            this.UpdateInfoWindow();

            this.not_busy = true;
            return;
        }
        this.party_manager.Select(index, false);
        this.SetActiveWindow(this.window_pool);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PoolMembers.item_focused) {
        this.SetActiveWindow(this.window_pool);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PoolMembers.item_unfocused) {
    }
    else if (message_id == this.id_message_code_PoolMembers.exit) {
        this._InfoWindow.CycleDataPage(0);
        this.party_manager.Select(-1, false);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_PoolMembers.border_wrap) {
        if (direction == this._ActorPoolWindow.left) {
            this.SetActiveWindow(this.window_class);
            this._ClassSelectWindow.select_auto(0);
            this._ClassSelectWindow.ensureCursorVisible(true);
        } else
            this.SetActiveWindow(this.window_pool);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
        this.not_busy = true;
        return;
    }

    /// Actor Info Window
    else if (message_id == this.id_message_code_Info.window_focused) {
        this.SetActiveWindow(this.window_info);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_Info.item_activated) {
        this.SetActiveWindow(this.window_info);
        this._InfoWindow.CycleDataPage();
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_Info.item_focused) {
        this.SetActiveWindow(this.window_info);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_Info.item_unfocused) {
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_Info.exit) {
        this.SetActiveWindow(this.window_info);
        this._InfoWindow.CycleDataPage(0);
        this.party_manager.Select(-1, false);
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
    }
    else if (message_id == this.id_message_code_Info.border_wrap) {
        if (direction == this._InfoWindow.left) {
            this.SetActiveWindow(this.window_party);
            this._PartyWindow.select_auto(0);
            this._PartyWindow.ensureCursorVisible(true);
        }
        else if (direction == this._InfoWindow.right) {
            this.SetActiveWindow(this.window_pool);
            this._ActorPoolWindow.select_auto(0);
            this._ActorPoolWindow.ensureCursorVisible(true);
        }
        else if (direction == this._InfoWindow.up) {
            this.SetActiveWindow(this.window_command);
            this._MainCommandWindow.select_auto(this.command_list.length - 1);
        }
        this.HighlightActiveActor();
        this.UpdateInfoWindow();
        this.not_busy = true;
        return;
    }

    else {
        console.log("Warning: Action List Child-to-Parent function in Party Initialization Start Scene called with unknown ID.\n" +
                    "message_id: " + String(message_id) + "\n" + "index: " + index + "\n" + "direction: " + direction);
    }

    this.not_busy = true;
};
Scene_Dgn_PartyInit.prototype.ShowAllWindows = function() {
        this._PartyWindow.show();
        this._ActorPoolWindow.show();
        this._MainCommandWindow.show();
        this._ClassSelectWindow.show();
        this._InfoWindow.show();
};
Scene_Dgn_PartyInit.prototype.needsPageButtons = function() {
    return true;
};
Scene_Dgn_PartyInit.prototype.arePageButtonsEnabled = function() {
    return ( this._PartyWindow.active || this._ActorPoolWindow.active || this._ClassSelectWindow.active ||
            this._InfoWindow.active );
};

