// const alias_DRAGON_Scene_Boot_start = Scene_Boot.prototype.start;
Scene_Boot.prototype.start = function() {
    Scene_Base.prototype.start.call(this);
    SoundManager.preloadImportantSounds();

    // this.CustomDgn();

    if (DataManager.isBattleTest()) {
        DataManager.setupBattleTest();
        SceneManager.goto(Scene_Dgn_PartySelection);
        // SceneManager.goto(Scene_Battle);
    } else if (DataManager.isEventTest()) {
        DataManager.setupEventTest();
        SceneManager.goto(Scene_Map);
    } else if (DataManager.isTitleSkip()) {
        this.checkPlayerLocation();
        DataManager.setupNewGame();
        SceneManager.goto(Scene_Map);
    } else {
        this.startNormalGame();
        SceneManager.goto(Scene_Dgn_PartySelection);
    }
    this.resizeScreen();
    this.updateDocumentTitle();

    // Graphics._requestFullScreen();

	// alias_DRAGON_Scene_Boot_start.apply(this, arguments);
    // this.CustomDgn();
};
Scene_Boot.prototype.resizeScreen = function() {
    const screenWidth = $dataSystem.advanced.screenWidth;
    const screenHeight = $dataSystem.advanced.screenHeight;
    Graphics.resize(screenWidth, screenHeight);
    Graphics.defaultScale = this.screenScale();
    this.adjustBoxSize();
    // this.adjustWindow();

    // Graphics._requestFullScreen();
};
