Scene_Boot.prototype.CustomDgnInitDatabase_Races = function() {
    $dataRaces = [];

    for (let i = 1; i < $dataClasses.length; i++) {
        if (!$dataClasses[i]) continue;
        if (!$dataClasses[i].meta) continue;
        if ($dataClasses[i].meta.dgnIgnore) continue;
        if (!$dataClasses[i].meta.dgnActorRace) continue;
        const data = $dataClasses[i].Deep();
        const meta = data.meta.Deep();
        let race0 = data.Deep();
        delete race0.expParams;
        delete race0.params;
        race0.id = $dataRaces.length;
        race0.name = "None";
        race0.race = Game_BattlerBase.RACE_NONE;
        race0.enable_sub_type = [];
        race0.custom_traits = {};
        race0.inventory_slots = [];
        race0.blocked_inventory_slots = [];
        race0.extra_actions_leveled = [];
        race0.extra_actions_bonus = [];
        race0.xp_base = 1.0;
        race0.xp_add = 1.0;
        race0.info = "";
        race0.info2 = "";
        race0.info3 = "";
        race0.info4 = "";
        race0.info5 = "";

        let race1 = DGN.SetCustomTraitsFromMeta(race0);
        let ctraits = race1.custom_traits;
        race1.race = DGN.GetRaceFromText(race1.name);

        const error_text = " for character race: " + race1.name + ", ID: " + race1.id + ".\n";
        if (meta.dgnInvSlots) {
            try {
                race1.inventory_slots = JSON.parse(meta.dgnInvSlots);
            } catch (e) {
                console.log("Error: Unable to parse inventory slots" + error_text + e);
            };
        }
        if (meta.dgnInvSlotsBlocked) {
            try {
                race1.blocked_inventory_slots = JSON.parse(meta.dgnInvSlotsBlocked);
            } catch (e) {
                console.log("Error: Unable to parse blocked inventory slots" + error_text + e);
            };
        }
        if (meta.dgnEnableSubType) {
            try {
                const value = String(meta.dgnEnableSubType);
                race1.enable_sub_type = eval(value);
            } catch (e) {
                console.log("Error: Unable to parse ENABLE SUB TYPE" + error_text + e);
            };
        }

        if ( meta.dgnActionsPerTurnByLevel ) {
            let data_array = [];
            try {
                data_array = JSON.parse( meta.dgnActionsPerTurnByLevel );
            } catch (e) {
                console.log("ERROR: Unable to parse data for calculating actions per combat turn" + error_text + e);
                data_array = [];
            }
            if (data_array.length >= 3) {
                if ( Math.round(data_array.length % 3) > 0 ) {
                    console.log("ERROR: Unable to parse data for calculating actions per combat turn" + error_text);
                }
                else {
                    for (let d = 0; d < data_array.length; d += 3) {
                        race1.extra_actions_leveled.push( [data_array[d], data_array[d+1], data_array[d+2]] );
                    }
                }
            }
        }
        if ( meta.dgnActionsPerTurnBonus ) {
            let data_array = [];
            try {
                data_array = JSON.parse( meta.dgnActionsPerTurnBonus );
            } catch (e) {
                console.log("ERROR: Unable to parse data for calculating actions per combat turn" + error_text + e);
                data_array = [];
            }
            if (data_array.length >= 3) {
                if ( Math.round(data_array.length % 3) > 0 ) {
                    console.log("ERROR: Unable to parse data for calculating actions per combat turn" + error_text);
                }
                else {
                    for (let d = 0; d < data_array.length; d += 3) {
                        race1.extra_actions_bonus.push( [data_array[d], data_array[d+1], data_array[d+2]] );
                    }
                }
            }
        }
        /*
        if (meta.dgnInvSlots) {
            try {
                race1.inventory_slots = JSON.parse(meta.dgnInvSlots);
            } catch (e) {
                console.log("Error: Unable to parse inventory slots for character race: " + race1.name + ".\n" + e);
            };
        }
        if (meta.dgnInvSlotsBlocked) {
            try {
                race1.blocked_inventory_slots = JSON.parse(meta.dgnInvSlotsBlocked);
            } catch (e) {
                console.log("Error: Unable to parse blocked inventory slots for character race: " + race1.name + ".\n" + e);
            };
        }
        */

        if ( meta.dgnExpBase ) race1.xp_base = Number(meta.dgnExpBase);
        if ( meta.dgnExpAdd ) race1.xp_add = Number(meta.dgnExpAdd);

        if (meta.dgnInfo) race1.info = String(meta.dgnInfo);
        if (meta.dgnInfo2) race1.info2 = String(meta.dgnInfo2);
        if (meta.dgnInfo3) race1.info3 = String(meta.dgnInfo3);
        if (meta.dgnInfo4) race1.info4 = String(meta.dgnInfo4);
        if (meta.dgnInfo5) race1.info5 = String(meta.dgnInfo5);

        $dataRaces.push( race1.Deep() );
    }

    // console.log($dataRaces);
};
Scene_Boot.prototype.CustomDgnStripMetaTags = function() {
    const actors_size = $dataActors.length;
    const enemies_size = $dataEnemies.length;
    const classes_size = $dataClasses.length;
    const weapons_size = $dataWeapons.length;
    const armors_size = $dataArmors.length;
    const items_size = $dataItems.length;
    const skills_size = $dataSkills.length;
    const states_size = $dataStates.length;

    /*
    for ( let i = 1; i < actors_size; i++ ) {
        delete $dataActors[i].meta;
        $dataActors[i].note = "";
    }
    */
    for ( let i = 1; i < enemies_size; i++ ) {
        delete $dataEnemies[i].meta;
        $dataEnemies[i].note = "";
    }
    /*
    for ( let i = 1; i < classes_size; i++ ) {
        delete $dataClasses[i].meta;
        $dataClasses[i].note = "";
    }
    for ( let i = 1; i < weapons_size; i++ ) {
        delete $dataWeapons[i].meta;
        $dataWeapons[i].note = "";
    }
    for ( let i = 1; i < armors_size; i++ ) {
        delete $dataArmors[i].meta;
        $dataArmors[i].note = "";
    }

    for ( let i = 1; i < items_size; i++ ) {
        delete $dataItems[i].meta;
        $dataItems[i].note = "";
    }
    */
    for ( let i = 1; i < skills_size; i++ ) {
        if (!$dataSkills[i]) continue;

        let new_note = "";
        if ($dataSkills[i].meta) {
            if ($dataSkills[i].meta.dgnEnemySkill) new_note += "<dgnEnemySkill>";
            if ($dataSkills[i].meta.dgnSpecialSkill) new_note += "<dgnSpecialSkill>";
            if ($dataSkills[i].meta.dgnUnarmedCombat) new_note += "<dgnUnarmedCombat>";
            if ($dataSkills[i].meta.dgnMiscellaneous) new_note += "<dgnMiscellaneous>";
            if ($dataSkills[i].meta.dgnInnate) new_note += "<dgnInnate>";
        }

        delete $dataSkills[i].meta;
        $dataSkills[i].note = new_note;
    }
    for ( let i = 1; i < states_size; i++ ) {
        delete $dataStates[i].meta;
        $dataStates[i].note = "";
    }
};
