Scene_Boot.prototype.CustomDgnReorderAnimations = function() {
    if (!dragon_write_new_animations_database) return;

    const category_check = (d) => dragon_animations_specific_spaced_categories.includes(d);

    const blanks = $dataAnimations.filter( anim => anim && anim.name.length < 1 );
    if (blanks.length < 1) return;

    const blank_animation = blanks[0].Deep();
    let new_anims = [];
    new_anims.push( null );

    let spacing = 0;
    for ( let i = 1; i < $dataAnimations.length; i++ ) {
        if (!$dataAnimations[i]) continue;
        if ($dataAnimations[i].name.length < 1) continue;
        const data = $dataAnimations[i];

        if (data.name[0] === "-") {
            for (s = 0; s < spacing; s++) new_anims.push( blank_animation.Deep() );
            for (let b = 0; b < dragon_number_blank_skills_per_category; b++) new_anims.push( blank_animation.Deep() );

            new_anims.push( data.Deep() );

            if (category_check(data.name))
                spacing = dragon_number_blank_animations_specific_categories;
            else
                spacing = 0;

            continue;
        }

        for (s = 0; s < spacing; s++) new_anims.push( blank_animation.Deep() );
        new_anims.push( data.Deep() );
    }

    const anims = new_anims.map( anim => anim ? anim.id : 0 );

    for (let dat of $dataSkills) {
        if (dat) dat.animationId = anims.indexOf(dat.animationId);
    }
    for (let dat of $dataItems) {
        if (dat) dat.animationId = anims.indexOf(dat.animationId);
    }
    for (let dat of $dataWeapons) {
        if (dat) dat.animationId = anims.indexOf(dat.animationId);
    }

    for (let i = 1; i < new_anims.length; i++) new_anims.id = i;
    $dataAnimations = new_anims;

    StorageManager.SaveToJSON( "dev", "System.json", $dataSystem );
    StorageManager.SaveToJSON( "dev", "Animations.json", $dataAnimations );
    StorageManager.SaveToJSON( "dev", "Actors.json", $dataActors );
    StorageManager.SaveToJSON( "dev", "Classes.json", $dataClasses );
    StorageManager.SaveToJSON( "dev", "Enemies.json", $dataEnemies );
    StorageManager.SaveToJSON( "dev", "Weapons.json", $dataWeapons );
    StorageManager.SaveToJSON( "dev", "Armors.json", $dataArmors );
    StorageManager.SaveToJSON( "dev", "Items.json", $dataItems );
    StorageManager.SaveToJSON( "dev", "Skills.json", $dataSkills );
    StorageManager.SaveToJSON( "dev", "States.json", $dataStates );
};
