///-----------------------------------------------------------------------------
/// Scene_Dgn_PartySelection
///
/// The scene class for choosing the initial party members and their classes.
function Scene_Dgn_PartySelection() {
    this.initialize(...arguments);
}
Scene_Dgn_PartySelection.prototype = Object.create(Scene_MenuBase.prototype);
Scene_Dgn_PartySelection.prototype.constructor = Scene_Dgn_PartySelection;
Scene_Dgn_PartySelection.prototype.initialize = function() {
    Scene_MenuBase.prototype.initialize.call(this);

    this.rect_MainCommandWindow = null;
    this.rect_PartyWindow = null;
    this.rect_ActorPoolWindow = null;
    this.rect_ClassSelectWindow = null;
    this.rect_InfoWindow = null;

    this._MainCommandWindow = null;
    this._ClassSelectWindow = null;
    this._PartyWindow = null;
    this._ActorPoolWindow = null;
    this._InfoWindow = null;

    this.party_manager = null;

    this._cheats = DataManager.isBattleTest() ? true : false;
    if ($gameSystem.cheats_enabled === true) this._cheats = true;
};
Scene_Dgn_PartySelection.prototype.create = function() {
    Scene_MenuBase.prototype.create.call(this);

    // this.party_manager = new dgnInitParty();
    $gameParty.Reset();
    $gameParty.HealPartyAll();

    this.CreateWindowRects();
    this.CreateWindows();

    this._MainCommandWindow.activate();
    this._MainCommandWindow.select(0);
};
Scene_Dgn_PartySelection.prototype.CreateWindowRects = function() {
    const list_item_height = 38;
    const list_border_height = 20;
    const full_screen_rect = new Rectangle(0, 0, Graphics.boxWidth, Graphics.boxHeight);

    {
        const ww = Graphics.boxWidth;
        const wh = (list_item_height * 2) + list_border_height;
        const wx = 0;
        const wy = Graphics.boxHeight - wh;
        this.rect_MainCommandWindow = new Rectangle(wx, wy, ww, wh);
    }
    {
        const ww = Graphics.boxWidth;
        const wh = Graphics.boxHeight - this.rect_MainCommandWindow.height;
        const wx = 0;
        const wy = 0;
        this.rect_PartyWindow = new Rectangle(wx, wy, ww, wh);
    }
    this.rect_ActorPoolWindow = full_screen_rect;
    this.rect_ClassSelectWindow = full_screen_rect;
    this.rect_InfoWindow = full_screen_rect;
};
Scene_Dgn_PartySelection.prototype.CreateWindows = function() {
    this._PartyWindow = new Window_Dgn_PartySelection_Party(this.rect_PartyWindow);
    this._PartyWindow.setHandler("ok", this.onPartyWindowSelectItem.bind(this));
    this._PartyWindow.setHandler("cancel", this.onPartyWindowExit.bind(this));
    this.addWindow(this._PartyWindow);

    this._MainCommandWindow = new Window_Dgn_PartySelection_Command(this.rect_MainCommandWindow, this._cheats);
    this._MainCommandWindow.setHandler("ok", this.onCommandSelect.bind(this));
    this.addWindow(this._MainCommandWindow);

    this._ActorPoolWindow = new Window_Dgn_PartySelection_Pool(this.rect_ActorPoolWindow);
    this._ActorPoolWindow.setHandler("ok", this.onPoolWindowSelectItem.bind(this));
    this._ActorPoolWindow.setHandler("cancel", this.onPoolWindowExit.bind(this));
    this.addWindow(this._ActorPoolWindow);
    this._ActorPoolWindow.hide();

    this._InfoWindow = new Window_Dgn_ItemInfo(this.rect_InfoWindow);
    this._InfoWindow.setHandler("ok", this.onInfoWindowOk.bind(this));
    this._InfoWindow.setHandler("cancel", this.onInfoWindowCancel.bind(this));
    this._InfoWindow.setHandler("pageup", this.onInfoWindowPrevious.bind(this));
    this._InfoWindow.setHandler("left", this.onInfoWindowPrevious.bind(this));
    this._InfoWindow.setHandler("pagedown", this.onInfoWindowNext.bind(this));
    this._InfoWindow.setHandler("right", this.onInfoWindowNext.bind(this));
    this._InfoWindow.SetTextCommand("actor, init");
    this.addWindow(this._InfoWindow);
    this._InfoWindow.hide();
};
/*
Window_Dgn_PartySelection_Command.prototype.makeItemList = function() {
    this._data = ["Start", "Character Info", "Add Party Member", "Remove Party Member", "Choose Class"];
    if (this._cheats === true) {
        this._data.push("Set EXP");
        this._data.push("Auto Equip Party");
    }
};
*/
Scene_Dgn_PartySelection.prototype.activatePartyWindow = function() {
    if ($gameParty.size() < 1) {
        this._PartyWindow.deselect();
        this._MainCommandWindow.activate();
        this._MainCommandWindow.selectLast();
        return;
    }
    this._PartyWindow.activate();
    this._PartyWindow.selectLast();
};
Scene_Dgn_PartySelection.prototype.activatePoolWindow = function() {
    this._MainCommandWindow.deactivate();
    this._PartyWindow.deactivate();
    this._ActorPoolWindow.show();
    this._ActorPoolWindow.activate();
    this._ActorPoolWindow.refresh();
    this._ActorPoolWindow.selectLast();
};
Scene_Dgn_PartySelection.prototype.onCommandSelect = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Start") {
        if ($gameParty.members().some(actor => actor.currentClass().name === "Not Set")) {
            SoundManager.playBuzzer();
            this._MainCommandWindow.activate();
            return;
        }
        if (DataManager.isBattleTest())
            SceneManager.goto(Scene_Battle);
        else
            SceneManager.goto(Scene_Map);
    }
    else if (cmd === "Character Info") {
        this.activatePartyWindow();
    }
    else if (cmd === "Add Party Member") {
        if ($gameParty.size() < dragon_max_starting_party_members)
            this.activatePoolWindow();
        else {
            SoundManager.playBuzzer();
            this._MainCommandWindow.activate();
        }
    }
    else if (cmd === "Remove Party Member") {
        this.activatePartyWindow();
    }
    else if (cmd === "Choose Class") {
        this.activatePartyWindow();
    }
    else if (cmd === "Set EXP") {
        this._MainCommandWindow.activate();
    }
    else if (cmd === "Auto Equip Party") {
        this._MainCommandWindow.activate();
        SoundManager.playEquip();
    }
};
Scene_Dgn_PartySelection.prototype.onPartyWindowSelectItem = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Character Info") {
        if (!this._PartyWindow.item()) {
            this._PartyWindow.activate();
            return;
        }
        this._PartyWindow.deactivate();
        this._InfoWindow.SetTextCommand("actor, init");
        this._InfoWindow.SetActor(this._PartyWindow.item());
        this._InfoWindow.show();
        this._InfoWindow.activate();
        this._InfoWindow.select(-1);
        this._InfoWindow.refresh();
    }
    else if (cmd === "Remove Party Member") {
        const actor_to_remove = this._PartyWindow.item().actorId();
        $gameParty.removeActor(actor_to_remove);
        this._PartyWindow.deactivate();
        this._PartyWindow.refresh();
        this._MainCommandWindow.activate();
        this._MainCommandWindow.selectLast();
    }
    else if (cmd === "Choose Class") {
    }
};
Scene_Dgn_PartySelection.prototype.onPartyWindowExit = function() {
    this._PartyWindow.deactivate();
    this._MainCommandWindow.activate();
    this._MainCommandWindow.selectLast();
};
Scene_Dgn_PartySelection.prototype.onPoolWindowSelectItem = function() {
    this._ActorPoolWindow.deactivate();
    this._InfoWindow.SetTextCommand("actor, pool");
    this._InfoWindow.SetActor(this._ActorPoolWindow.item());
    this._InfoWindow.show();
    this._InfoWindow.activate();
    this._InfoWindow.select(-1);
    this._InfoWindow.refresh();
};
Scene_Dgn_PartySelection.prototype.onPoolWindowExit = function() {
    this._ActorPoolWindow.deactivate();
    this._ActorPoolWindow.hide();
    this._MainCommandWindow.activate();
    this._MainCommandWindow.selectLast();
};
Scene_Dgn_PartySelection.prototype.onInfoWindowOk = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Character Info") {
        this._InfoWindow.deactivate();
        this._InfoWindow.hide();
        this._PartyWindow.activate();
        this._PartyWindow.selectLast();
    }
    else if (cmd === "Add Party Member") {
        const actor_to_add = this._ActorPoolWindow.item().actorId();
        this._InfoWindow.deactivate();
        this._InfoWindow.hide();
        this._ActorPoolWindow.deactivate();
        this._ActorPoolWindow.hide();
        $gameParty.addActor(actor_to_add);
        this._ActorPoolWindow.refresh();
        this._PartyWindow.refresh();
        this._MainCommandWindow.activate();
        this._MainCommandWindow.selectLast();
    }
};
Scene_Dgn_PartySelection.prototype.onInfoWindowCancel = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Character Info") {
        this._InfoWindow.deactivate();
        this._InfoWindow.hide();
        this._PartyWindow.activate();
        this._PartyWindow.selectLast();
    }
    else if (cmd === "Add Party Member") {
        this._InfoWindow.deactivate();
        this._InfoWindow.hide();
        this._ActorPoolWindow.activate();
        this._ActorPoolWindow.refresh();
        this._ActorPoolWindow.selectLast();
    }
};
Scene_Dgn_PartySelection.prototype.onInfoWindowPrevious = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Character Info") {
        this._InfoWindow.deactivate();
        this._PartyWindow.activate();
        this._PartyWindow.selectPrevious();
        this._PartyWindow.deactivate();
        this._InfoWindow.activate();
        this._InfoWindow.SetTextCommand("actor, init");
        this._InfoWindow.SetActor(this._PartyWindow.item());
        this._InfoWindow.select(-1);
        this._InfoWindow.refresh();
    }
    else if (cmd === "Add Party Member") {
        this._InfoWindow.deactivate();
        this._ActorPoolWindow.activate();
        this._ActorPoolWindow.selectPrevious();
        this._ActorPoolWindow.deactivate();
        this._InfoWindow.activate();
        this._InfoWindow.SetTextCommand("actor, pool");
        this._InfoWindow.SetActor(this._ActorPoolWindow.item());
        this._InfoWindow.select(-1);
        this._InfoWindow.refresh();
    }
};
Scene_Dgn_PartySelection.prototype.onInfoWindowNext = function() {
    const cmd = this._MainCommandWindow.item();
    if (cmd === "Character Info") {
        this._InfoWindow.deactivate();
        this._PartyWindow.activate();
        this._PartyWindow.selectNext();
        this._PartyWindow.deactivate();
        this._InfoWindow.activate();
        this._InfoWindow.SetTextCommand("actor, init");
        this._InfoWindow.SetActor(this._PartyWindow.item());
        this._InfoWindow.select(-1);
        this._InfoWindow.refresh();
    }
    else if (cmd === "Add Party Member") {
        this._InfoWindow.deactivate();
        this._ActorPoolWindow.activate();
        this._ActorPoolWindow.selectNext();
        this._ActorPoolWindow.deactivate();
        this._InfoWindow.activate();
        this._InfoWindow.SetTextCommand("actor, pool");
        this._InfoWindow.SetActor(this._ActorPoolWindow.item());
        this._InfoWindow.select(-1);
        this._InfoWindow.refresh();
    }
};
